INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/skill-stocktake', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'skill-stocktake', 61988, 7678, 80, '2026-03-06T03:39:20Z', '2026-03-06T04:34:27.118Z', '7b0b982d8d0c60ead792d7befe1b4ef8890543cba931132a7618730d9987b246', '{"id":"affaan-m/everything-claude-code/skill-stocktake","name":"skill-stocktake","description":{"en":"The skill-stocktake slash command performs quality audits on Claude skills and commands using a checklist and AI evaluation. It benefits developers and AI agent builders working with Claude Code and MCP by scanning both global and project-level skill directories.","zh":"skill-stocktake是一个用于审计Claude技能和命令的工具，支持Quick Scan和Full Stocktake两种模式","ja":"skill-stocktakeはClaudeスキルとコマンドの品質をAuditするツールで、Quick ScanとFull Stocktakeの2つのモードをサポート","ko":"skill-stocktake는 클라우드 스킬과 명령의 품질을 감사하는 도구로, 빠른 스캔과 전체盤点 두 가지 모드를 지원","es":"Skill-stocktake es una herramienta de auditoría para evaluar la calidad de las habilidades y comandos de Claude. Soporta modos de exploración rápida y completa.","fr":"Skill-stocktake est un outil d''audit pour évaluer la qualité des compétences et des commandes de Claude. Il prend en charge les modes de balayage rapide et complet.","de":"Skill-stocktake ist ein Audit-Tool, um die Qualität von Claude-Fähigkeiten und -Befehlen zu bewerten. Es unterstützt die Modi Quick Scan und Full Stocktake.","pt":"O skill-stocktake é uma ferramenta de auditoria de qualidade para skills e comandos do Claude, com suporte a Quick Scan e Full Stocktake.","ru":"Skill-stocktake - это инструмент для аудита качества навыков и команд Claude, поддерживающий Quick Scan и Full Stocktake.","ar":"مرشد skill-stocktake هو أداة تدقيق الجودة لمهارات وأوامر Claude، يدعم Quick Scan و Full Stocktake."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"","description":"Use when auditing Claude skills and commands for quality. Supports Quick Scan (changed skills only) and Full Stocktake modes with sequential subagent batch evaluation.","bodyPreview":"# skill-stocktake\n\nSlash command (`/skill-stocktake`) that audits all Claude skills and commands using a quality checklist + AI holistic judgment. Supports two modes: Quick Scan for recently changed skills, and Full Stocktake for a complete review.\n\n## Scope\n\nThe command targets the following paths **relative to the directory where it is invoked**:\n\n| Path | Description |\n|------|-------------|\n| `~/.claude/skills/` | Global skills (all projects) |\n| `{cwd}/.claude/skills/` | Project-level skill","body":"# skill-stocktake\n\nSlash command (`/skill-stocktake`) that audits all Claude skills and commands using a quality checklist + AI holistic judgment. Supports two modes: Quick Scan for recently changed skills, and Full Stocktake for a complete review.\n\n## Scope\n\nThe command targets the following paths **relative to the directory where it is invoked**:\n\n| Path | Description |\n|------|-------------|\n| `~/.claude/skills/` | Global skills (all projects) |\n| `{cwd}/.claude/skills/` | Project-level skills (if the directory exists) |\n\n**At the start of Phase 1, the command explicitly lists which paths were found and scanned.**\n\n### Targeting a specific project\n\nTo include project-level skills, run from that project''s root directory:\n\n```bash\ncd ~/path/to/my-project\n/skill-stocktake\n```\n\nIf the project has no `.claude/skills/` directory, only global skills and commands are evaluated.\n\n## Modes\n\n| Mode | Trigger | Duration |\n|------|---------|---------|\n| Quick Scan | `results.json` exists (default) | 5–10 min |\n| Full Stocktake | `results.json` absent, or `/skill-stocktake full` | 20–30 min |\n\n**Results cache:** `~/.claude/skills/skill-stocktake/results.json`\n\n## Quick Scan Flow\n\nRe-evaluate only skills that have changed since the last run (5–10 min).\n\n1. Read `~/.claude/skills/skill-stocktake/results.json`\n2. Run: `bash ~/.claude/skills/skill-stocktake/scripts/quick-diff.sh \\\n         ~/.claude/skills/skill-stocktake/results.json`\n   (Project dir is auto-detected from `$PWD/.claude/skills`; pass it explicitly only if needed)\n3. If output is `[]`: report \"No changes since last run.\" and stop\n4. Re-evaluate only those changed files using the same Phase 2 criteria\n5. Carry forward unchanged skills from previous results\n6. Output only the diff\n7. Run: `bash ~/.claude/skills/skill-stocktake/scripts/save-results.sh \\\n         ~/.claude/skills/skill-stocktake/results.json <<< \"$EVAL_RESULTS\"`\n\n## Full Stocktake Flow\n\n### Phase 1 — Inventory\n\nRun: `bash ~/.claude/skills/skill-stocktake/scripts/scan.sh`\n\nThe script enumerates skill files, extracts frontmatter, and collects UTC mtimes.\nProject dir is auto-detected from `$PWD/.claude/skills`; pass it explicitly only if needed.\nPresent the scan summary and inventory table from the script output:\n\n```\nScanning:\n  ✓ ~/.claude/skills/         (17 files)\n  ✗ {cwd}/.claude/skills/    (not found — global skills only)\n```\n\n| Skill | 7d use | 30d use | Description |\n|-------|--------|---------|-------------|\n\n### Phase 2 — Quality Evaluation\n\nLaunch a Task tool subagent (**Explore agent, model: opus**) with the full inventory and checklist.\nThe subagent reads each skill, applies the checklist, and returns per-skill JSON:\n\n`{ \"verdict\": \"Keep\"|\"Improve\"|\"Update\"|\"Retire\"|\"Merge into [X]\", \"reason\": \"...\" }`\n\n**Chunk guidance:** Process ~20 skills per subagent invocation to keep context manageable. Save intermediate results to `results.json` (`status: \"in_progress\"`) after each chunk.\n\nAfter all skills are evaluated: set `status: \"completed\"`, proceed to Phase 3.\n\n**Resume detection:** If `status: \"in_progress\"` is found on startup, resume from the first unevaluated skill.\n\nEach skill is evaluated against this checklist:\n\n```\n- [ ] Content overlap with other skills checked\n- [ ] Overlap with MEMORY.md / CLAUDE.md checked\n- [ ] Freshness of technical references verified (use WebSearch if tool names / CLI flags / APIs are present)\n- [ ] Usage frequency considered\n```\n\nVerdict criteria:\n\n| Verdict | Meaning |\n|---------|---------|\n| Keep | Useful and current |\n| Improve | Worth keeping, but specific improvements needed |\n| Update | Referenced technology is outdated (verify with WebSearch) |\n| Retire | Low quality, stale, or cost-asymmetric |\n| Merge into [X] | Substantial overlap with another skill; name the merge target |\n\nEvaluation is **holistic AI judgment** — not a numeric rubric. Guiding dimensions:\n- **Actionability**: code examples, commands, or steps that let you act immediately\n- **Scope fit**: name, trigger, and content are aligned; not too broad or narrow\n- **Uniqueness**: value not replaceable by MEMORY.md / CLAUDE.md / another skill\n- **Currency**: technical references work in the current environment\n\n**Reason quality requirements** — the `reason` field must be self-contained and decision-enabling:\n- Do NOT write \"unchanged\" alone — always restate the core evidence\n- For **Retire**: state (1) what specific defect was found, (2) what covers the same need instead\n  - Bad: `\"Superseded\"`\n  - Good: `\"disable-model-invocation: true already set; superseded by continuous-learning-v2 which covers all the same patterns plus confidence scoring. No unique content remains.\"`\n- For **Merge**: name the target and describe what content to integrate\n  - Bad: `\"Overlaps with X\"`\n  - Good: `\"42-line thin content; Step 4 of chatlog-to-article already covers the same workflow. Integrate the ''article angle'' tip as a note in that skill.\"`\n- For **Improve**: describe the specific change needed (what section, what action, target size if relevant)\n  - Bad: `\"Too long\"`\n  - Good: `\"276 lines; Section ''Framework Comparison'' (L80–140) duplicates ai-era-architecture-principles; delete it to reach ~150 lines.\"`\n- For **Keep** (mtime-only change in Quick Scan): restate the original verdict rationale, do not write \"unchanged\"\n  - Bad: `\"Unchanged\"`\n  - Good: `\"mtime updated but content unchanged. Unique Python reference explicitly imported by rules/python/; no overlap found.\"`\n\n### Phase 3 — Summary Table\n\n| Skill | 7d use | Verdict | Reason |\n|-------|--------|---------|--------|\n\n### Phase 4 — Consolidation\n\n1. **Retire / Merge**: present detailed justification per file before confirming with user:\n   - What specific problem was found (overlap, staleness, broken references, etc.)\n   - What alternative covers the same functionality (for Retire: which existing skill/rule; for Merge: the target file and what content to integrate)\n   - Impact of removal (any dependent skills, MEMORY.md references, or workflows affected)\n2. **Improve**: present specific improvement suggestions with rationale:\n   - What to change and why (e.g., \"trim 430→200 lines because sections X/Y duplicate python-patterns\")\n   - User decides whether to act\n3. **Update**: present updated content with sources checked\n4. Check MEMORY.md line count; propose compression if >100 lines\n\n## Results File Schema\n\n`~/.claude/skills/skill-stocktake/results.json`:\n\n**`evaluated_at`**: Must be set to the actual UTC time of evaluation completion.\nObtain via Bash: `date -u +%Y-%m-%dT%H:%M:%SZ`. Never use a date-only approximation like `T00:00:00Z`.\n\n```json\n{\n  \"evaluated_at\": \"2026-02-21T10:00:00Z\",\n  \"mode\": \"full\",\n  \"batch_progress\": {\n    \"total\": 80,\n    \"evaluated\": 80,\n    \"status\": \"completed\"\n  },\n  \"skills\": {\n    \"skill-name\": {\n      \"path\": \"~/.claude/skills/skill-name/SKILL.md\",\n      \"verdict\": \"Keep\",\n      \"reason\": \"Concrete, actionable, unique value for X workflow\",\n      \"mtime\": \"2026-01-15T08:30:00Z\"\n    }\n  }\n}\n```\n\n## Notes\n\n- Evaluation is blind: the same checklist applies to all skills regardless of origin (ECC, self-authored, auto-extracted)\n- Archive / delete operations always require explicit user confirmation\n- No verdict branching by skill origin\n"},"category":"official","lastSynced":"2026-03-06T04:34:27.118Z","seo":{"title":{"en":"skill-stocktake: Audit Claude Skills for Quality | AI Age...","zh":"AIエージェント优化工具：skill-stocktake Setup Guide","ja":"AIエージェントの品質管理：skill-stocktake ベストプラクティス","ko":"AI 에이전트 품질 관리 도구: skill-stocktake 설정 가이드","es":"Guía de configuración de skill-stocktake para auditoría d...","fr":"Guide de mise en place de skill-stocktake pour l''audit de...","de":"Einrichtungsanleitung für skill-stocktake zur Überprüfung...","pt":"Guia de Configuração do skill-stocktake para Auditoria de...","ru":"ИИ Агенты: Настройка skill-stocktake для аудита качества","ar":"إعداد مرشد skill-stocktake لتدقيق الجودة"},"description":{"en":"Run the /skill-stocktake command to audit Claude skills using AI holistic judgment. Supports Quick Scan for changed skills and Full Stocktake modes. Learn ho...","zh":"使用skill-stocktake Audit Claude技能和命令，支持快速扫描和完整盘点模式，提高开发效率","ja":"Claudeスキルとコマンドの品質をAuditするためのツール、Quick ScanとFull Stocktakeモードをサポート","ko":"클라우드 스킬과 명령의 품질을 감사하는 툴, 빠른 스캔과 전체盤点 모드를 지원하여 개발 효율성을 향상","es":"Aprende a utilizar skill-stocktake para auditar habilidades y comandos de Claude con nuestra guía paso a paso","fr":"Découvrez comment utiliser skill-stocktake pour auditer les compétences et les commandes de Claude avec notre guide étape par étape","de":"Erfahren Sie, wie Sie skill-stocktake verwenden, um Claude-Fähigkeiten und -Befehle zu überprüfen, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o skill-stocktake para auditoria de qualidade de skills e comandos do Claude com Quick Scan e Full Stocktake","ru":"Узнайте, как настроить skill-stocktake для аудита качества навыков и команд Claude с помощью Quick Scan и Full Stocktake","ar":"تعلم كيفية إعداد مرشد skill-stocktake لتدقيق الجودة لمهارات وأوامر Claude مع Quick Scan و Full Stocktake"},"definition":{"en":"skill-stocktake is a slash command (/skill-stocktake) that audits Claude skills and commands for quality using a checklist and AI holistic judgment. It supports Quick Scan mode for recently changed skills and Full Stocktake mode for a complete review of all skills.","zh":"skill-stocktake是一种AIエージェント工具，用于审计Claude技能和命令的品质","ja":"skill-stocktakeはAIエージェントの品質管理ツールで、ClaudeスキルとコマンドをAudit","ko":"skill-stocktake는 AI 에이전트의 품질 관리 도구로, 클라우드 스킬과 명령의 품질을 감사","es":"Skill-stocktake es una herramienta de auditoría de AI que evalúa la calidad de las habilidades y comandos de Claude","fr":"Skill-stocktake est un outil d''audit d''IA qui évalue la qualité des compétences et des commandes de Claude","de":"Skill-stocktake ist ein AI-Audit-Tool, das die Qualität von Claude-Fähigkeiten und -Befehlen bewertet","pt":"O que é skill-stocktake? É uma ferramenta de auditoria de qualidade para skills e comandos do Claude.","ru":"Что такое skill-stocktake? Это инструмент для аудита качества навыков и команд Claude.","ar":"ما هو مرشد skill-stocktake؟ هو أداة تدقيق الجودة لمهارات وأوامر Claude."},"features":{"en":["Executes via the /skill-stocktake slash command","Performs AI holistic judgment for quality auditing","Supports Quick Scan mode for recently changed skills only","Supports Full Stocktake mode for a complete review","Scans global skills in ~/.claude/skills/ directory","Scans project-level skills in {cwd}/.claude/skills/ directory"],"zh":["支持Quick Scan和Full Stocktake两种模式","使用AI全局判断进行品质Audit","支持对Global skills和Project-level skill进行审计","命令行工具，方便快捷"],"ja":["Quick ScanとFull Stocktakeの2つのモードをサポート","AIホリスティック判断を使用した品質Audit","Global skillsとProject-level skillの両方をサポート","コマンドラインツール、便利な操作"],"ko":["빠른 스캔과 전체盤点 두 가지 모드를 지원","AI 전체 판단을 사용한 품질 감사","전체 스킬과 프로젝트 수준 스킬을 모두 지원","명령 줄 도구, 편리한操作"],"es":["Soporte para modos de exploración rápida y completa","Evaluación de habilidades y comandos de Claude mediante una lista de verificación de calidad","Uso de juicio holístico de IA para la evaluación","Compatibilidad con el comando de barra diagonal (/skill-stocktake)","Análisis de caminos relativos al directorio donde se invoca el comando","Soporte para la evaluación de habilidades globales y de proyecto"],"fr":["Prise en charge des modes de balayage rapide et complet","Évaluation des compétences et des commandes de Claude à l''aide d''une liste de vérification de qualité","Utilisation du jugement holistique de l''IA pour l''évaluation","Compatibilité avec la commande de barre oblique (/skill-stocktake)","Analyse des chemins relatifs au répertoire où la commande est invoquée","Prise en charge de l''évaluation des compétences globales et de projet"],"de":["Unterstützung für Quick-Scan- und Full-Stocktake-Modi","Bewertung von Claude-Fähigkeiten und -Befehlen mithilfe einer Qualitätsscheckliste","Verwendung von AI-holistischem Urteil für die Bewertung","Kompatibilität mit dem Befehl (/skill-stocktake)","Analyse von Pfaden relativ zum Verzeichnis, in dem der Befehl aufgerufen wird","Unterstützung für die Bewertung globaler und projektspezifischer Fähigkeiten"],"pt":["Suporte a Quick Scan para skills alterados recentemente","Suporte a Full Stocktake para revisão completa","Avaliação sequencial de subagentes em batch","Auditoria de qualidade de skills e comandos do Claude","Suporte a CLI para execução de comandos"],"ru":["Поддержка Quick Scan для недавно измененных навыков","Поддержка Full Stocktake для полного обзора","Последовательная оценка субагентов в пакетах","Аудит качества навыков и команд Claude","Поддержка CLI для выполнения команд"],"ar":["دعم Quick Scan لمهارات معدلة حديثًا","دعم Full Stocktake لاستعراض كامل","تقييم متتالي للوكلاء الفرعيين في الدفعة","تدقيق الجودة لمهارات وأوامر Claude","دعم CLI لتنفيذ الأوامر"]},"keywords":{"en":["how to use skill-stocktake","what is skill-stocktake","skill-stocktake vs manual audit","skill-stocktake alternative","skill-stocktake install","skill-stocktake setup guide","Claude Code skill audit","MCP developer tools","AI agent quality checklist"],"zh":["AIエージェント工具","skill-stocktake","Claude技能审计","Quick Scan","Full Stocktake","AI开发工具","开发效率优化"],"ja":["AIエージェントツール","skill-stocktake","ClaudeスキルAudit","Quick Scan","Full Stocktake","AI開発ツール","開発効率最適化"],"ko":["AI 에이전트 도구","skill-stocktake","클라우드 스킬 감사","빠른 스캔","전체盤点","AI 개발 도구","개발 효율성 향상"],"es":["skill-stocktake","auditoría de habilidades de Claude","herramientas de AI para desarrolladores","evaluación de calidad de habilidades de Claude","modos de exploración rápida y completa","lista de verificación de calidad para habilidades de Claude","jugamiento holístico de IA","desarrollo de habilidades de Claude"],"fr":["skill-stocktake","audit des compétences de Claude","outils d''IA pour les développeurs","évaluation de la qualité des compétences de Claude","modes de balayage rapide et complet","liste de vérification de qualité pour les compétences de Claude","jugement holistique de l''IA","développement de compétences de Claude"],"de":["skill-stocktake","Überprüfung von Claude-Fähigkeiten","AI-Tools für Entwickler","Bewertung der Qualität von Claude-Fähigkeiten","Quick-Scan- und Full-Stocktake-Modi","Qualitätsscheckliste für Claude-Fähigkeiten","AI-holistisches Urteil","Entwicklung von Claude-Fähigkeiten"],"pt":["skill-stocktake","auditoria de qualidade","Claude","Quick Scan","Full Stocktake","desenvolvimento de software","ferramentas de desenvolvimento","AI agents"],"ru":["skill-stocktake","аудит качества","Claude","Quick Scan","Full Stocktake","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["مرشد skill-stocktake","تدقيق الجودة","Claude","Quick Scan","Full Stocktake","تطوير البرمجيات","أدوات التطوير","وكلاء الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Essential for Quality Assurance Agents auditing Claude skill repositories across global and project-level directories.","zh":"对于质量保证代理在全球和项目级目录中审计Claude技能存储库至关重要。","ja":"グローバルおよびプロジェクトレベルのディレクトリでClaudeスキルリポジトリを監査するための品質保証エージェントに不可欠です。","ko":"글로벌 및 프로젝트 수준의 디렉토리에서 Claude 스킬 저장소를 감사하는 품질 보증 에이전트에 필수적입니다.","es":"Esencial para los Agentes de Aseguramiento de la Calidad que auditan los repositorios de habilidades de Claude en los directorios globales y a nivel de proyecto.","fr":"Essentiel pour les agents d''assurance qualité qui audite les dépôts de compétences Claude dans les répertoires globaux et au niveau du projet.","de":"Essenziell für Quality Assurance Agents, die Claude-Skill-Repositorys in globalen und projektbezogenen Verzeichnissen prüfen.","pt":"Essencial para Agentes de Garantia de Qualidade que auditam repositórios de skills do Claude em diretórios globais e de nível de projeto.","ru":"Необходим для Агентов по Обеспечению Качества, проводящих аудит репозиториев навыков Claude в глобальных каталогах и каталогах на уровне проектов.","ar":"أساسي لوكلاء ضمان الجودة الذين يقومون بمراجعة مستودعات مهارات Claude عبر أدلة المستوى العالمي والمستوى المشروع."},"recommendation":{"en":"Enables automated batch evaluation of Claude skills using sequential subagent processing with quality checklist validation and AI holistic judgment. Supports both Quick Scan (changed skills only) and Full Stocktake modes for comprehensive content analysis.","zh":"通过顺序子代理处理和质量检查清单验证以及AI整体判断，实现Claude技能的自动化批量评估。支持快速扫描（仅更改的技能）和完整库存模式，以进行全面内容分析。","ja":"シーケンシャルサブエージェント処理および品質チェックリストによるバリデーションとAIのホリスティック判断を使用して、Claudeスキルの自動化されたバッチ評価を可能にします。最近変更されたスキルのためのクイックスキャンと包括的なコンテンツ分析のためのフルストックテイクモードの両方をサポートします。","ko":"순차적 하위 에이전트 처리 및 품질 체크리스트에 따른 검증 및 AI의 일반적인 판단을 사용하여 Claude 스킬의 자동화된 배치 평가를 가능하게 합니다. 최근 수정된 스킬에 대한 빠른 스캔과 포괄적인 내용 분석을 위한 전체 재고 모드의 두 가지 모두를 지원합니다.","es":"Permite la evaluación automatizada por lotes de las habilidades de Claude utilizando un procesamiento secuencial de subagentes con validación de lista de comprobación de calidad y juicio holístico de IA. Admite tanto el modo Escaneo Rápido (solo habilidades modificadas) como el modo Inventario Completo para un análisis de contenido exhaustivo.","fr":"Permet l''évaluation automatisée par lots des compétences Claude en utilisant un traitement séquentiel de sous-agents avec validation par liste de contrôle qualité et jugement holistique de l''IA. Prend en charge à la fois le mode Analyse Rapide (compétences modifiées uniquement) et le mode Inventaire Complet pour une analyse de contenu exhaustive.","de":"Ermöglicht die automatisierte Batch-Evaluierung von Claude-Skills mittels sequentieller Subagenten-Verarbeitung mit Qualitäts-Checklist-Validierung und ganzheitlicher KI-Beurteilung. Unterstützt sowohl den Quick-Scan-Modus (nur geänderte Skills) als auch den Full-Stocktake-Modus für eine umfassende Inhaltsanalyse.","pt":"Permite a avaliação automatizada em lote de skills do Claude usando processamento sequencial de subagentes com validação de lista de verificação de qualidade e julgamento holístico de IA. Suporta os modos Quick Scan (apenas skills alteradas) e Full Stocktake para análise abrangente de conteúdo.","ru":"Позволяет проводить автоматизированную пакетную оценку навыков Claude с использованием последовательной обработки подчиненными агентами, проверкой по контрольному списку качества и комплексной оценкой ИИ. Поддерживает как режим Быстрого Сканирования (только измененные навыки), так и режим Полной Инвентаризации для всестороннего анализа содержимого.","ar":"يمكن من التقييم الآلي المجمع لمهارات Claude باستخدام المعالجة المتسلسلة للوكلاء الفرعية مع التحقق من قائمة مراجعة الجودة والحكم الشامل للذكاء الاصطناعي. يدعم كلاً من وضع المسح السريع (المهارات المتغيرة فقط) ووضع الجرد الكامل لتحليل محتوى شامل."},"useCases":{"en":["Auditing global skills in ~/.claude/skills/ directory","Validating project-level skills in {cwd}/.claude/skills/","Performing sequential subagent batch evaluation","Conducting Quick Scan reviews for recently modified skills"],"zh":["审计~/.claude/skills/目录中的全局技能","验证{cwd}/.claude/skills/中的项目级技能","执行顺序子代理批量评估","进行最近修改的技能的快速扫描审查"],"ja":["~/.claude/skills/ディレクトリ内のグローバルスキルの監査","{cwd}/.claude/skills/内のプロジェクトレベルのスキルの検証","シーケンシャルサブエージェントによるバッチ評価の実行","最近変更されたスキルのためのクイックスキャンレビューの実施"],"ko":["~/.claude/skills/ 디렉토리 내의 글로벌 스킬 감사","{cwd}/.claude/skills/ 내의 프로젝트 레벨 스킬 검증","순차적 하위 에이전트 배치 평가 수행","최근 수정된 스킬에 대한 빠른 스캔 검토 수행"],"es":["Auditoría de habilidades globales en el directorio ~/.claude/skills/","Validación de habilidades a nivel de proyecto en {cwd}/.claude/skills/","Realización de evaluaciones por lotes de subagentes secuenciales","Realización de revisiones de Escaneo Rápido para habilidades modificadas recientemente"],"fr":["Audit des compétences globales dans le répertoire ~/.claude/skills/","Validation des compétences au niveau du projet dans {cwd}/.claude/skills/","Réalisation d''évaluations par lots de sous-agents séquentiels","Réalisation d''analyses rapides pour les compétences récemment modifiées"],"de":["Auditierung globaler Skills im Verzeichnis ~/.claude/skills/","Validierung projektbezogener Skills in {cwd}/.claude/skills/","Durchführung sequentieller Subagenten-Batch-Evaluierungen","Durchführung von Quick-Scan-Überprüfungen für kürzlich geänderte Skills"],"pt":["Auditoria de skills globais no diretório ~/.claude/skills/","Validação de skills de nível de projeto em {cwd}/.claude/skills/","Execução de avaliação em lote sequencial de subagentes","Realização de revisões de Quick Scan para skills modificadas recentemente"],"ru":["Аудит глобальных навыков в каталоге ~/.claude/skills/","Проверка навыков на уровне проекта в {cwd}/.claude/skills/","Проведение последовательной пакетной оценки подчиненными агентами","Проведение обзоров Быстрого Сканирования для недавно измененных навыков"],"ar":["مراجعة المهارات العالمية في دليل ~/.claude/skills/","التحقق من صحة مهارات مستوى المشروع في {cwd}/.claude/skills/","إجراء تقييم مجمع متسلسل للوكلاء الفرعية","إجراء مراجعات المسح السريع للمهارات المعدلة حديثًا"]},"limitations":{"en":["Requires access to filesystem paths","Limited to Claude skill ecosystem","Dependent on directory structure compliance"],"zh":["需要访问文件系统路径","仅限Claude技能生态系统","依赖于目录结构的合规性"],"ja":["ファイルシステムパスのアクセスが必要","Claudeスキルエコシステムに限定される","ディレクトリ構造のコンプライアンスに依存する"],"ko":["파일 시스템 경로에 대한 액세스가 필요함","Claude 스킬 에코시스템으로 제한됨","디렉토리 구조의 규정 준수에 의존함"],"es":["Requiere acceso a las rutas del sistema de archivos","Limitado al ecosistema de habilidades de Claude","Depende del cumplimiento de la estructura del directorio"],"fr":["Nécessite un accès aux chemins du système de fichiers","Limité à l''écosystème des compétences Claude","Dépend du respect de la structure du répertoire"],"de":["Erfordert Zugriff auf Dateisystempfade","Beschränkt auf das Claude-Skill-Ökosystem","Abhängig von der Einhaltung der Verzeichnisstruktur"],"pt":["Requer acesso aos caminhos do sistema de arquivos","Limitado ao ecossistema de skills do Claude","Dependente da conformidade com a estrutura do diretório"],"ru":["Требует доступа к путям файловой системы","Ограничено экосистемой навыков Claude","Зависит от соответствия структуре каталога"],"ar":["يتطلب الوصول إلى مسارات نظام الملفات","مقتصر على نظام مهارات Claude","يعتمد على الامتثال لهيكل الدليل"]},"version":4},"contentHash":"7b0b982d8d0c60ead792d7befe1b4ef8890543cba931132a7618730d9987b246","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":80}');
