INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/skill-stocktake', 'skill-stocktake', 'affaan-m', 'everything-claude-code', 'official', 'skill-stocktake affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The skill-stocktake slash command performs quality audits on Claude skills and commands using a checklist and AI evaluation. It benefits developers and AI agent builders working with Claude Code and MCP by scanning both global and project-level skill directories. skill-stocktake是一个用于审计Claude技能和命令的工具，支持Quick Scan和Full Stocktake两种模式 skill-stocktakeはClaudeスキルとコマンドの品質をAuditするツールで、Quick ScanとFull Stocktakeの2つのモードをサポート skill-stocktake는 클라우드 스킬과 명령의 품질을 감사하는 도구로, 빠른 스캔과 전체盤点 두 가지 모드를 지원 Skill-stocktake es una herramienta de auditoría para evaluar la calidad de las habilidades y comandos de Claude. Soporta modos de exploración rápida y completa. Skill-stocktake est un outil d''audit pour évaluer la qualité des compétences et des commandes de Claude. Il prend en charge les modes de balayage rapide et complet. Skill-stocktake ist ein Audit-Tool, um die Qualität von Claude-Fähigkeiten und -Befehlen zu bewerten. Es unterstützt die Modi Quick Scan und Full Stocktake. O skill-stocktake é uma ferramenta de auditoria de qualidade para skills e comandos do Claude, com suporte a Quick Scan e Full Stocktake. Skill-stocktake - это инструмент для аудита качества навыков и команд Claude, поддерживающий Quick Scan и Full Stocktake. مرشد skill-stocktake هو أداة تدقيق الجودة لمهارات وأوامر Claude، يدعم Quick Scan و Full Stocktake. how to use skill-stocktake what is skill-stocktake skill-stocktake vs manual audit skill-stocktake alternative skill-stocktake install skill-stocktake setup guide Claude Code skill audit MCP developer tools AI agent quality checklist AIエージェント工具 skill-stocktake Claude技能审计 Quick Scan Full Stocktake AI开发工具 开发效率优化 Executes via the /skill-stocktake slash command Performs AI holistic judgment for quality auditing Supports Quick Scan mode for recently changed skills only Supports Full Stocktake mode for a complete review Scans global skills in ~/.claude/skills/ directory Scans project-level skills in {cwd}/.claude/skills/ directory skill-stocktake is a slash command (/skill-stocktake) that audits Claude skills and commands for quality using a checklist and AI holistic judgment. It supports Quick Scan mode for recently changed skills and Full Stocktake mode for a complete review of all skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/strategic-compact', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'strategic-compact', 61988, 7678, 80, '2026-03-06T03:39:20Z', '2026-03-06T04:38:59.219Z', 'c83c4c9d60d30d508bbd2bf0c6ffa724b5fdac679addd4828b268892dc39dc1b', '{"id":"affaan-m/everything-claude-code/strategic-compact","name":"strategic-compact","description":{"en":"The strategic-compact skill suggests manual context compaction at logical workflow intervals instead of arbitrary auto-compaction. It benefits developers running long AI sessions with Claude, particularly those working on multi-phase tasks approaching context limits.","zh":"Strategic Compact 技术建议在逻辑间隔手动压缩上下文，以保持任务阶段的上下文一致性","ja":"Strategic Compact 技術は、タスクの各段階で上下文を保持するために、論理的な間隔で手動でコンテキストを圧縮することを提案します","ko":"Strategic Compact 기술은 작업 단계에서 컨텍스트를 유지하기 위해 논리적인 간격으로 수동으로 컨텍스트를 압축하는 것을 제안합니다","es":"Strategic Compact es una habilidad de MCP que sugiere puntos lógicos para ejecutar el comando /compact manualmente. Esto preserva el contexto valioso en sesiones largas que se acercan al límite de 200K tokens, mejorando la coherencia en tareas multifase.","fr":"Strategic Compact est une compétence MCP qui suggère des points logiques pour exécuter manuellement la commande /compact. Cela préserve le contexte précieux dans les longues sessions approchant la limite de 200K tokens, améliorant la cohérence pour les tâches multi-phases.","de":"Strategic Compact ist ein MCP-Skill, der logische Zeitpunkte für die manuelle Ausführung des /compact-Befehls vorschlägt. So wird wertvoller Kontext in langen Sitzungen nahe dem 200K-Token-Limit erhalten, was die Kohärenz bei mehrphasigen Aufgaben verbessert.","pt":"O Strategic Compact é uma habilidade que sugere a compactação manual do contexto em intervalos lógicos, melhorando a produtividade e reduzindo a pressão de contexto","ru":"Strategic Compact - это навык, который предлагает ручную компактацию контекста на логических интервалах,提高ая производительность и снижая контекстное давление","ar":"Strategic Compact هو مهارة تقترح الضغط اليدوي للسياق في فترات منطقية، مما يحسن الإنتاجية ويقلل الضغط السياقي"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"strategic-compact","description":"Suggests manual context compaction at logical intervals to preserve context through task phases rather than arbitrary auto-compaction.","bodyPreview":"# Strategic Compact Skill\n\nSuggests manual `/compact` at strategic points in your workflow rather than relying on arbitrary auto-compaction.\n\n## When to Activate\n\n- Running long sessions that approach context limits (200K+ tokens)\n- Working on multi-phase tasks (research → plan → implement → test)\n- Switching between unrelated tasks within the same session\n- After completing a major milestone and starting new work\n- When responses slow down or become less coherent (context pressure)\n\n## Why Stra","body":"# Strategic Compact Skill\n\nSuggests manual `/compact` at strategic points in your workflow rather than relying on arbitrary auto-compaction.\n\n## When to Activate\n\n- Running long sessions that approach context limits (200K+ tokens)\n- Working on multi-phase tasks (research → plan → implement → test)\n- Switching between unrelated tasks within the same session\n- After completing a major milestone and starting new work\n- When responses slow down or become less coherent (context pressure)\n\n## Why Strategic Compaction?\n\nAuto-compaction triggers at arbitrary points:\n- Often mid-task, losing important context\n- No awareness of logical task boundaries\n- Can interrupt complex multi-step operations\n\nStrategic compaction at logical boundaries:\n- **After exploration, before execution** — Compact research context, keep implementation plan\n- **After completing a milestone** — Fresh start for next phase\n- **Before major context shifts** — Clear exploration context before different task\n\n## How It Works\n\nThe `suggest-compact.js` script runs on PreToolUse (Edit/Write) and:\n\n1. **Tracks tool calls** — Counts tool invocations in session\n2. **Threshold detection** — Suggests at configurable threshold (default: 50 calls)\n3. **Periodic reminders** — Reminds every 25 calls after threshold\n\n## Hook Setup\n\nAdd to your `~/.claude/settings.json`:\n\n```json\n{\n  \"hooks\": {\n    \"PreToolUse\": [\n      {\n        \"matcher\": \"Edit\",\n        \"hooks\": [{ \"type\": \"command\", \"command\": \"node ~/.claude/skills/strategic-compact/suggest-compact.js\" }]\n      },\n      {\n        \"matcher\": \"Write\",\n        \"hooks\": [{ \"type\": \"command\", \"command\": \"node ~/.claude/skills/strategic-compact/suggest-compact.js\" }]\n      }\n    ]\n  }\n}\n```\n\n## Configuration\n\nEnvironment variables:\n- `COMPACT_THRESHOLD` — Tool calls before first suggestion (default: 50)\n\n## Compaction Decision Guide\n\nUse this table to decide when to compact:\n\n| Phase Transition | Compact? | Why |\n|-----------------|----------|-----|\n| Research → Planning | Yes | Research context is bulky; plan is the distilled output |\n| Planning → Implementation | Yes | Plan is in TodoWrite or a file; free up context for code |\n| Implementation → Testing | Maybe | Keep if tests reference recent code; compact if switching focus |\n| Debugging → Next feature | Yes | Debug traces pollute context for unrelated work |\n| Mid-implementation | No | Losing variable names, file paths, and partial state is costly |\n| After a failed approach | Yes | Clear the dead-end reasoning before trying a new approach |\n\n## What Survives Compaction\n\nUnderstanding what persists helps you compact with confidence:\n\n| Persists | Lost |\n|----------|------|\n| CLAUDE.md instructions | Intermediate reasoning and analysis |\n| TodoWrite task list | File contents you previously read |\n| Memory files (`~/.claude/memory/`) | Multi-step conversation context |\n| Git state (commits, branches) | Tool call history and counts |\n| Files on disk | Nuanced user preferences stated verbally |\n\n## Best Practices\n\n1. **Compact after planning** — Once plan is finalized in TodoWrite, compact to start fresh\n2. **Compact after debugging** — Clear error-resolution context before continuing\n3. **Don''t compact mid-implementation** — Preserve context for related changes\n4. **Read the suggestion** — The hook tells you *when*, you decide *if*\n5. **Write before compacting** — Save important context to files or memory before compacting\n6. **Use `/compact` with a summary** — Add a custom message: `/compact Focus on implementing auth middleware next`\n\n## Related\n\n- [The Longform Guide](https://x.com/affaanmustafa/status/2014040193557471352) — Token optimization section\n- Memory persistence hooks — For state that survives compaction\n- `continuous-learning` skill — Extracts patterns before session ends\n"},"category":"official","lastSynced":"2026-03-06T04:38:59.219Z","seo":{"title":{"en":"strategic-compact: Manual Context Compaction Guide | AI A...","zh":"Strategic Compact Setup Guide - AIエージェント优化","ja":"Strategic Compact ベストプラクティス - AIエージェントの効率化","ko":"Strategic Compact 구축 가이드 - AI 에이전트 최적화","es":"Strategic Compact: Guía de Compactación Manual para AI Ag...","fr":"Strategic Compact : Guide de Compaction Manuel pour Outil...","de":"Strategic Compact: Leitfaden für manuelle Komprimierung v...","pt":"Guia de Configuração do Strategic Compact para Agentes de IA","ru":"Настройка Strategic Compact для ИИ Агентов: Руководство","ar":"دليل إعداد Strategic Compact لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how strategic-compact''s manual /compact command preserves context in long AI sessions. Avoid arbitrary auto-compaction and maintain coherence when work...","zh":"提高您的工作效率，通过在合适的时间手动压缩上下文，优化AIエージェント的性能","ja":"AIエージェントのパフォーマンスを最適化するために、適切なタイミングで手動でコンテキストを圧縮します","ko":"AI 에이전트의 성능을 최적화하기 위해 적절한 시점에 수동으로 컨텍스트를 압축합니다","es":"Aprende a usar Strategic Compact para gestionar manualmente el contexto en sesiones largas de Claude. Optimiza el rendimiento en tareas multifase evitando la...","fr":"Découvrez comment utiliser Strategic Compact pour gérer manuellement le contexte dans les longues sessions Claude. Optimisez les performances pour les tâches...","de":"Erfahren Sie, wie Sie mit Strategic Compact den Kontext in langen Claude-Sitzungen manuell verwalten. Optimieren Sie die Leistung bei mehrphasigen Aufgaben d...","pt":"Aprenda a otimizar o desempenho dos agentes de IA com o Strategic Compact, reduzindo a pressão de contexto e melhorando a produtividade","ru":"Узнайте, как настроить Strategic Compact для ИИ Агентов, чтобы повысить производительность и снизить контекстное давление","ar":"تعلم كيفية تحسين أداء أدوات الذكاء الاصطناعي باستخدام Strategic Compact، وتقليل الضغط السياقي وتحسين الإنتاجية"},"definition":{"en":"strategic-compact is an AI agent skill that recommends manual execution of the /compact command at strategic points in a workflow. It helps preserve context integrity through task phases in long sessions, especially when approaching the 200K+ token limit in Claude AI interactions.","zh":"Strategic Compact 是一种 AI エージェント技术，用于在特定时机手动压缩上下文","ja":"Strategic Compact は、特定のタイミングで手動でコンテキストを圧縮する AI エージェント技術です","ko":"Strategic Compact 는 특정 시점에 수동으로 컨텍스트를 압축하는 AI 에이전트 기술입니다","es":"Strategic Compact es una habilidad para AI Agents y herramientas de desarrollador que recomienda la compactación manual del contexto en intervalos lógicos dentro de un flujo de trabajo. En lugar de una compactación automática arbitraria, se activa al cambiar entre fases de tareas o completar hitos importantes.","fr":"Strategic Compact est une compétence pour les outils IA et développeurs qui recommande une compaction manuelle du contexte à des intervalles logiques dans un flux de travail. Au lieu d''une compaction automatique arbitraire, elle s''active lors du changement entre phases de tâches ou de l''achèvement d''étapes importantes.","de":"Strategic Compact ist ein Skill für KI-Agenten und Entwickler-Tools, der eine manuelle Komprimierung des Kontexts in logischen Intervallen innerhalb eines Workflows empfiehlt. Statt willkürlicher Auto-Kompaktierung wird sie beim Wechsel zwischen Aufgabenphasen oder dem Abschluss wichtiger Meilensteine aktiviert.","pt":"O que é Strategic Compact? É uma habilidade que ajuda a preservar o contexto através de fases de tarefas, evitando a compactação automática arbitrária","ru":"Что такое Strategic Compact? Это навык, который помогает сохранять контекст через фазы задач, избегая произвольной автоматической компактации","ar":"ما هو Strategic Compact؟ إنه مهارة تساعد على الحفاظ على السياق عبر مراحل المهام، وتجنب الضغط التلقائي التعسفي"},"features":{"en":["Suggests manual /compact command execution at logical intervals","Designed for long sessions approaching 200K+ token context limits","Optimized for multi-phase tasks (research → plan → implement → test)","Activates when switching between unrelated tasks within a session","Recommends compaction after completing major milestones","Triggers suggestions when responses slow down or lose coherence due to context pressure"],"zh":["在长时间会话中手动压缩上下文（200K+ tokens）","支持多阶段任务（研究、规划、实施、测试）","在同一会话中切换无关任务时压缩上下文","完成主要里程碑后启动新工作","响应速度变慢或不一致时压缩上下文"],"ja":["長時間のセッション中（200K+ トークン）に手動でコンテキストを圧縮する","多段階タスク（リサーチ、プランニング、実装、テスト）をサポートする","同一セッション内で無関係タスクを切り替える際にコンテキストを圧縮する","主要マイルストーンを完了後、新しい作業を開始する","レスポンス速度が遅くなったり不一致になったりした際にコンテキストを圧縮する"],"ko":["긴 시간 세션에서 수동으로 컨텍스트를 압축합니다（200K+ 토큰）","다단계 작업（연구, 계획, 구현, 테스트）을 지원합니다","同じ 세션 내에서 관련 없는 작업을 전환할 때 컨텍스트를 압축합니다","주요 마일스톤을 완료한 후 새로운 작업을 시작합니다","응답 속도가 느려지거나 일관성이 없을 때 컨텍스트를 압축합니다"],"es":["Sugiere compactación manual en lugar de auto-compactación arbitraria","Optimizado para sesiones largas que se acercan al límite de 200K tokens","Activa en transiciones entre fases de tareas (investigación → plan → implementación → test)","Recomienda uso después de completar hitos importantes o cambiar entre tareas no relacionadas","Mejora la coherencia de las respuestas al reducir la presión del contexto","Integrado con el ecosistema MCP y Claude Code para desarrolladores"],"fr":["Suggère une compaction manuelle au lieu d''une auto-compaction arbitraire","Optimisé pour les longues sessions approchant la limite de 200K tokens","S''active lors des transitions entre phases de tâches (recherche → plan → implémentation → test)","Recommande l''utilisation après l''achèvement d''étapes importantes ou le changement entre tâches non liées","Améliore la cohérence des réponses en réduisant la pression contextuelle","Intégré à l''écosystème MCP et Claude Code pour les développeurs"],"de":["Schlägt manuelle Komprimierung statt willkürlicher Auto-Kompaktierung vor","Optimiert für lange Sitzungen nahe dem 200K-Token-Limit","Aktiviert bei Übergängen zwischen Aufgabenphasen (Recherche → Plan → Implementierung → Test)","Empfiehlt Nutzung nach Abschluss wichtiger Meilensteine oder Wechsel zwischen unabhängigen Aufgaben","Verbessert die Antwortkohärenz durch Reduzierung des Kontextdrucks","Integriert in das MCP-Ökosystem und Claude Code für Entwickler"],"pt":["Sugestão de compactação manual do contexto em intervalos lógicos","Melhoria da produtividade em sessões longas","Redução da pressão de contexto em tarefas multi-fase","Compatibilidade com agentes de IA como Claude e MCP","Integração com ferramentas de desenvolvimento como CLI"],"ru":["Предложение ручной компактации контекста на логических интервалах","Повышение производительности в длинных сессиях","Снижение контекстного давления в многофазных задачах","Совместимость с ИИ Агентами как Claude и MCP","Интеграция с инструментами разработки как CLI"],"ar":["اقتراح الضغط اليدوي للسياق في الفترات المنطقية","تحسين الإنتاجية في الجلسات الطويلة","تقليل الضغط السياقي في المهام متعددة المراحل","التوافق مع أدوات الذكاء الاصطناعي مثل Claude وMCP","التكامل مع أدوات التطوير مثل CLI"]},"keywords":{"en":["how to use strategic-compact skill","what is strategic-compact MCP","strategic-compact vs auto compaction","strategic-compact alternative","strategic-compact install guide","strategic-compact setup for Claude","manual context compaction AI agent","managing Claude 200K token limit","MCP server compaction strategies"],"zh":["AIエージェント优化","Strategic Compact 技术","手动压缩上下文","长时间会话","多阶段任务","AI工具","开发者工具"],"ja":["AIエージェントの効率化","Strategic Compact 技術","手動でコンテキストを圧縮する","長時間のセッション","多段階タスク","AIツール","開発者ツール"],"ko":["AI 에이전트 최적화","Strategic Compact 기술","수동으로 컨텍스트를 압축하는","긴 시간 세션","다단계 작업","AI 도구","개발자 도구"],"es":["strategic compact MCP","compactación manual contexto Claude","gestionar contexto 200K tokens","mejorar coherencia AI agent","optimizar sesiones largas Claude","comando compact AI tools","MCP skills para desarrolladores","evitar compactación automática"],"fr":["strategic compact MCP","compaction manuelle contexte Claude","gérer contexte 200K tokens","améliorer cohérence outil IA","optimiser longues sessions Claude","commande compact outils IA","compétences MCP pour développeurs","éviter compaction automatique"],"de":["strategic compact MCP","manuelle Komprimierung Kontext Claude","Kontext 200K Token verwalten","Antwortkohärenz KI Agent verbessern","lange Claude Sitzungen optimieren","compact Befehl AI Tools","MCP Skills für Entwickler","Auto-Kompaktierung vermeiden"],"pt":["agentes de ia","strategic compact","compactação de contexto","produtividade","ferramentas de desenvolvimento","cli","claude","mcp","índice de contexto","otimização de desempenho"],"ru":["ИИ Агенты","стратегический компакт","компактация контекста","производительность","инструменты разработки","cli","claude","mcp","индекс контекста","оптимизация производительности"],"ar":["أدوات الذكاء الاصطناعي","الضغط الاستراتيجي","ضغط السياق","الإنتاجية","أدوات التطوير","cli","claude","mcp","مؤشر السياق","تحسين الأداء"]}},"agentAnalysis":{"suitability":{"en":"Ideal for long-session agents handling multi-phase workflows like research, planning, and implementation.","zh":"适合处理像研究、规划和实施等多阶段工作流的长会话代理。","ja":"研究、計画、実装などのマルチフェーズのワークフローを扱う長時間セッションのエージェントに最適です。","ko":"연구, 계획 및 구현과 같은 다중 단계 워크플로를 처리하는 장기 세션 에이전트에 적합합니다.","es":"Ideal para agentes de sesión larga que manejan flujos de trabajo multifásicos como research, planning e implementation.","fr":"Idéal pour les agents à session longue gérant des flux de travail multi-étapes comme la research, la planning et l''implementation.","de":"Ideal für Agenten mit langen Sitzungen, die mehrphasige Workflows wie research, planning und implementation handhaben.","pt":"Ideal para agentes de sessão longa que lidam com fluxos de trabalho multifásicos, como pesquisa, planejamento e implementação.","ru":"Идеально подходит для агентов с длительными сессиями, обрабатывающих многоэтапные рабочие процессы, такие как исследование, планирование и реализация.","ar":"مثالي لوكلاء الجلسات الطويلة الذين يتعاملون مع سير عمل متعددة المراحل مثل البحث، والتخطيط، والتنفيذ."},"recommendation":{"en":"Enables manual context compaction at logical intervals to preserve critical information through task phases, preventing performance degradation from arbitrary auto-compaction. This strategic approach maintains coherence when working near 200K+ token limits or switching between unrelated tasks.","zh":"在逻辑间隔内启用手动上下文压缩，以保留任务阶段中的关键信息，防止由于任意自动压缩而导致性能下降。这种战略方法可以在接近 200K+ 令牌限制或在无关任务之间切换时保持一致性。","ja":"論理的な間隔で手動コンテキスト圧縮を有効にし、タスクのフェーズを通じて重要な情報を保持し、任意の自動圧縮によってパフォーマンスの低下を防ぐ。これらの戦略的なアプローチは、200K+ トークン制限に近づいたり、無関係なタスク間を切り替えたりするときに一貫性を維持する。","ko":"논리적 간격에서 수동 컨텍스트 압축을 활성화하여 작업 단계를 통해 중요한 정보를 보존하고 임의의 자동 압축으로 인한 성능 저하를 방지하는 것을 가능하게 한다. 이러한 전략적 접근 방식은 200K+ 토큰 제한에 근접하거나 관련 없는 작업 사이를 전환할 때 일관성을 유지한다.","es":"Permite la compactación manual del contexto en intervalos lógicos para preservar información crítica a través de las fases de la tarea, evitando la degradación del rendimiento por una auto-compactación arbitraria. Este enfoque estratégico mantiene la coherencia cuando se trabaja cerca de límites de 200K+ tokens o al cambiar entre tareas no relacionadas.","fr":"Permet une compaction manuelle du contexte à des intervalles logiques pour préserver les informations critiques tout au long des phases de la tâche, évitant une dégradation des performances due à une auto-compaction arbitraire. Cette approche stratégique maintient la cohérence lors d''un travail près des limites de 200K+ tokens ou lors du passage entre des tâches non liées.","de":"Ermöglicht manuelle Kontext-Kompaktierung zu logischen Intervallen, um kritische Informationen über Aufgabenphasen hinweg zu erhalten und Leistungsverschlechterung durch willkürliche Auto-Kompaktierung zu verhindern. Dieser strategische Ansatz bewahrt die Kohärenz bei der Arbeit nahe 200K+ Token-Grenzen oder beim Wechsel zwischen nicht zusammenhängenden Aufgaben.","pt":"Permite a compactação manual de contexto em intervalos lógicos para preservar informações críticas através das fases da tarefa, prevenindo a degradação de desempenho causada pela compactação automática arbitrária. Esta abordagem estratégica mantém a coerência ao trabalhar próximo aos limites de 200K+ tokens ou ao alternar entre tarefas não relacionadas.","ru":"Позволяет вручную выполнять компрессию контекста через логические интервалы для сохранения критически важной информации на протяжении этапов задачи, предотвращая снижение производительности из-за произвольной автоматической компрессии. Этот стратегический подход обеспечивает целостность при работе вблизи лимитов в 200K+ токенов или при переключении между несвязанными задачами.","ar":"يُمكّن من ضبط السياق يدويًا على فترات منطقية للحفاظ على المعلومات الحرجة خلال مراحل المهمة، مما يمنع تدهور الأداء الناتج عن الضغط التلقائي التعسفي. هذا النهج الاستراتيجي يحافظ على التماسك عند العمل بالقرب من حدود 200K+ رمز أو عند التبديل بين المهام غير المرتبطة."},"useCases":{"en":["Preserving research context before planning phases","Maintaining session coherence during multi-step implementations","Optimizing performance when approaching context limits"],"zh":["保存研究上下文以进行规划阶段","在多步骤实施过程中保持会话一致性","在接近上下文限制时优化性能"],"ja":["計画フェーズの前に研究コンテキストを保存する","マルチステップ実装中にセッションの一貫性を維持する","コンテキスト制限に近づいたときのパフォーマンスの最適化"],"ko":["계획 단계 전에 연구 컨텍스트를 보존","다단계 구현 중에 세션 일관성을 유지","컨텍스트 제한에 가까워 질 때 성능 최적화"],"es":["Preservar el contexto de investigación antes de las fases de planificación","Mantener la coherencia de la sesión durante implementaciones de múltiples pasos","Optimizar el rendimiento al acercarse a los límites de contexto"],"fr":["Préserver le contexte de recherche avant les phases de planification","Maintenir la cohérence de la session pendant les implémentations multi-étapes","Optimiser les performances à l''approche des limites de contexte"],"de":["Bewahrung des Forschungs-Kontextes vor Planungsphasen","Aufrechterhaltung der Sitzungskohärenz während mehrstufiger Implementierungen","Optimierung der Leistung bei Annäherung an Kontextgrenzen"],"pt":["Preservar o contexto de pesquisa antes das fases de planejamento","Manter a coerência da sessão durante implementações de várias etapas","Otimizar o desempenho ao se aproximar dos limites de contexto"],"ru":["Сохранение исследовательского контекста перед этапами планирования","Поддержание целостности сессии во время многоэтапной реализации","Оптимизация производительности при приближении к пределам контекста"],"ar":["الحفاظ على سياق البحث قبل مراحل التخطيط","الحفاظ على تماسك الجلسة أثناء عمليات التنفيذ متعددة الخطوات","تحسين الأداء عند الاقتراب من حدود السياق"]},"limitations":{"en":["Requires manual activation at strategic points","Depends on user recognizing logical workflow intervals","No automatic compaction capability"],"zh":["需要在战略点手动激活","依赖于用户识别逻辑工作流间隔","没有自动压缩功能"],"ja":["戦略的なポイントで手動でアクティブ化する必要がある","ユーザーが論理的なワークフロー間隔を認識することに依存する","自動圧縮機能がない"],"ko":["전략적 지점에서 수동으로 활성화해야 함","사용자가 논리적인 워크플로 간격을 인식하는 것에 의존","자동 압축 기능이 없음"],"es":["Requiere activación manual en puntos estratégicos","Depende de que el usuario reconozca intervalos lógicos del flujo de trabajo","Sin capacidad de compactación automática"],"fr":["Nécessite une activation manuelle à des points stratégiques","Dépend de la reconnaissance par l''utilisateur des intervalles logiques du flux de travail","Aucune capacité de compaction automatique"],"de":["Erfordert manuelle Aktivierung an strategischen Punkten","Hängt davon ab, dass der Benutzer logische Workflow-Intervalle erkennt","Keine automatische Kompaktierungsfähigkeit"],"pt":["Requer ativação manual em pontos estratégicos","Depende do usuário reconhecer intervalos lógicos do fluxo de trabalho","Nenhuma capacidade de compactação automática"],"ru":["Требует ручной активации в стратегических точках","Зависит от способности пользователя определять логические интервалы рабочего процесса","Отсутствие возможности автоматической компрессии"],"ar":["يتطلب التفعيل اليدوي في نقاط استراتيجية","يعتمد على قدرة المستخدم على التعرف على الفترات المنطقية لسير العمل","لا توجد قدرة على الضغط التلقائي"]},"version":4},"contentHash":"c83c4c9d60d30d508bbd2bf0c6ffa724b5fdac679addd4828b268892dc39dc1b","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":80}');
