INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/strategic-compact', 'strategic-compact', 'affaan-m', 'everything-claude-code', 'official', 'strategic-compact affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The strategic-compact skill suggests manual context compaction at logical workflow intervals instead of arbitrary auto-compaction. It benefits developers running long AI sessions with Claude, particularly those working on multi-phase tasks approaching context limits. Strategic Compact 技术建议在逻辑间隔手动压缩上下文，以保持任务阶段的上下文一致性 Strategic Compact 技術は、タスクの各段階で上下文を保持するために、論理的な間隔で手動でコンテキストを圧縮することを提案します Strategic Compact 기술은 작업 단계에서 컨텍스트를 유지하기 위해 논리적인 간격으로 수동으로 컨텍스트를 압축하는 것을 제안합니다 Strategic Compact es una habilidad de MCP que sugiere puntos lógicos para ejecutar el comando /compact manualmente. Esto preserva el contexto valioso en sesiones largas que se acercan al límite de 200K tokens, mejorando la coherencia en tareas multifase. Strategic Compact est une compétence MCP qui suggère des points logiques pour exécuter manuellement la commande /compact. Cela préserve le contexte précieux dans les longues sessions approchant la limite de 200K tokens, améliorant la cohérence pour les tâches multi-phases. Strategic Compact ist ein MCP-Skill, der logische Zeitpunkte für die manuelle Ausführung des /compact-Befehls vorschlägt. So wird wertvoller Kontext in langen Sitzungen nahe dem 200K-Token-Limit erhalten, was die Kohärenz bei mehrphasigen Aufgaben verbessert. O Strategic Compact é uma habilidade que sugere a compactação manual do contexto em intervalos lógicos, melhorando a produtividade e reduzindo a pressão de contexto Strategic Compact - это навык, который предлагает ручную компактацию контекста на логических интервалах,提高ая производительность и снижая контекстное давление Strategic Compact هو مهارة تقترح الضغط اليدوي للسياق في فترات منطقية، مما يحسن الإنتاجية ويقلل الضغط السياقي how to use strategic-compact skill what is strategic-compact MCP strategic-compact vs auto compaction strategic-compact alternative strategic-compact install guide strategic-compact setup for Claude manual context compaction AI agent managing Claude 200K token limit MCP server compaction strategies AIエージェント优化 Strategic Compact 技术 手动压缩上下文 长时间会话 多阶段任务 AI工具 开发者工具 Suggests manual /compact command execution at logical intervals Designed for long sessions approaching 200K+ token context limits Optimized for multi-phase tasks (research → plan → implement → test) Activates when switching between unrelated tasks within a session Recommends compaction after completing major milestones Triggers suggestions when responses slow down or lose coherence due to context pressure strategic-compact is an AI agent skill that recommends manual execution of the /compact command at strategic points in a workflow. It helps preserve context integrity through task phases in long sessions, especially when approaching the 200K+ token limit in Claude AI interactions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-tool-builder', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-tool-builder', 8290, 490, 80, '2026-03-06T05:28:53Z', '2026-03-06T05:39:59.814Z', 'ad8ea7af44a94503c52859696c1828046688ceb71fda4361725fcd64e7aeaa82', '{"id":"huggingface/skills/hugging-face-tool-builder","name":"hugging-face-tool-builder","description":{"en":"The hugging-face-tool-builder skill creates reusable command line scripts and utilities for using the Hugging Face API, allowing chaining, piping and intermediate processing. This skill benefits developers who want to automate tasks using the Hugging Face API.","zh":"Hugging Face工具构建器用于创建可重用的命令行脚本和工具，用于处理Hugging Face API数据","ja":"Hugging Face Tool Builderは、Hugging Face APIデータを処理するための再利用可能なコマンドラインスクリプトとツールを構築するために使用されます","ko":"Hugging Face 도구 빌더는 Hugging Face API 데이터를 처리하기 위한 재사용 가능한 명령줄 스크립트와 도구를 구축하는 데 사용됩니다","es":"El hugging-face-tool-builder permite crear scripts reutilizables para acceder a la API de Hugging Face y automatizar tareas. Utiliza el comando `hf` para acceder a Model y Dataset cards","fr":"L''outil hugging-face-tool-builder permet de créer des scripts réutilisables pour accéder à l''API Hugging Face et automatiser des tâches. Utilisez la commande `hf` pour accéder aux cartes de modèle et de jeu de données","de":"Das hugging-face-tool-builder-Tool ermöglicht die Erstellung wiederverwendbarer Skripte, um auf die Hugging Face-API zuzugreifen und Aufgaben zu automatisieren. Verwenden Sie den Befehl `hf`, um auf Model- und Dataset-Karten zuzugreifen","pt":"O Hugging Face Tool Builder é uma ferramenta para criar scripts reutilizáveis para automatizar tarefas com a API do Hugging Face","ru":"Hugging Face Tool Builder - это инструмент для создания повторно используемых скриптов для автоматизации задач с помощью API Hugging Face","ar":"هوجينج فايس تول بيلدر هو أداة لإنشاء سكريبتات قابلة لإعادة الاستخدام لتحسين الإنتاجية باستخدام واجهة برمجة تطبيقات هوجينج فايس"},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-tool-builder","description":"Use this skill when the user wants to build tool/scripts or achieve a task where using data from the Hugging Face API would help. This is especially useful when chaining or combining API calls or the task will be repeated/automated. This Skill creates a reusable script to fetch, enrich or process data.","bodyPreview":"# Hugging Face API Tool Builder\n\nYour purpose is now is to create reusable command line scripts and utilities for using the Hugging Face API, allowing chaining, piping and intermediate processing where helpful. You can access the API directly, as well as use the `hf` command line tool. Model and Dataset cards can be accessed from repositories directly.\n\n## Script Rules\n\nMake sure to follow these rules:\n - Scripts must take a `--help` command line argument to describe their inputs and outputs\n -","body":"# Hugging Face API Tool Builder\n\nYour purpose is now is to create reusable command line scripts and utilities for using the Hugging Face API, allowing chaining, piping and intermediate processing where helpful. You can access the API directly, as well as use the `hf` command line tool. Model and Dataset cards can be accessed from repositories directly.\n\n## Script Rules\n\nMake sure to follow these rules:\n - Scripts must take a `--help` command line argument to describe their inputs and outputs\n - Non-destructive scripts should be tested before handing over to the User\n - Shell scripts are preferred, but use Python or TSX if complexity or user need requires it.\n - IMPORTANT: Use the `HF_TOKEN` environment variable as an Authorization header. For example: `curl -H \"Authorization: Bearer ${HF_TOKEN}\" https://huggingface.co/api/`. This provides higher rate limits and appropriate authorization for data access.\n - Investigate the shape of the API results before commiting to a final design; make use of piping and chaining where composability would be an advantage - prefer simple solutions where possible.\n - Share usage examples once complete.\n\nBe sure to confirm User preferences where there are questions or clarifications needed.\n\n## Sample Scripts\n\nPaths below are relative to this skill directory.\n\nReference examples:\n- `references/hf_model_papers_auth.sh` — uses `HF_TOKEN` automatically and chains trending → model metadata → model card parsing with fallbacks; it demonstrates multi-step API usage plus auth hygiene for gated/private content.\n- `references/find_models_by_paper.sh` — optional `HF_TOKEN` usage via `--token`, consistent authenticated search, and a retry path when arXiv-prefixed searches are too narrow; it shows resilient query strategy and clear user-facing help.\n- `references/hf_model_card_frontmatter.sh` — uses the `hf` CLI to download model cards, extracts YAML frontmatter, and emits NDJSON summaries (license, pipeline tag, tags, gated prompt flag) for easy filtering.\n\nBaseline examples (ultra-simple, minimal logic, raw JSON output with `HF_TOKEN` header):\n- `references/baseline_hf_api.sh` — bash\n- `references/baseline_hf_api.py` — python\n- `references/baseline_hf_api.tsx` — typescript executable\n\nComposable utility (stdin → NDJSON):\n- `references/hf_enrich_models.sh` — reads model IDs from stdin, fetches metadata per ID, emits one JSON object per line for streaming pipelines.\n\nComposability through piping (shell-friendly JSON output):\n- `references/baseline_hf_api.sh 25 | jq -r ''.[].id'' | references/hf_enrich_models.sh | jq -s ''sort_by(.downloads) | reverse | .[:10]''`\n- `references/baseline_hf_api.sh 50 | jq ''[.[] | {id, downloads}] | sort_by(.downloads) | reverse | .[:10]''`\n- `printf ''%s\\n'' openai/gpt-oss-120b meta-llama/Meta-Llama-3.1-8B | references/hf_model_card_frontmatter.sh | jq -s ''map({id, license, has_extra_gated_prompt})''`\n\n## High Level Endpoints\n\nThe following are the main API endpoints available at `https://huggingface.co`\n\n```\n/api/datasets\n/api/models\n/api/spaces\n/api/collections\n/api/daily_papers\n/api/notifications\n/api/settings\n/api/whoami-v2\n/api/trending\n/oauth/userinfo\n```\n\n## Accessing the API\n\nThe API is documented with the OpenAPI standard at `https://huggingface.co/.well-known/openapi.json`.\n\n**IMPORTANT:** DO NOT ATTEMPT to read `https://huggingface.co/.well-known/openapi.json` directly as it is too large to process. \n\n**IMPORTANT** Use `jq` to query and extract relevant parts. For example, \n\n Command to Get All 160 Endpoints\n\n```bash\ncurl -s \"https://huggingface.co/.well-known/openapi.json\" | jq ''.paths | keys | sort''\n```\n\nModel Search Endpoint Details\n\n```bash\ncurl -s \"https://huggingface.co/.well-known/openapi.json\" | jq ''.paths[\"/api/models\"]''\n```\n\nYou can also query endpoints to see the shape of the data. When doing so constrain results to low numbers to make them easy to process, yet representative.\n\n## Using the HF command line tool\n\nThe `hf` command line tool gives you further access to Hugging Face repository content and infrastructure. \n\n```bash\n❯ hf --help\nUsage: hf [OPTIONS] COMMAND [ARGS]...\n\n  Hugging Face Hub CLI\n\nOptions:\n  --help                Show this message and exit.\n\nCommands:\n  auth                 Manage authentication (login, logout, etc.).\n  cache                Manage local cache directory.\n  download             Download files from the Hub.\n  endpoints            Manage Hugging Face Inference Endpoints.\n  env                  Print information about the environment.\n  jobs                 Run and manage Jobs on the Hub.\n  repo                 Manage repos on the Hub.\n  repo-files           Manage files in a repo on the Hub.\n  upload               Upload a file or a folder to the Hub.\n  upload-large-folder  Upload a large folder to the Hub.\n  version              Print information about the hf version.\n```\n\nThe `hf` CLI command has replaced the now deprecated `huggingface_hub` CLI command.\n"},"category":"official","lastSynced":"2026-03-06T05:39:59.814Z","seo":{"title":{"en":"hugging-face-tool-builder: CLI Script Builder for AI Agen...","zh":"Hugging Face工具构建器入门指南","ja":"Hugging Face Tool Builderのセットアップガイド","ko":"Hugging Face 도구 빌더 설정 가이드","es":"Guía de configuración de hugging-face-tool-builder para A...","fr":"Guide de démarrage rapide pour hugging-face-tool-builder ...","de":"Einrichtungsleitfaden für hugging-face-tool-builder KI-Tools","pt":"Guia de Configuração do Hugging Face Tool Builder para De...","ru":"ИИ Агенты: Настройка Hugging Face Tool Builder для Автома...","ar":"دليل إعداد هوجينج فايس تول بيلدر للبرمجة"},"description":{"en":"Discover how to automate Hugging Face API tasks with reusable scripts and utilities, and learn how to get started with the hugging-face-tool-builder skill to...","zh":"使用Hugging Face API构建可重用的命令行脚本和工具，实现数据处理和自动化","ja":"Hugging Face APIを使用して再利用可能なコマンドラインスクリプトとツールを構築する","ko":"Hugging Face API를 사용하여 데이터 처리와 자동화를 위한 재사용 가능한 명령줄 스크립트와 도구를 구축","es":"Aprende a crear scripts reutilizables con hugging-face-tool-builder para acceder a la API de Hugging Face y automatizar tareas","fr":"Découvrez comment créer des scripts réutilisables avec hugging-face-tool-builder pour accéder à l''API Hugging Face et automatiser des tâches","de":"Erfahren Sie, wie Sie mit hugging-face-tool-builder wiederverwendbare Skripte erstellen, um auf die Hugging Face-API zuzugreifen und Aufgaben zu automatisieren","pt":"Aprenda a criar scripts reutilizáveis com o Hugging Face Tool Builder para automatizar tarefas e melhorar a produtividade","ru":"Узнайте, как создать повторно используемые скрипты с помощью Hugging Face Tool Builder для автоматизации задач","ar":"تعلم كيفية إنشاء سكريبتات قابلة لإعادة الاستخدام باستخدام هوجينج فايس تول بيلدر لتحسين الإنتاجية"},"definition":{"en":"hugging-face-tool-builder is a skill that creates reusable command line scripts and utilities for using the Hugging Face API, enabling automation and efficient data processing.","zh":"Hugging Face工具构建器是一种用于构建可重用的命令行脚本和工具的技能，用于处理Hugging Face API数据","ja":"Hugging Face Tool Builderは、Hugging Face APIデータを処理するための再利用可能なコマンドラインスクリプトとツールを構築する技能です","ko":"Hugging Face 도구 빌더는 Hugging Face API 데이터를 처리하기 위한 재사용 가능한 명령줄 스크립트와 도구를 구축하는 데 사용되는 기술입니다","es":"El hugging-face-tool-builder es una herramienta para crear scripts reutilizables que acceden a la API de Hugging Face","fr":"L''outil hugging-face-tool-builder est un outil pour créer des scripts réutilisables qui accèdent à l''API Hugging Face","de":"Das hugging-face-tool-builder-Tool ist ein Tool zum Erstellen wiederverwendbarer Skripte, die auf die Hugging Face-API zugreifen","pt":"O que é Hugging Face Tool Builder? Uma ferramenta para criar scripts reutilizáveis para a API do Hugging Face","ru":"Что такое Hugging Face Tool Builder? Инструмент для создания повторно используемых скриптов для API Hugging Face","ar":"ما هو هوجينج فايس تول بيلدر؟ أداة لإنشاء سكريبتات قابلة لإعادة الاستخدام لواجهة برمجة تطبيقات هوجينج فايس"},"features":{"en":["Creates reusable command line scripts for Hugging Face API tasks","Supports chaining and piping of API calls","Allows intermediate processing of data using the `hf` command line tool","Enables access to Model and Dataset cards from repositories directly","Requires scripts to take a `--help` command line argument for documentation"],"zh":["支持Hugging Face API数据的处理和自动化","使用hf命令行工具访问Hugging Face API","支持模型和数据集卡片的访问","脚本必须支持--help命令行参数","支持数据的获取、丰富和处理"],"ja":["Hugging Face APIデータの処理と自動化をサポート","Hugging Face APIにアクセスするためのhfコマンドラインツールを使用","モデルとデータセットカードへのアクセスをサポート","スクリプトは--helpコマンドライン引数をサポートする必要がある","データの取得、豊富化、処理をサポート"],"ko":["Hugging Face API 데이터의 처리와 자동화를 지원","Hugging Face API에 접근하기 위한 hf 명령줄 도구를 사용","モデル과 데이터셋 카드에 대한 접근을 지원","스크립트는 --help 명령줄 인수를 지원해야 함","데이터의 가져오기, 보강, 처리를 지원"],"es":["Acceso a la API de Hugging Face","Uso de la commande `hf` para acceder a Model y Dataset cards","Creación de scripts reutilizables para tareas automatizadas","Soporte para procesamiento de datos y enriquecimiento","Compatibilidad con la línea de comandos para scripts personalizados"],"fr":["Accès à l''API Hugging Face","Utilisation de la commande `hf` pour accéder aux cartes de modèle et de jeu de données","Création de scripts réutilisables pour des tâches automatisées","Prise en charge du traitement de données et de l''enrichissement","Compatibilité avec la ligne de commande pour les scripts personnalisés"],"de":["Zugriff auf die Hugging Face-API","Verwendung des Befehls `hf` zum Zugriff auf Model- und Dataset-Karten","Erstellung wiederverwendbarer Skripte für automatisierte Aufgaben","Unterstützung für Datenverarbeitung und -anreicherung","Kompatibilität mit der Kommandozeile für benutzerdefinierte Skripte"],"pt":["Criação de scripts reutilizáveis para a API do Hugging Face","Acesso direto à API do Hugging Face","Uso do comando `hf` na linha de comando","Acesso a cartões de modelo e conjunto de dados de repositórios","Suporte a processamento intermediário e encadeamento de chamadas de API"],"ru":["Создание повторно используемых скриптов для API Hugging Face","Прямой доступ к API Hugging Face","Использование команды `hf` в командной строке","Доступ к карточкам модели и набора данных из репозиториев","Поддержка промежуточной обработки и цепочки вызовов API"],"ar":["إنشاء سكريبتات قابلة لإعادة الاستخدام لواجهة برمجة تطبيقات هوجينج فايس","الدخول المباشر لواجهة برمجة تطبيقات هوجينج فايس","استخدام الأمر `hf` في سطر الأوامر","الدخول إلى بطاقات النموذج و مجموعة البيانات من المستودعات","دعم المعالجة الوسيطة و سلسلة مكالمات واجهة برمجة التطبيقات"]},"keywords":{"en":["how to use hugging-face-tool-builder","hugging-face-tool-builder setup guide","hugging-face-tool-builder alternative","hugging face api automation","hugging-face-tool-builder install","hugging face api scripting","hugging-face-tool-builder vs api calls","hugging face api command line tool"],"zh":["Hugging Face工具构建器","Hugging Face API","命令行脚本","数据处理","自动化","AI工具","AIエージェント","Python","CLI"],"ja":["Hugging Face Tool Builder","Hugging Face API","コマンドラインスクリプト","データ処理","自動化","AIエージェント","Python","CLI","AIツール"],"ko":["Hugging Face 도구 빌더","Hugging Face API","명령줄 스크립트","데이터 처리","자동화","AI 도구","AI 에이전트","Python","CLI","인공지능 툴"],"es":["hugging face tool builder","agentes de ia","herramientas de ia","api de hugging face","scripts reutilizables","automatización de tareas","procesamiento de datos","enriquecimiento de datos"],"fr":["hugging face tool builder","outils d''ia","api hugging face","scripts réutilisables","automatisation de tâches","traitement de données","enrichissement de données"],"de":["hugging face tool builder","ki-tools","hugging face api","wiederverwendbare skripte","automatisierung von aufgaben","datenverarbeitung","datenanreicherung"],"pt":["Hugging Face Tool Builder","API Hugging Face","Scripts reutilizáveis","Automatização de tarefas","Desenvolvimento de software","Ferramentas de desenvolvimento","Programação em Python","Linha de comando"],"ru":["Hugging Face Tool Builder","API Hugging Face","Повторно используемые скрипты","Автоматизация задач","Разработка программного обеспечения","Инструменты разработки","Программирование на Python","Командная строка"],"ar":["هوجينج فايس تول بيلدر","واجهة برمجة تطبيقات هوجينج فايس","سكريبتات قابلة لإعادة الاستخدام","تأتمة المهام","برمجة تطبيقات","أدوات البرمجة","برمجة بايثون","سطر الأوامر"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Automation Agents building reusable data processing pipelines with Hugging Face models and datasets.","zh":"适合用于构建可重用数据处理管道的自动化代理，使用Hugging Face模型和数据集。","ja":"Hugging Faceモデルとデータセットを使用して再利用可能なデータ処理パイプラインを構築する自動化エージェントに適しています。","ko":"Hugging Face 모델과 데이터셋을 사용하여 재사용 가능한 데이터 처리 파이프라인을 구축하는 자동화 에이전트에 적합합니다.","es":"Ideal para Automation Agents que construyen pipelines de procesamiento de datos reutilizables con modelos y datasets de Hugging Face.","fr":"Idéal pour les Automation Agents construisant des pipelines de traitement de données réutilisables avec des modèles et des datasets Hugging Face.","de":"Ideal für Automation Agents, die wiederverwendbare Datenverarbeitungspipelines mit Hugging Face-Modellen und -Datensätzen erstellen.","pt":"Ideal para Agentes de Automação que constroem pipelines reutilizáveis de processamento de dados com modelos e datasets do Hugging Face.","ru":"Идеально подходит для Automation Agents, создающих многократно используемые конвейеры обработки данных с моделями и наборами данных Hugging Face.","ar":"مثالي لوكلاء الأتمتة الذين يقومون ببناء خطوط معالجة بيانات قابلة لإعادة الاستخدام مع نماذج ومجموعات بيانات Hugging Face."},"recommendation":{"en":"Enables creation of command-line scripts for chaining and piping Hugging Face API calls, supporting data fetching, enrichment, and intermediate processing operations using both direct API access and the hf CLI tool.","zh":"允许创建命令行脚本以连接和管道Hugging Face API调用，支持使用直接API访问和hf CLI工具进行数据获取、增强和中间处理操作。","ja":"Hugging Face APIコールの連結とパイプライン化のためのコマンドラインスクリプトの作成を可能にし、直接のAPIアクセスとhf CLIツールを使用してデータ取得、強化、そして中間処理操作をサポートします。","ko":"Hugging Face API 호출을 연결하고 파이프라인화하는 명령줄 스크립트를 생성할 수 있으며, 직접 API 액세스와 hf CLI 툴을 사용하여 데이터 가져오기, 보강 및 중간 처리 작업을 지원합니다.","es":"Permite la creación de scripts de command-line para encadenar y canalizar llamadas a la API de Hugging Face, soportando operaciones de data fetching, enrichment y intermediate processing utilizando tanto acceso directo a la API como la herramienta hf CLI.","fr":"Permet la création de scripts command-line pour enchaîner et canaliser les appels d''API Hugging Face, prenant en charge les opérations de data fetching, enrichment et intermediate processing en utilisant à la fois l''accès direct à l''API et l''outil hf CLI.","de":"Ermöglicht die Erstellung von command-line Skripten zum Verketten und Pipen von Hugging Face API-Aufrufen, unterstützt data fetching, enrichment und intermediate processing Operationen durch direkten API-Zugriff und das hf CLI-Tool.","pt":"Permite a criação de scripts de linha de comando para encadear e canalizar chamadas da API do Hugging Face, suportando operações de busca de dados, enriquecimento e processamento intermediário usando tanto o acesso direto à API quanto a ferramenta CLI hf.","ru":"Позволяет создавать скрипты командной строки для объединения в цепочки и конвейеризации вызовов API Hugging Face, поддерживая операции получения данных, обогащения и промежуточной обработки с использованием как прямого доступа к API, так и инструмента CLI hf.","ar":"يتيح إنشاء نصوص سطر الأوامر لربط وتحويل مكالمات Hugging Face API، دعم عمليات جلب البيانات والتخصيب والمعالجة المتوسطة باستخدام كل من الوصول المباشر إلى API وأداة CLI hf."},"useCases":{"en":["Automating repetitive model inference tasks","Building data processing pipelines with intermediate steps","Creating reusable utilities for dataset fetching and transformation","Chaining multiple Hugging Face API calls for complex workflows"],"zh":["自动化重复的模型推理任务","构建具有中间步骤的数据处理管道","创建用于数据获取和转换的可重用实用程序","连接多个Hugging Face API调用以进行复杂的工作流"],"ja":["繰り返しのモデル推論タスクの自動化","中間ステップを含むデータ処理パイプラインの構築","データ取得と変換のための再利用可能なユーティリティの作成","複雑なワークフローを実現するための複数のHugging Face APIコールの連結"],"ko":["반복되는 모델 추론 작업의 자동화","중간 단계를 포함하는 데이터 처리 파이프라인의 구축","데이터 가져오기 및 변환을 위한 재사용 가능한 유틸리티의 생성","복잡한 워크플로우를 위한 여러 Hugging Face API 호출의 연결"],"es":["Automatización de tareas repetitivas de model inference","Construcción de pipelines de procesamiento de datos con pasos intermedios","Creación de utilidades reutilizables para dataset fetching y transformation","Encadenamiento de múltiples llamadas a la API de Hugging Face para workflows complejos"],"fr":["Automatisation des tâches répétitives de model inference","Construction de pipelines de traitement de données avec des étapes intermédiaires","Création d''utilitaires réutilisables pour le dataset fetching et la transformation","Enchaînement de multiples appels d''API Hugging Face pour des workflows complexes"],"de":["Automatisierung sich wiederholender model inference Aufgaben","Erstellung von Datenverarbeitungspipelines mit Zwischenschritten","Entwicklung wiederverwendbarer Utilities für dataset fetching und transformation","Verkettung mehrerer Hugging Face API-Aufrufe für komplexe Workflows"],"pt":["Automatizando tarefas repetitivas de inferência de modelo","Construindo pipelines de processamento de dados com etapas intermediárias","Criando utilitários reutilizáveis para busca e transformação de datasets","Encadeando múltiplas chamadas da API do Hugging Face para fluxos de trabalho complexos"],"ru":["Автоматизация повторяющихся задач вывода модели","Построение конвейеров обработки данных с промежуточными этапами","Создание многократно используемых утилит для получения и преобразования наборов данных","Объединение в цепочку множественных вызовов API Hugging Face для сложных рабочих процессов"],"ar":["أتمتة مهام استدلال النموذج المتكررة","بناء خطوط معالجة البيانات بخطوات وسيطة","إنشاء أدوات مساعدة قابلة لإعادة الاستخدام لجلب وتحويل مجموعات البيانات","ربط مكالمات Hugging Face API المتعددة لسير العمل المعقد"]},"limitations":{"en":["Requires Hugging Face API access","Designed for command-line script generation","Depends on hf CLI tool availability"],"zh":["需要Hugging Face API访问","仅设计用于命令行脚本生成","依赖于hf CLI工具的可用性"],"ja":["Hugging Face APIへのアクセスが必要","コマンドラインスクリプトの生成のみに設計","hf CLIツールの可用性に依存"],"ko":["Hugging Face API 액세스가 필요","명령줄 스크립트 생성만을 위해 설계됨","hf CLI 툴의 가용성에 의존"],"es":["Requiere acceso a la API de Hugging Face","Diseñado para la generación de scripts de command-line","Depende de la disponibilidad de la herramienta hf CLI"],"fr":["Nécessite un accès à l''API Hugging Face","Conçu pour la génération de scripts command-line","Dépend de la disponibilité de l''outil hf CLI"],"de":["Erfordert Hugging Face API-Zugriff","Entworfen für die Generierung von command-line Skripten","Hängt von der Verfügbarkeit des hf CLI-Tools ab"],"pt":["Requer acesso à API do Hugging Face","Projetado para geração de scripts de linha de comando","Depende da disponibilidade da ferramenta CLI hf"],"ru":["Требуется доступ к API Hugging Face","Предназначен для генерации скриптов командной строки","Зависит от доступности инструмента CLI hf"],"ar":["يتطلب الوصول إلى Hugging Face API","مصمم لتوليد نصوص سطر الأوامر","يعتمد على توفر أداة CLI hf"]},"version":4},"contentHash":"ad8ea7af44a94503c52859696c1828046688ceb71fda4361725fcd64e7aeaa82","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":80}');
