INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-tool-builder', 'hugging-face-tool-builder', 'huggingface', 'skills', 'official', 'hugging-face-tool-builder huggingface skills official The hugging-face-tool-builder skill creates reusable command line scripts and utilities for using the Hugging Face API, allowing chaining, piping and intermediate processing. This skill benefits developers who want to automate tasks using the Hugging Face API. Hugging Face工具构建器用于创建可重用的命令行脚本和工具，用于处理Hugging Face API数据 Hugging Face Tool Builderは、Hugging Face APIデータを処理するための再利用可能なコマンドラインスクリプトとツールを構築するために使用されます Hugging Face 도구 빌더는 Hugging Face API 데이터를 처리하기 위한 재사용 가능한 명령줄 스크립트와 도구를 구축하는 데 사용됩니다 El hugging-face-tool-builder permite crear scripts reutilizables para acceder a la API de Hugging Face y automatizar tareas. Utiliza el comando `hf` para acceder a Model y Dataset cards L''outil hugging-face-tool-builder permet de créer des scripts réutilisables pour accéder à l''API Hugging Face et automatiser des tâches. Utilisez la commande `hf` pour accéder aux cartes de modèle et de jeu de données Das hugging-face-tool-builder-Tool ermöglicht die Erstellung wiederverwendbarer Skripte, um auf die Hugging Face-API zuzugreifen und Aufgaben zu automatisieren. Verwenden Sie den Befehl `hf`, um auf Model- und Dataset-Karten zuzugreifen O Hugging Face Tool Builder é uma ferramenta para criar scripts reutilizáveis para automatizar tarefas com a API do Hugging Face Hugging Face Tool Builder - это инструмент для создания повторно используемых скриптов для автоматизации задач с помощью API Hugging Face هوجينج فايس تول بيلدر هو أداة لإنشاء سكريبتات قابلة لإعادة الاستخدام لتحسين الإنتاجية باستخدام واجهة برمجة تطبيقات هوجينج فايس how to use hugging-face-tool-builder hugging-face-tool-builder setup guide hugging-face-tool-builder alternative hugging face api automation hugging-face-tool-builder install hugging face api scripting hugging-face-tool-builder vs api calls hugging face api command line tool Hugging Face工具构建器 Hugging Face API 命令行脚本 数据处理 自动化 AI工具 AIエージェント Python CLI Creates reusable command line scripts for Hugging Face API tasks Supports chaining and piping of API calls Allows intermediate processing of data using the `hf` command line tool Enables access to Model and Dataset cards from repositories directly Requires scripts to take a `--help` command line argument for documentation hugging-face-tool-builder is a skill that creates reusable command line scripts and utilities for using the Hugging Face API, enabling automation and efficient data processing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('google-labs-code/stitch-skills/stitch-loop', 'official', 'google-labs-code', 'stitch-skills', 'google-labs-code/stitch-skills', 'stitch-loop', 2204, 256, 80, '2026-03-06T05:29:41Z', '2026-03-06T05:49:14.015Z', '05f39ecf81b0664872e6f3d6be01c53cf8c1f8b9ef14c741fe01d1ac424ce634', '{"id":"google-labs-code/stitch-skills/stitch-loop","name":"stitch-loop","description":{"en":"The stitch-loop skill teaches AI agents to autonomously build websites using Stitch through an iterative loop pattern. It reads tasks from a baton file, generates pages, and prepares instructions for the next iteration, enabling continuous development cycles.","zh":"Stitch-Loop 是一个迭代网站构建的模式，通过自治的 baton-passing 循环，实现持续的网站开发","ja":"Stitch-Loop は、自治のバトンパス循環パターンを使用して継続的なウェブサイト開発を実現するウェブサイト構築のパターン","ko":"Stitch-Loop는 자율적인 baton-passing 루프 패턴을 사용하여 지속적인 사이트 구축을 달성하는 사이트 구축 패턴","es":"stitch-loop es una habilidad para IA Herramientas que enseña a los agentes a construir sitios web iterativamente usando Stitch. Implementa un patrón autónomo de bucle con paso de batón que lee tareas desde .stitch/next-prompt.md y genera páginas mediante herramientas MCP.","fr":"stitch-loop est une compétence pour Outils IA qui apprend aux agents à construire des sites web itérativement en utilisant Stitch. Il implémente un modèle autonome de boucle avec passage de témoin qui lit les tâches depuis .stitch/next-prompt.md et génère des pages via des outils MCP.","de":"stitch-loop ist eine Fähigkeit für KI Werkzeuge, die Agenten beibringt, Websites iterativ mit Stitch zu bauen. Es implementiert ein autonomes Schleifenmuster mit Staffelstab-Übergabe, das Aufgaben aus .stitch/next-prompt.md liest und Seiten über MCP-Tools generiert.","pt":"O Stitch-Loop é uma skill para agentes IA que automatiza a construção iterativa de websites usando Stitch. Implementa um padrão de ''baton-passing'' onde cada iteração lê uma tarefa, gera uma página e prepara a próxima.","ru":"Stitch-Loop — это навык для ИИ агентов, автоматизирующий итеративную сборку сайтов на Stitch. Реализует паттерн ''передачи эстафеты'' для генерации страниц и подготовки следующих задач.","ar":"Stitch-Loop هي مهارة لأدوات الذكاء الاصطناعي لأتمتة بناء مواقع الويب بشكل متكرر باستخدام Stitch. تنفذ نمط ''تمرير العصا'' حيث تقوم كل دورة بقراءة المهمة وإنشاء الصفحة وإعداد التكرار التالي."},"owner":"google-labs-code","repo":"stitch-skills","repoPath":"google-labs-code/stitch-skills","stars":2204,"forks":256,"updatedAt":"2026-03-06T05:29:41Z","topics":[],"skillMd":{"name":"stitch-loop","description":"Teaches agents to iteratively build websites using Stitch with an autonomous baton-passing loop pattern","bodyPreview":"# Stitch Build Loop\n\nYou are an **autonomous frontend builder** participating in an iterative site-building loop. Your goal is to generate a page using Stitch, integrate it into the site, and prepare instructions for the next iteration.\n\n## Overview\n\nThe Build Loop pattern enables continuous, autonomous website development through a \"baton\" system. Each iteration:\n1. Reads the current task from a baton file (`.stitch/next-prompt.md`)\n2. Generates a page using Stitch MCP tools\n3. Integrates the p","body":"# Stitch Build Loop\n\nYou are an **autonomous frontend builder** participating in an iterative site-building loop. Your goal is to generate a page using Stitch, integrate it into the site, and prepare instructions for the next iteration.\n\n## Overview\n\nThe Build Loop pattern enables continuous, autonomous website development through a \"baton\" system. Each iteration:\n1. Reads the current task from a baton file (`.stitch/next-prompt.md`)\n2. Generates a page using Stitch MCP tools\n3. Integrates the page into the site structure\n4. Writes the next task to the baton file for the next iteration\n\n## Prerequisites\n\n**Required:**\n- Access to the Stitch MCP Server\n- A Stitch project (existing or will be created)\n- A `.stitch/DESIGN.md` file (generate one using the `design-md` skill if needed)\n- A `.stitch/SITE.md` file documenting the site vision and roadmap\n\n**Optional:**\n- Chrome DevTools MCP Server — enables visual verification of generated pages\n\n## The Baton System\n\nThe `.stitch/next-prompt.md` file acts as a relay baton between iterations:\n\n```markdown\n---\npage: about\n---\nA page describing how jules.top tracking works.\n\n**DESIGN SYSTEM (REQUIRED):**\n[Copy from .stitch/DESIGN.md Section 6]\n\n**Page Structure:**\n1. Header with navigation\n2. Explanation of tracking methodology\n3. Footer with links\n```\n\n**Critical rules:**\n- The `page` field in YAML frontmatter determines the output filename\n- The prompt content must include the design system block from `.stitch/DESIGN.md`\n- You MUST update this file before completing your work to continue the loop\n\n## Execution Protocol\n\n### Step 1: Read the Baton\n\nParse `.stitch/next-prompt.md` to extract:\n- **Page name** from the `page` frontmatter field\n- **Prompt content** from the markdown body\n\n### Step 2: Consult Context Files\n\nBefore generating, read these files:\n\n| File | Purpose |\n|------|---------|\n| `.stitch/SITE.md` | Site vision, **Stitch Project ID**, existing pages (sitemap), roadmap |\n| `.stitch/DESIGN.md` | Required visual style for Stitch prompts |\n\n**Important checks:**\n- Section 4 (Sitemap) — Do NOT recreate pages that already exist\n- Section 5 (Roadmap) — Pick tasks from here if backlog exists\n- Section 6 (Creative Freedom) — Ideas for new pages if roadmap is empty\n\n### Step 3: Generate with Stitch\n\nUse the Stitch MCP tools to generate the page:\n\n1. **Discover namespace**: Run `list_tools` to find the Stitch MCP prefix\n2. **Get or create project**: \n   - If `.stitch/metadata.json` exists, use the `projectId` from it\n   - Otherwise, call `[prefix]:create_project`, then call `[prefix]:get_project` to retrieve full project details, and save them to `.stitch/metadata.json` (see schema below)\n   - After generating each screen, call `[prefix]:get_project` again and update the `screens` map in `.stitch/metadata.json` with each screen''s full metadata (id, sourceScreen, dimensions, canvas position)\n3. **Generate screen**: Call `[prefix]:generate_screen_from_text` with:\n   - `projectId`: The project ID\n   - `prompt`: The full prompt from the baton (including design system block)\n   - `deviceType`: `DESKTOP` (or as specified)\n4. **Retrieve assets**: Before downloading, check if `.stitch/designs/{page}.html` and `.stitch/designs/{page}.png` already exist:\n   - **If files exist**: Ask the user whether to refresh the designs from the Stitch project or reuse the existing local files. Only re-download if the user confirms.\n   - **If files do not exist**: Proceed with download:\n     - `htmlCode.downloadUrl` — Download and save as `.stitch/designs/{page}.html`\n      - `screenshot.downloadUrl` — Append `=w{width}` to the URL before downloading, where `{width}` is the `width` value from the screen metadata (Google CDN serves low-res thumbnails by default). Save as `.stitch/designs/{page}.png`\n\n### Step 4: Integrate into Site\n\n1. Move generated HTML from `.stitch/designs/{page}.html` to `site/public/{page}.html`\n2. Fix any asset paths to be relative to the public folder\n3. Update navigation:\n   - Find existing placeholder links (e.g., `href=\"#\"`) and wire them to the new page\n   - Add the new page to the global navigation if appropriate\n4. Ensure consistent headers/footers across all pages\n\n### Step 4.5: Visual Verification (Optional)\n\nIf the **Chrome DevTools MCP Server** is available, verify the generated page:\n\n1. **Check availability**: Run `list_tools` to see if `chrome*` tools are present\n2. **Start dev server**: Use Bash to start a local server (e.g., `npx serve site/public`)\n3. **Navigate to page**: Call `[chrome_prefix]:navigate` to open `http://localhost:3000/{page}.html`\n4. **Capture screenshot**: Call `[chrome_prefix]:screenshot` to capture the rendered page\n5. **Visual comparison**: Compare against the Stitch screenshot (`.stitch/designs/{page}.png`) for fidelity\n6. **Stop server**: Terminate the dev server process\n\n> **Note:** This step is optional. If Chrome DevTools MCP is not installed, skip to Step 5.\n\n### Step 5: Update Site Documentation\n\nModify `.stitch/SITE.md`:\n- Add the new page to Section 4 (Sitemap) with `[x]`\n- Remove any idea you consumed from Section 6 (Creative Freedom)\n- Update Section 5 (Roadmap) if you completed a backlog item\n\n### Step 6: Prepare the Next Baton (Critical)\n\n**You MUST update `.stitch/next-prompt.md` before completing.** This keeps the loop alive.\n\n1. **Decide the next page**: \n   - Check `.stitch/SITE.md` Section 5 (Roadmap) for pending items\n   - If empty, pick from Section 6 (Creative Freedom)\n   - Or invent something new that fits the site vision\n2. **Write the baton** with proper YAML frontmatter:\n\n```markdown\n---\npage: achievements\n---\nA competitive achievements page showing developer badges and milestones.\n\n**DESIGN SYSTEM (REQUIRED):**\n[Copy the entire design system block from .stitch/DESIGN.md]\n\n**Page Structure:**\n1. Header with title and navigation\n2. Badge grid showing unlocked/locked states\n3. Progress bars for milestone tracking\n```\n\n## File Structure Reference\n\n```\nproject/\n├── .stitch/\n│   ├── metadata.json   # Stitch project & screen IDs (persist this!)\n│   ├── DESIGN.md       # Visual design system (from design-md skill)\n│   ├── SITE.md         # Site vision, sitemap, roadmap\n│   ├── next-prompt.md  # The baton — current task\n│   └── designs/        # Staging area for Stitch output\n│       ├── {page}.html\n│       └── {page}.png\n└── site/public/        # Production pages\n    ├── index.html\n    └── {page}.html\n```\n\n### `.stitch/metadata.json` Schema\n\nThis file persists all Stitch identifiers so future iterations can reference them for edits or variants. Populate it by calling `[prefix]:get_project` after creating a project or generating screens.\n\n```json\n{\n  \"name\": \"projects/6139132077804554844\",\n  \"projectId\": \"6139132077804554844\",\n  \"title\": \"My App\",\n  \"visibility\": \"PRIVATE\",\n  \"createTime\": \"2026-03-04T23:11:25.514932Z\",\n  \"updateTime\": \"2026-03-04T23:34:40.400007Z\",\n  \"projectType\": \"PROJECT_DESIGN\",\n  \"origin\": \"STITCH\",\n  \"deviceType\": \"MOBILE\",\n  \"designTheme\": {\n    \"colorMode\": \"DARK\",\n    \"font\": \"INTER\",\n    \"roundness\": \"ROUND_EIGHT\",\n    \"customColor\": \"#40baf7\",\n    \"saturation\": 3\n  },\n  \"screens\": {\n    \"index\": {\n      \"id\": \"d7237c7d78f44befa4f60afb17c818c1\",\n      \"sourceScreen\": \"projects/6139132077804554844/screens/d7237c7d78f44befa4f60afb17c818c1\",\n      \"x\": 0,\n      \"y\": 0,\n      \"width\": 390,\n      \"height\": 1249\n    },\n    \"about\": {\n      \"id\": \"bf6a3fe5c75348e58cf21fc7a9ddeafb\",\n      \"sourceScreen\": \"projects/6139132077804554844/screens/bf6a3fe5c75348e58cf21fc7a9ddeafb\",\n      \"x\": 549,\n      \"y\": 0,\n      \"width\": 390,\n      \"height\": 1159\n    }\n  },\n  \"metadata\": {\n    \"userRole\": \"OWNER\"\n  }\n}\n```\n\n| Field | Description |\n|-------|-------------|\n| `name` | Full resource name (`projects/{id}`) |\n| `projectId` | Stitch project ID (from `create_project` or `get_project`) |\n| `title` | Human-readable project title |\n| `designTheme` | Design system tokens: color mode, font, roundness, custom color, saturation |\n| `deviceType` | Target device: `MOBILE`, `DESKTOP`, `TABLET` |\n| `screens` | Map of page name → screen object. Each screen includes `id`, `sourceScreen` (resource path for MCP calls), canvas position (`x`, `y`), and dimensions (`width`, `height`) |\n| `metadata.userRole` | User''s role on the project (`OWNER`, `EDITOR`, `VIEWER`) |\n\n## Orchestration Options\n\nThe loop can be driven by different orchestration layers:\n\n| Method | How it works |\n|--------|--------------|\n| **CI/CD** | GitHub Actions triggers on `.stitch/next-prompt.md` changes |\n| **Human-in-loop** | Developer reviews each iteration before continuing |\n| **Agent chains** | One agent dispatches to another (e.g., Jules API) |\n| **Manual** | Developer runs the agent repeatedly with the same repo |\n\nThe skill is orchestration-agnostic — focus on the pattern, not the trigger mechanism.\n\n## Design System Integration\n\nThis skill works best with the `design-md` skill:\n\n1. **First time setup**: Generate `.stitch/DESIGN.md` using the `design-md` skill from an existing Stitch screen\n2. **Every iteration**: Copy Section 6 (\"Design System Notes for Stitch Generation\") into your baton prompt\n3. **Consistency**: All generated pages will share the same visual language\n\n## Common Pitfalls\n\n- ❌ Forgetting to update `.stitch/next-prompt.md` (breaks the loop)\n- ❌ Recreating a page that already exists in the sitemap\n- ❌ Not including the design system block from `.stitch/DESIGN.md` in the prompt\n- ❌ Leaving placeholder links (`href=\"#\"`) instead of wiring real navigation\n- ❌ Forgetting to persist `.stitch/metadata.json` after creating a new project\n\n## Troubleshooting\n\n| Issue | Solution |\n|-------|----------|\n| Stitch generation fails | Check that the prompt includes the design system block |\n| Inconsistent styles | Ensure `.stitch/DESIGN.md` is up-to-date and copied correctly |\n| Loop stalls | Verify `.stitch/next-prompt.md` was updated with valid frontmatter |\n| Navigation broken | Check all internal links use correct relative paths |\n"},"category":"official","lastSynced":"2026-03-06T05:49:14.015Z","seo":{"title":{"en":"stitch-loop: Autonomous Website Build Loop Setup Guide | ...","zh":"Stitch-Loop 设计指南：迭代网站构建","ja":"Stitch-Loop セットアップガイド：継続的なウェブサイト開発","ko":"Stitch-Loop 설정 가이드: 반복적 사이트 구축","es":"stitch-loop: Guía de configuración para construcción autó...","fr":"stitch-loop: Guide de configuration pour la construction ...","de":"stitch-loop: Setup-Anleitung für autonomen Website-Bau","pt":"Stitch-Loop Setup Guide: Automação de Websites com Agente...","ru":"Stitch-Loop: Руководство по автоматизации сборки сайтов с...","ar":"Stitch-Loop: دليل الإعداد لأتمتة بناء المواقع باستخدام أد..."},"description":{"en":"Master the autonomous baton-passing loop pattern for iterative website building with Stitch. Learn how the `.stitch/next-prompt.md` baton file drives continu...","zh":"了解 Stitch-Loop 的工作原理，通过自治的 baton-passing 循环模式构建网站","ja":"Stitch-Loop の機能を学び、自治のバトンパス循環パターンで継続的なウェブサイト開発を実現","ko":"Stitch-Loop 기능을 숙지하고, 자율적인 baton-passing 루프 패턴으로 지속적인 사이트 구축을 달성","es":"Aprende a implementar stitch-loop para desarrollo web autónomo con IA Herramientas. Usa el patrón de bucle con paso de batón y Stitch MCP para generar página...","fr":"Apprenez à implémenter stitch-loop pour le développement web autonome avec Outils IA. Utilisez le modèle de boucle avec passage de témoin et Stitch MCP pour ...","de":"Erfahren Sie, wie Sie stitch-loop für autonome Webentwicklung mit KI Werkzeugen implementieren. Nutzen Sie das Schleifenmuster mit Staffelstab-Übergabe und S...","pt":"Aprenda a configurar o padrão autónomo Stitch-Loop para construir websites iterativamente. Usa um ficheiro baton (.stitch/next-prompt.md) e ferramentas MCP p...","ru":"Настройте автономный паттерн Stitch-Loop для итеративной сборки сайтов. Использует батон-файл (.stitch/next-prompt.md) и инструменты MCP для непрерывной инте...","ar":"تعلم كيفية إعداد نمط Stitch-Loop المستقل لبناء مواقع ويب بشكل متكرر. يستخدم ملف baton (.stitch/next-prompt.md) وأدوات MCP للتكامل المستمر للصفحات."},"definition":{"en":"stitch-loop is an AI agent skill that implements an autonomous iterative build pattern for website creation. It uses a baton file (`.stitch/next-prompt.md`) to pass tasks between iterations, generating pages with Stitch MCP tools and integrating them into the site structure.","zh":"Stitch-Loop 是一种使用 Stitch MCP 工具的自治前端构建器，用于迭代网站构建","ja":"Stitch-Loop は、Stitch MCP ツールを使用して継続的なウェブサイト開発を行う自治フロントエンドビルダー","ko":"Stitch-Loop는 Stitch MCP 도구를 사용하여 지속적인 사이트 구축을 수행하는 자율적인 프론트엔드 빌더","es":"stitch-loop es una habilidad técnica para IA Herramientas que implementa un patrón de bucle de construcción autónoma para desarrollo web. Los agentes leen instrucciones desde un archivo batón (.stitch/next-prompt.md), generan páginas usando Stitch MCP tools, y preparan la siguiente iteración para desarrollo continuo sin intervención humana.","fr":"stitch-loop est une compétence technique pour Outils IA qui implémente un modèle de boucle de construction autonome pour le développement web. Les agents lisent les instructions depuis un fichier témoin (.stitch/next-prompt.md), génèrent des pages en utilisant Stitch MCP tools, et préparent la prochaine itération pour un développement continu sans intervention humaine.","de":"stitch-loop ist eine technische Fähigkeit für KI Werkzeuge, die ein autonomes Bau-Schleifenmuster für Webentwicklung implementiert. Agenten lesen Anweisungen aus einer Baton-Datei (.stitch/next-prompt.md), generieren Seiten mit Stitch MCP tools und bereiten die nächste Iteration für kontinuierliche Entwicklung ohne menschliches Eingreifen vor.","pt":"Stitch-Loop é um padrão de desenvolvimento autónomo que ensina agentes IA a construir websites iterativamente com Stitch. Usa um ficheiro baton (.stitch/next-prompt.md) para coordenar um ciclo contínuo de geração e integração de páginas.","ru":"Stitch-Loop — это автономный паттерн разработки, который обучает ИИ агентов итеративной сборке сайтов на Stitch. Использует батон-файл (.stitch/next-prompt.md) для координации цикла генерации и интеграции страниц.","ar":"Stitch-Loop هو نمط تطوير مستقل يعلم أدوات الذكاء الاصطناعي بناء مواقع ويب بشكل متكرر باستخدام Stitch. يستخدم ملف baton (.stitch/next-prompt.md) لتنسيق دورة مستمرة من إنشاء الصفحات ودمجها."},"features":{"en":["Reads build tasks from the `.stitch/next-prompt.md` baton file","Generates pages using Stitch MCP tools","Integrates newly created pages into the existing site structure","Prepares instructions for the next iteration in the autonomous loop","Implements baton-passing pattern for continuous development cycles","Operates as part of an autonomous frontend builder workflow"],"zh":["使用 Stitch MCP 工具生成页面","自治的 baton-passing 循环模式","通过 `.stitch/next-prompt.md` 文件读取当前任务","将生成的页面集成到网站中","为下一个迭代准备指令"],"ja":["Stitch MCP ツールを使用してページを生成","自治のバトンパス循環パターン","`.stitch/next-prompt.md` ファイルから現在のタスクを読み取る","生成されたページをウェブサイトに統合","次のイテレーションに備えた指示の準備"],"ko":["Stitch MCP 도구를 사용하여 페이지 생성","자율적인 baton-passing 루프 패턴","`.stitch/next-prompt.md` 파일에서 현재 작업 읽기","생성된 페이지를 사이트에 통합","다음 반복을 위한 지침 준비"],"es":["Patrón autónomo de bucle con paso de batón para desarrollo iterativo","Lectura de tareas desde archivo .stitch/next-prompt.md","Generación de páginas web usando Stitch MCP tools","Integración automática de páginas en el sitio existente","Preparación de instrucciones para la siguiente iteración","Desarrollo continuo sin intervención humana requerida"],"fr":["Modèle autonome de boucle avec passage de témoin pour développement itératif","Lecture des tâches depuis le fichier .stitch/next-prompt.md","Génération de pages web utilisant Stitch MCP tools","Intégration automatique des pages dans le site existant","Préparation des instructions pour la prochaine itération","Développement continu sans intervention humaine requise"],"de":["Autonomes Schleifenmuster mit Staffelstab-Übergabe für iterative Entwicklung","Aufgabenlesen aus .stitch/next-prompt.md Datei","Seitengenerierung mit Stitch MCP tools","Automatische Integration von Seiten in bestehende Website","Vorbereitung von Anweisungen für nächste Iteration","Kontinuierliche Entwicklung ohne menschliches Eingreifen erforderlich"],"pt":["Padrão autónomo de baton-passing para desenvolvimento iterativo","Lê tarefas do ficheiro .stitch/next-prompt.md","Geração de páginas usando ferramentas Stitch MCP","Integração automática de novas páginas no site","Preparação autónoma de instruções para a próxima iteração","Habilita desenvolvimento contínuo e autónomo de websites"],"ru":["Автономный паттерн передачи эстафеты для итеративной разработки","Чтение задач из файла .stitch/next-prompt.md","Генерация страниц с помощью инструментов Stitch MCP","Автоматическая интеграция новых страниц в сайт","Автономная подготовка инструкций для следующей итерации","Обеспечивает непрерывную автономную разработку сайтов"],"ar":["نمط تمرير العصا المستقل للتطوير المتكرر","قراءة المهام من ملف .stitch/next-prompt.md","إنشاء الصفحات باستخدام أدوات Stitch MCP","دمج تلقائي للصفحات الجديدة في الموقع","إعداد تعليمات مستقلة للتكرار التالي","يمكن من التطوير المستمر والمستقل للمواقع"]},"keywords":{"en":["how to use stitch-loop baton system","what is stitch-loop autonomous builder","stitch-loop vs manual website building","stitch-loop alternative iterative patterns","stitch-loop install guide for AI agents","stitch-loop setup .stitch directory","autonomous website build loop pattern","Stitch MCP tools integration guide","AI agent iterative development workflow"],"zh":["Stitch-Loop","自治前端构建器","Stitch MCP","baton-passing 循环","网站构建","持续集成","AIエージェント","前端开发"],"ja":["Stitch-Loop","自治フロントエンドビルダー","Stitch MCP","バトンパス循環","ウェブサイト構築","継続的インテグレーション","AIエージェント","フロントエンド開発"],"ko":["Stitch-Loop","자율적인 프론트엔드 빌더","Stitch MCP","baton-passing 루프","사이트 구축","지속적인 통합","AI 에이전트","프론트엔드 개발"],"es":["stitch-loop setup","IA Herramientas desarrollo web autónomo","patrón bucle paso batón","Stitch MCP tools tutorial",".stitch/next-prompt.md configuración","desarrollo web iterativo IA","autonomous frontend builder","construcción sitios web automática"],"fr":["stitch-loop configuration","Outils IA développement web autonome","modèle boucle passage témoin","Stitch MCP tools tutoriel",".stitch/next-prompt.md configuration","développement web itératif IA","autonomous frontend builder","construction sites web automatique"],"de":["stitch-loop einrichten","KI Werkzeuge autonome Webentwicklung","Schleifenmuster Staffelstab-Übergabe","Stitch MCP tools Anleitung",".stitch/next-prompt.md Konfiguration","iterative Webentwicklung KI","autonomous frontend builder","automatische Website-Erstellung"],"pt":["stitch-loop agentes ia","automação desenvolvimento web stitch","padrão baton-passing stitch","ferramentas stitch mcp","construção iterativa websites","ficheiro next-prompt.md","desenvolvimento autónomo frontend","tutorial stitch-loop"],"ru":["stitch-loop ИИ агенты","автоматизация сборки сайтов stitch","паттерн передачи эстафеты stitch","инструменты stitch mcp","итеративная сборка сайтов","файл next-prompt.md","автономная фронтенд разработка","руководство stitch-loop"],"ar":["stitch-loop أدوات الذكاء الاصطناعي","أتمتة بناء مواقع stitch","نمط تمرير العصا stitch","أدوات stitch mcp","بناء متكرر للمواقع","ملف next-prompt.md","تطوير واجهة مستقل","برنامج تعليمي stitch-loop"]}},"agentAnalysis":{"suitability":{"en":"Ideal for autonomous frontend builder agents seeking to master iterative website development using Stitch with a baton-passing loop pattern","zh":"非常适合寻求使用 Stitch 和接力循环模式掌握迭代式网站开发的自主前端构建器 Agent","ja":"Stitch とバトンパッシングループパターンを使用した反復的なウェブサイト開発を習得しようとする自律型フロントエンドビルダーエージェントに最適です","ko":"배턴 전달 루프 패턴과 Stitch를 사용한 반복적 웹사이트 개발을 숙달하려는 자율형 프론트엔드 빌더 에이전트에 이상적입니다","es":"Ideal para constructores de frontend autónomos que buscan dominar el desarrollo de sitios web iterativo utilizando Stitch con un patrón de bucle de paso de testigo","fr":"Idéal pour les agents de construction de frontend autonomes qui cherchent à maîtriser le développement de sites web itératif en utilisant Stitch avec un modèle de boucle de passage de relais","de":"Ideal für autonome Frontend-Builder-Agenten, die iteratives Website-Entwicklung mit Stitch und einem Staffelübernahmemuster beherrschen möchten","pt":"Ideal para agentes de construção de frontend autônoma que buscam dominar o desenvolvimento de websites iterativo usando Stitch com um padrão de loop de passagem de bastão","ru":"Идеально для автономных агентов постройки frontend, стремящихся овладеть итеративным развитием сайтов, используя Stitch с шаблоном петли передачи жезла","ar":"مثالي لوسائل एजنت البناء الأمامي المستقل الذين يسعون إلى التعمق في تطوير الموقع الإلكتروني المتكرر باستخدام Stitch مع نمط حلقة تمرير العصا"},"recommendation":{"en":"Empowers agents to generate pages using Stitch MCP tools, integrate them into sites, and prepare instructions for the next iteration, leveraging the autonomous baton-passing loop pattern and reading from `.stitch/next-prompt.md` files","zh":"使 Agent 能够使用 Stitch MCP 工具生成页面，将其集成到站点中，并利用自主接力循环模式，通过读取 `.stitch/next-prompt.md` 文件来为下一次迭代准备指令","ja":"Stitch MCP ツールを使用してページを生成し、サイトに統合し、自律的なバトンパッシングループパターンを活用し、`.stitch/next-prompt.md` ファイルから読み取ることで、次の反復のための指示を準備する能力をエージェントに与えます","ko":"에이전트가 Stitch MCP 도구를 사용하여 페이지를 생성하고, 이를 사이트에 통합하며, 자율적 배턴 전달 루프 패턴을 활용하고 `.stitch/next-prompt.md` 파일을 읽어 후속 빌드 루프 반복을 위한 지시를 준비할 수 있도록 합니다","es":"Habilita a los agentes a generar páginas utilizando las herramientas Stitch MCP, integrarlas en sitios y preparar instrucciones para la próxima iteración, aprovechando el patrón de bucle de paso de testigo autónomo y leyendo desde archivos `.stitch/next-prompt.md`","fr":"Permet aux agents de générer des pages à l''aide des outils Stitch MCP, de les intégrer dans des sites et de préparer des instructions pour les prochaines itérations, en exploitant le modèle de boucle de passage de relais autonome et en lisant à partir de fichiers `.stitch/next-prompt.md`","de":"Ermächtigt Agenten, Seiten mit den Stitch-MCP-Tools zu generieren, sie in Sites zu integrieren und Anweisungen für die nächste Iteration vorzubereiten, indem sie das autonome Staffelübernahmemuster nutzen und aus Dateien `.stitch/next-prompt.md` lesen","pt":"Habilita os agentes a gerar páginas usando as ferramentas Stitch MCP, integrá-las em sites e preparar instruções para a próxima iteração, aproveitando o padrão de loop de passagem de bastão autônoma e lendo arquivos `.stitch/next-prompt.md`","ru":"Наделяет агентов возможностью генерировать страницы, используя инструменты Stitch MCP, интегрировать их в сайты и подготавливать инструкции для следующей итерации, используя автономный шаблон петли передачи жезла и читая файлы `.stitch/next-prompt.md`","ar":"يُمكّن الوكلاء من توليد الصفحات باستخدام أدوات Stitch MCP، ودمجها في المواقع الإلكترونية، وإعداد التعليمات للiteration التالية، مستفيداً من نمط الحلقة المستقلة لتمرير العصا والقراءة من ملفات `.stitch/next-prompt.md`"},"useCases":{"en":["Generating pages using Stitch MCP tools","Integrating pages into existing websites","Preparing instructions for subsequent build loop iterations"],"zh":["使用 Stitch MCP 工具生成页面","将页面集成到现有网站中","为后续构建循环迭代准备指令"],"ja":["Stitch MCP ツールを使用したページの生成","既存のウェブサイトへのページの統合","後続のビルドループ反復のための指示の準備"],"ko":["Stitch MCP 도구를 사용하여 페이지 생성","기존 웹사이트에 페이지 통합","후속 빌드 루프 반복을 위한 지시 사항 준비"],"es":["Generar páginas utilizando las herramientas Stitch MCP","Integrar páginas en sitios web existentes","Preparar instrucciones para iteraciones posteriores del bucle de compilación"],"fr":["Générer des pages à l''aide des outils Stitch MCP","Intégrer des pages dans des sites web existants","Préparer des instructions pour les itérations suivantes de la boucle de construction"],"de":["Seiten mit den Stitch-MCP-Tools generieren","Seiten in bestehende Websites integrieren","Anweisungen für nachfolgende Build-Schleifen-Iterationen vorbereiten"],"pt":["Geração de páginas usando as ferramentas Stitch MCP","Integração de páginas em sites existentes","Preparação de instruções para iterações subsequentes do loop de construção"],"ru":["Генерация страниц, используя инструменты Stitch MCP","Интеграция страниц в существующие сайты","Подготовка инструкций для последующих итераций цикла построения"],"ar":["توليد الصفحات باستخدام أدوات Stitch MCP","دمج الصفحات في المواقع الإلكترونية الحالية","إعداد التعليمات للiterations اللاحقة من دورة البناء"]},"limitations":{"en":["Requires Stitch MCP tools","Dependent on `.stitch/next-prompt.md` file format","Autonomous loop pattern may require additional configuration"],"zh":["需要 Stitch MCP 工具","依赖于 `.stitch/next-prompt.md` 文件格式","自主循环模式可能需要额外配置"],"ja":["Stitch MCP ツールが必要","`.stitch/next-prompt.md` ファイル形式に依存","自律ループパターンは追加の設定が必要な場合があります"],"ko":["Stitch MCP 도구 필요","`.stitch/next-prompt.md` 파일 형식에 종속됨","자율 루프 패턴은 추가 구성이 필요할 수 있음"],"es":["Requiere las herramientas Stitch MCP","Dependiente del formato de archivo `.stitch/next-prompt.md`","El patrón de bucle autónomo puede requerir configuración adicional"],"fr":["Nécessite les outils Stitch MCP","Dépend du format de fichier `.stitch/next-prompt.md`","Le modèle de boucle autonome peut nécessiter une configuration supplémentaire"],"de":["Benötigt die Stitch-MCP-Tools","Abhängig vom Dateiformat `.stitch/next-prompt.md`","Das autonome Staffelübernahmemuster kann eine zusätzliche Konfiguration erfordern"],"pt":["Exige as ferramentas Stitch MCP","Dependente do formato de arquivo `.stitch/next-prompt.md`","O padrão de loop autônoma pode requerer configuração adicional"],"ru":["Требует инструментов Stitch MCP","Зависит от формата файла `.stitch/next-prompt.md`","Автономный шаблон петли может потребовать дополнительной настройки"],"ar":["يتطلب أدوات Stitch MCP","يعتمد على تنسيق ملف `.stitch/next-prompt.md`","نمط الحلقة المستقلة قد يتطلب cấu trúc إضافية"]},"version":4},"contentHash":"05f39ecf81b0664872e6f3d6be01c53cf8c1f8b9ef14c741fe01d1ac424ce634","repoEtag":"W/\"bb47617e3029a9b4385327f9dc9702c508cf6c4fbacc7fed320cabd4b144bac3\"","qualityScore":80}');
