INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-labs-code/stitch-skills/stitch-loop', 'stitch-loop', 'google-labs-code', 'stitch-skills', 'official', 'stitch-loop google-labs-code stitch-skills official The stitch-loop skill teaches AI agents to autonomously build websites using Stitch through an iterative loop pattern. It reads tasks from a baton file, generates pages, and prepares instructions for the next iteration, enabling continuous development cycles. Stitch-Loop 是一个迭代网站构建的模式，通过自治的 baton-passing 循环，实现持续的网站开发 Stitch-Loop は、自治のバトンパス循環パターンを使用して継続的なウェブサイト開発を実現するウェブサイト構築のパターン Stitch-Loop는 자율적인 baton-passing 루프 패턴을 사용하여 지속적인 사이트 구축을 달성하는 사이트 구축 패턴 stitch-loop es una habilidad para IA Herramientas que enseña a los agentes a construir sitios web iterativamente usando Stitch. Implementa un patrón autónomo de bucle con paso de batón que lee tareas desde .stitch/next-prompt.md y genera páginas mediante herramientas MCP. stitch-loop est une compétence pour Outils IA qui apprend aux agents à construire des sites web itérativement en utilisant Stitch. Il implémente un modèle autonome de boucle avec passage de témoin qui lit les tâches depuis .stitch/next-prompt.md et génère des pages via des outils MCP. stitch-loop ist eine Fähigkeit für KI Werkzeuge, die Agenten beibringt, Websites iterativ mit Stitch zu bauen. Es implementiert ein autonomes Schleifenmuster mit Staffelstab-Übergabe, das Aufgaben aus .stitch/next-prompt.md liest und Seiten über MCP-Tools generiert. O Stitch-Loop é uma skill para agentes IA que automatiza a construção iterativa de websites usando Stitch. Implementa um padrão de ''baton-passing'' onde cada iteração lê uma tarefa, gera uma página e prepara a próxima. Stitch-Loop — это навык для ИИ агентов, автоматизирующий итеративную сборку сайтов на Stitch. Реализует паттерн ''передачи эстафеты'' для генерации страниц и подготовки следующих задач. Stitch-Loop هي مهارة لأدوات الذكاء الاصطناعي لأتمتة بناء مواقع الويب بشكل متكرر باستخدام Stitch. تنفذ نمط ''تمرير العصا'' حيث تقوم كل دورة بقراءة المهمة وإنشاء الصفحة وإعداد التكرار التالي. how to use stitch-loop baton system what is stitch-loop autonomous builder stitch-loop vs manual website building stitch-loop alternative iterative patterns stitch-loop install guide for AI agents stitch-loop setup .stitch directory autonomous website build loop pattern Stitch MCP tools integration guide AI agent iterative development workflow Stitch-Loop 自治前端构建器 Stitch MCP baton-passing 循环 网站构建 持续集成 AIエージェント 前端开发 Reads build tasks from the `.stitch/next-prompt.md` baton file Generates pages using Stitch MCP tools Integrates newly created pages into the existing site structure Prepares instructions for the next iteration in the autonomous loop Implements baton-passing pattern for continuous development cycles Operates as part of an autonomous frontend builder workflow stitch-loop is an AI agent skill that implements an autonomous iterative build pattern for website creation. It uses a baton file (`.stitch/next-prompt.md`) to pass tasks between iterations, generating pages with Stitch MCP tools and integrating them into the site structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/workers-best-practices', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'workers-best-practices', 535, 66, 80, '2026-03-06T05:33:24Z', '2026-03-06T05:58:58.713Z', '099432ff265ff6080327ef0b392c118b835d2a5bda98a7de07e1afd115ed6458', '{"id":"cloudflare/skills/workers-best-practices","name":"workers-best-practices","description":{"en":"This AI agent skill analyzes and authors Cloudflare Workers code against production best practices. It is designed for developers writing new Workers, reviewing code, configuring wrangler.jsonc, or checking for common anti-patterns, with a bias for retrieval from live Cloudflare documentation.","zh":"Cloudflare Workers 最佳实践是一种 AI 工具，帮助您优化 Workers 代码，确保其符合生产环境的最佳实践","ja":"Cloudflare Workers ベストプラクティスは、Workers コードを最適化する AI エージェントです。生産環境のベストプラクティスに従ったコードを保証します","ko":"Cloudflare Workers 최고의 실践은 Workers 코드를 최적화하는 AI 에이전트입니다. 생산 환경의 최고의 실践에 따라 코드를 보장합니다","es":"El skill ''workers-best-practices'' ayuda a los desarrolladores a escribir y revisar código de Cloudflare Workers siguiendo las mejores prácticas de producción","fr":"Le skill ''workers-best-practices'' aide les développeurs à écrire et réviser du code Cloudflare Workers en suivant les meilleures pratiques de production","de":"Der Skill ''workers-best-practices'' unterstützt Entwickler dabei, Cloudflare-Worker-Code zu schreiben und zu überprüfen, indem er die besten Produktionspraktiken einhält","pt":"O workers-best-practices é uma habilidade que revisa e autoriza código Cloudflare Workers contra as melhores práticas de produção. Carregue ao escrever novo código Workers ou ao revisar código existente.","ru":"Workers-best-practices — это навык, который проверяет и авторизует код Cloudflare Workers на соответствие лучшим практикам производства. Загрузите при написании нового кода Workers или при проверке существующего кода.","ar":"workers-best-practices هو مهارة تقوم بمراجعة وتصديق رمز Cloudflare Workers مقابل أفضل الممارسات الإنتاجية. حمل عند كتابة رمز Workers جديد أو عند مراجعة رمز موجود."},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"workers-best-practices","description":"Reviews and authors Cloudflare Workers code against production best practices. Load when writing new Workers, reviewing Worker code, configuring wrangler.jsonc, or checking for common Workers anti-patterns (streaming, floating promises, global state, secrets, bindings, observability). Biases towards retrieval from Cloudflare docs over pre-trained knowledge.","bodyPreview":"Your knowledge of Cloudflare Workers APIs, types, and configuration may be outdated. **Prefer retrieval over pre-training** for any Workers code task — writing or reviewing.\n\n## Retrieval Sources\n\nFetch the **latest** versions before writing or reviewing Workers code. Do not rely on baked-in knowledge for API signatures, config fields, or binding shapes.\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Workers best practices | Fetch `https://developers.cloudflare.c","body":"Your knowledge of Cloudflare Workers APIs, types, and configuration may be outdated. **Prefer retrieval over pre-training** for any Workers code task — writing or reviewing.\n\n## Retrieval Sources\n\nFetch the **latest** versions before writing or reviewing Workers code. Do not rely on baked-in knowledge for API signatures, config fields, or binding shapes.\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Workers best practices | Fetch `https://developers.cloudflare.com/workers/best-practices/workers-best-practices/` | Canonical rules, patterns, anti-patterns |\n| Workers types | See `references/review.md` for retrieval steps | API signatures, handler types, binding types |\n| Wrangler config schema | `node_modules/wrangler/config-schema.json` | Config fields, binding shapes, allowed values |\n| Cloudflare docs | Search tool or `https://developers.cloudflare.com/workers/` | API reference, compatibility dates/flags |\n\n## FIRST: Fetch Latest References\n\nBefore reviewing or writing Workers code, retrieve the current best practices page and relevant type definitions. If the project''s `node_modules` has an older version, **prefer the latest published version**.\n\n```bash\n# Fetch latest workers types\nmkdir -p /tmp/workers-types-latest && \\\n  npm pack @cloudflare/workers-types --pack-destination /tmp/workers-types-latest && \\\n  tar -xzf /tmp/workers-types-latest/cloudflare-workers-types-*.tgz -C /tmp/workers-types-latest\n# Types at /tmp/workers-types-latest/package/index.d.ts\n```\n\n## Reference Documentation\n\n- `references/rules.md` — all best practice rules with code examples and anti-patterns\n- `references/review.md` — type validation, config validation, binding access patterns, review process\n\n## Rules Quick Reference\n\n### Configuration\n\n| Rule | Summary |\n|------|---------|\n| Compatibility date | Set `compatibility_date` to today on new projects; update periodically on existing ones |\n| nodejs_compat | Enable the `nodejs_compat` flag — many libraries depend on Node.js built-ins |\n| wrangler types | Run `wrangler types` to generate `Env` — never hand-write binding interfaces |\n| Secrets | Use `wrangler secret put`, never hardcode secrets in config or source |\n| wrangler.jsonc | Use JSONC config for non-secret settings — newer features are JSON-only |\n\n### Request & Response Handling\n\n| Rule | Summary |\n|------|---------|\n| Streaming | Stream large/unknown payloads — never `await response.text()` on unbounded data |\n| waitUntil | Use `ctx.waitUntil()` for post-response work; do not destructure `ctx` |\n\n### Architecture\n\n| Rule | Summary |\n|------|---------|\n| Bindings over REST | Use in-process bindings (KV, R2, D1, Queues) — not the Cloudflare REST API |\n| Queues & Workflows | Move async/background work off the critical path |\n| Service bindings | Use service bindings for Worker-to-Worker calls — not public HTTP |\n| Hyperdrive | Always use Hyperdrive for external PostgreSQL/MySQL connections |\n\n### Observability\n\n| Rule | Summary |\n|------|---------|\n| Logs & Traces | Enable `observability` in config with `head_sampling_rate`; use structured JSON logging |\n\n### Code Patterns\n\n| Rule | Summary |\n|------|---------|\n| No global request state | Never store request-scoped data in module-level variables |\n| Floating promises | Every Promise must be `await`ed, `return`ed, `void`ed, or passed to `ctx.waitUntil()` |\n\n### Security\n\n| Rule | Summary |\n|------|---------|\n| Web Crypto | Use `crypto.randomUUID()` / `crypto.getRandomValues()` — never `Math.random()` for security |\n| No passThroughOnException | Use explicit try/catch with structured error responses |\n\n## Anti-Patterns to Flag\n\n| Anti-pattern | Why it matters |\n|-------------|----------------|\n| `await response.text()` on unbounded data | Memory exhaustion — 128 MB limit |\n| Hardcoded secrets in source or config | Credential leak via version control |\n| `Math.random()` for tokens/IDs | Predictable, not cryptographically secure |\n| Bare `fetch()` without `await` or `waitUntil` | Floating promise — dropped result, swallowed error |\n| Module-level mutable variables for request state | Cross-request data leaks, stale state, I/O errors |\n| Cloudflare REST API from inside a Worker | Unnecessary network hop, auth overhead, added latency |\n| `ctx.passThroughOnException()` as error handling | Hides bugs, makes debugging impossible |\n| Hand-written `Env` interface | Drifts from actual wrangler config bindings |\n| Direct string comparison for secret values | Timing side-channel — use `crypto.subtle.timingSafeEqual` |\n| Destructuring `ctx` (`const { waitUntil } = ctx`) | Loses `this` binding — throws \"Illegal invocation\" at runtime |\n| `any` on `Env` or handler params | Defeats type safety for all binding access |\n| `as unknown as T` double-cast | Hides real type incompatibilities — fix the design |\n| `implements` on platform base classes (instead of `extends`) | Legacy — loses `this.ctx`, `this.env`. Applies to DurableObject, WorkerEntrypoint, Workflow |\n| `env.X` inside platform base class | Should be `this.env.X` in classes extending DurableObject, WorkerEntrypoint, etc. |\n\n## Review Workflow\n\n1. **Retrieve** — fetch latest best practices page, workers types, and wrangler schema\n2. **Read full files** — not just diffs; context matters for binding access patterns\n3. **Check types** — binding access, handler signatures, no `any`, no unsafe casts (see `references/review.md`)\n4. **Check config** — compatibility_date, nodejs_compat, observability, secrets, binding-code consistency\n5. **Check patterns** — streaming, floating promises, global state, serialization boundaries\n6. **Check security** — crypto usage, secret handling, timing-safe comparisons, error handling\n7. **Validate with tools** — `npx tsc --noEmit`, lint for `no-floating-promises`\n8. **Reference rules** — see `references/rules.md` for each rule''s correct pattern\n\n## Scope\n\nThis skill covers Workers-specific best practices and code review. For related topics:\n\n- **Durable Objects**: load the `durable-objects` skill\n- **Workflows**: see [Rules of Workflows](https://developers.cloudflare.com/workflows/build/rules-of-workflows/)\n- **Wrangler CLI commands**: load the `wrangler` skill\n\n## Principles\n\n- **Be certain.** Retrieve before flagging. If unsure about an API, config field, or pattern, fetch the docs first.\n- **Provide evidence.** Reference line numbers, tool output, or docs links.\n- **Focus on what developers will copy.** Workers code in examples and docs gets pasted into production.\n- **Correctness over completeness.** A concise example that works beats a comprehensive one with errors.\n"},"category":"official","lastSynced":"2026-03-06T05:58:58.713Z","seo":{"title":{"en":"workers-best-practices: AI Code Review & Configuration Gu...","zh":"Cloudflare Workers 最佳实践设置指南","ja":"Cloudflare Workers ベストプラクティス設定ガイド","ko":"Cloudflare Workers 최고의 실践 설정 가이드","es":"Guía de Mejores Prácticas para Cloudflare Workers","fr":"Guide des Meilleures Pratiques pour Cloudflare Workers","de":"Leitfaden für Best Practices bei Cloudflare Workers","pt":"Guia de Configuração de workers-best-practices para Desen...","ru":"Настойка ИИ Агентов workers-best-practices для Разработчиков","ar":"دليل إعداد workers-best-practices للأشخاص المتقدمين"},"description":{"en":"An AI agent skill that audits Cloudflare Workers code for anti-patterns like floating promises & global state. It retrieves live docs for wrangler.jsonc conf...","zh":"学习如何使用 Cloudflare Workers 最佳实践来优化您的代码，包括加载时检查和配置 wrangler.jsonc","ja":"Cloudflare Workers のベストプラクティスを使用してコードを最適化する方法を学びます。ロード時チェックや wrangler.jsonc の設定など","ko":"Cloudflare Workers 최고의 실践을 사용하여 코드를 최적화하는 방법을 배우세요. 로드 시检查 및 wrangler.jsonc 설정 등","es":"Aprende a configurar y optimizar tus Workers de Cloudflare con nuestras mejores prácticas y recomendaciones","fr":"Découvrez comment configurer et optimiser vos Workers Cloudflare avec nos meilleures pratiques et recommandations","de":"Erfahren Sie, wie Sie Ihre Cloudflare-Worker konfigurieren und optimieren können, mit unseren Best Practices und Empfehlungen","pt":"Aprenda a configurar workers-best-practices para melhorar a eficiência do seu código Cloudflare Workers. Descubra as melhores práticas e evite anti-padrões c...","ru":"Узнайте, как настроить workers-best-practices для улучшения производительности вашего кода Cloudflare Workers. Откройте для себя лучшие практики и избегайте ...","ar":"تعلم كيفية إعداد workers-best-practices لتحسين كفاءة код Cloudflare Workers. اكتشف أفضل الممارسات وتجنب الأنماط المضادة الشائعة."},"de