INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/workers-best-practices', 'workers-best-practices', 'cloudflare', 'skills', 'official', 'workers-best-practices cloudflare skills official agents cloudflare skills workers This AI agent skill analyzes and authors Cloudflare Workers code against production best practices. It is designed for developers writing new Workers, reviewing code, configuring wrangler.jsonc, or checking for common anti-patterns, with a bias for retrieval from live Cloudflare documentation. Cloudflare Workers 最佳实践是一种 AI 工具，帮助您优化 Workers 代码，确保其符合生产环境的最佳实践 Cloudflare Workers ベストプラクティスは、Workers コードを最適化する AI エージェントです。生産環境のベストプラクティスに従ったコードを保証します Cloudflare Workers 최고의 실践은 Workers 코드를 최적화하는 AI 에이전트입니다. 생산 환경의 최고의 실践에 따라 코드를 보장합니다 El skill ''workers-best-practices'' ayuda a los desarrolladores a escribir y revisar código de Cloudflare Workers siguiendo las mejores prácticas de producción Le skill ''workers-best-practices'' aide les développeurs à écrire et réviser du code Cloudflare Workers en suivant les meilleures pratiques de production Der Skill ''workers-best-practices'' unterstützt Entwickler dabei, Cloudflare-Worker-Code zu schreiben und zu überprüfen, indem er die besten Produktionspraktiken einhält O workers-best-practices é uma habilidade que revisa e autoriza código Cloudflare Workers contra as melhores práticas de produção. Carregue ao escrever novo código Workers ou ao revisar código existente. Workers-best-practices — это навык, который проверяет и авторизует код Cloudflare Workers на соответствие лучшим практикам производства. Загрузите при написании нового кода Workers или при проверке существующего кода. workers-best-practices هو مهارة تقوم بمراجعة وتصديق رمز Cloudflare Workers مقابل أفضل الممارسات الإنتاجية. حمل عند كتابة رمز Workers جديد أو عند مراجعة رمز موجود. workers-best-practices install how to use workers-best-practices Cloudflare Workers code review wrangler.jsonc configuration guide workers-best-practices vs eslint what is workers-best-practices Cloudflare Workers floating promises workers-best-practices setup guide Cloudflare Workers bindings best practices Cloudflare Workers 最佳实践 AI 工具 代码优化 生产环境 wrangler.jsonc Workers 代码 性能优化 代码检验 Reviews code for common Workers anti-patterns like streaming issues and floating promises Checks for proper implementation of global state and secrets management Validates bindings configuration and wrangler.jsonc setup Prioritizes retrieval from live Cloudflare docs for up-to-date API signatures Biases towards fetching the latest best practices from developers.cloudflare.com workers-best-practices is an AI agent skill that reviews and authors Cloudflare Workers code. It checks for production best practices, common anti-patterns, and proper configuration of wrangler.jsonc, bindings, and secrets, prioritizing retrieval from the latest Cloudflare docs over pre-trained knowledge.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/wrangler', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'wrangler', 535, 66, 80, '2026-03-06T05:33:24Z', '2026-03-06T05:59:56.408Z', 'cf7427585e31779f2b6747f0bf97903b161f2f3bd36b62fef83766d6e49d0fb1', '{"id":"cloudflare/skills/wrangler","name":"wrangler","description":{"en":"This AI agent skill provides real-time access to the official Wrangler CLI documentation, ensuring commands for deploying and managing Cloudflare Workers, KV, R2, and D1 are always current. It is essential for developers and AI agents automating Cloudflare''s serverless platform to prevent syntax ...","zh":"Wrangler 是 Cloudflare Workers CLI，用于部署、开发和管理 Workers、KV、R2、D1 等。通过 Cloudflare 文档获取最新信息","ja":"Wrangler は Cloudflare Workers CLI で、Workers、KV、R2、D1 などのデプロイ、開発、管理に使用されます。Cloudflare ドキュメントから最新情報を取得します","ko":"Wrangler는 Cloudflare Workers CLI로서 Workers, KV, R2, D1 등을 배포, 개발 및 관리하는 데 사용됩니다. Cloudflare 문서에서 최신 정보를 얻습니다","es":"Wrangler es una herramienta de línea de comandos para desplegar y gestionar Workers, KV, R2 y otros servicios de Cloudflare. Asegúrate de cargar la documentación oficial antes de ejecutar comandos.","fr":"Wrangler est un outil en ligne de commande pour déployer et gérer des Workers, KV, R2 et d''autres services Cloudflare. Assurez-vous de charger la documentation officielle avant d''exécuter des commandes.","de":"Wrangler ist ein Befehlszeilen-Tool zum Bereitstellen und Verwalten von Workers, KV, R2 und anderen Cloudflare-Diensten. Stellen Sie sicher, dass Sie die offizielle Dokumentation laden, bevor Sie Befehle ausführen.","pt":"Wrangler é a CLI oficial para desenvolver, implantar e gerenciar Workers da Cloudflare e seus serviços associados, como KV, R2, D1 e Vectorize. Prioriza a recuperação da documentação oficial para garantir a sintaxe correta.","ru":"Wrangler — это официальный интерфейс командной строки для разработки, развертывания и управления Cloudflare Workers и связанными сервисами, такими как KV, R2, D1 и Vectorize. Предпочитает получение информации из официальной документации для обеспечения правильного синтаксиса.","ar":"Wrangler هو واجهة سطر الأوامر الرسمية لتطوير ونشر وإدارة Cloudflare Workers والخدمات المرتبطة بها مثل KV وR2 وD1 وVectorize. يفضل استرجاع المعلومات من الوثائق الرسمية لضمان الصيغة الصحيحة."},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"wrangler","description":"Cloudflare Workers CLI for deploying, developing, and managing Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines, and Secrets Store. Load before running wrangler commands to ensure correct syntax and best practices. Biases towards retrieval from Cloudflare docs over pre-trained knowledge.","bodyPreview":"# Wrangler CLI\n\nYour knowledge of Wrangler CLI flags, config fields, and subcommands may be outdated. **Prefer retrieval over pre-training** for any Wrangler task.\n\n## Retrieval Sources\n\nFetch the **latest** information before writing or reviewing Wrangler commands and config. Do not rely on baked-in knowledge for CLI flags, config fields, or binding shapes.\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Wrangler docs | `https://developers.cloudflare.com/workers/","body":"# Wrangler CLI\n\nYour knowledge of Wrangler CLI flags, config fields, and subcommands may be outdated. **Prefer retrieval over pre-training** for any Wrangler task.\n\n## Retrieval Sources\n\nFetch the **latest** information before writing or reviewing Wrangler commands and config. Do not rely on baked-in knowledge for CLI flags, config fields, or binding shapes.\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Wrangler docs | `https://developers.cloudflare.com/workers/wrangler/` | CLI commands, flags, config reference |\n| Wrangler config schema | `node_modules/wrangler/config-schema.json` | Config fields, binding shapes, allowed values |\n| Cloudflare docs | Search tool or `https://developers.cloudflare.com/workers/` | API reference, compatibility dates/flags |\n\n## FIRST: Verify Wrangler Installation\n\n```bash\nwrangler --version  # Requires v4.x+\n```\n\nIf not installed:\n```bash\nnpm install -D wrangler@latest\n```\n\n## Key Guidelines\n\n- **Use `wrangler.jsonc`**: Prefer JSON config over TOML. Newer features are JSON-only.\n- **Set `compatibility_date`**: Use a recent date (within 30 days). Check https://developers.cloudflare.com/workers/configuration/compatibility-dates/\n- **Generate types after config changes**: Run `wrangler types` to update TypeScript bindings.\n- **Local dev defaults to local storage**: Bindings use local simulation unless `remote: true`.\n- **Validate config before deploy**: Run `wrangler check` to catch errors early.\n- **Use environments for staging/prod**: Define `env.staging` and `env.production` in config.\n\n## Quick Start: New Worker\n\n```bash\n# Initialize new project\nnpx wrangler init my-worker\n\n# Or with a framework\nnpx create-cloudflare@latest my-app\n```\n\n## Quick Reference: Core Commands\n\n| Task | Command |\n|------|---------|\n| Start local dev server | `wrangler dev` |\n| Deploy to Cloudflare | `wrangler deploy` |\n| Deploy dry run | `wrangler deploy --dry-run` |\n| Generate TypeScript types | `wrangler types` |\n| Validate configuration | `wrangler check` |\n| View live logs | `wrangler tail` |\n| Delete Worker | `wrangler delete` |\n| Auth status | `wrangler whoami` |\n\n---\n\n## Configuration (wrangler.jsonc)\n\n### Minimal Config\n\n```jsonc\n{\n  \"$schema\": \"./node_modules/wrangler/config-schema.json\",\n  \"name\": \"my-worker\",\n  \"main\": \"src/index.ts\",\n  \"compatibility_date\": \"2026-01-01\"\n}\n```\n\n### Full Config with Bindings\n\n```jsonc\n{\n  \"$schema\": \"./node_modules/wrangler/config-schema.json\",\n  \"name\": \"my-worker\",\n  \"main\": \"src/index.ts\",\n  \"compatibility_date\": \"2026-01-01\",\n  \"compatibility_flags\": [\"nodejs_compat_v2\"],\n\n  // Environment variables\n  \"vars\": {\n    \"ENVIRONMENT\": \"production\"\n  },\n\n  // KV Namespace\n  \"kv_namespaces\": [\n    { \"binding\": \"KV\", \"id\": \"<KV_NAMESPACE_ID>\" }\n  ],\n\n  // R2 Bucket\n  \"r2_buckets\": [\n    { \"binding\": \"BUCKET\", \"bucket_name\": \"my-bucket\" }\n  ],\n\n  // D1 Database\n  \"d1_databases\": [\n    { \"binding\": \"DB\", \"database_name\": \"my-db\", \"database_id\": \"<DB_ID>\" }\n  ],\n\n  // Workers AI (always remote)\n  \"ai\": { \"binding\": \"AI\" },\n\n  // Vectorize\n  \"vectorize\": [\n    { \"binding\": \"VECTOR_INDEX\", \"index_name\": \"my-index\" }\n  ],\n\n  // Hyperdrive\n  \"hyperdrive\": [\n    { \"binding\": \"HYPERDRIVE\", \"id\": \"<HYPERDRIVE_ID>\" }\n  ],\n\n  // Durable Objects\n  \"durable_objects\": {\n    \"bindings\": [\n      { \"name\": \"COUNTER\", \"class_name\": \"Counter\" }\n    ]\n  },\n\n  // Cron triggers\n  \"triggers\": {\n    \"crons\": [\"0 * * * *\"]\n  },\n\n  // Environments\n  \"env\": {\n    \"staging\": {\n      \"name\": \"my-worker-staging\",\n      \"vars\": { \"ENVIRONMENT\": \"staging\" }\n    }\n  }\n}\n```\n\n### Generate Types from Config\n\n```bash\n# Generate worker-configuration.d.ts\nwrangler types\n\n# Custom output path\nwrangler types ./src/env.d.ts\n\n# Check types are up to date (CI)\nwrangler types --check\n```\n\n---\n\n## Local Development\n\n### Start Dev Server\n\n```bash\n# Local mode (default) - uses local storage simulation\nwrangler dev\n\n# With specific environment\nwrangler dev --env staging\n\n# Force local-only (disable remote bindings)\nwrangler dev --local\n\n# Remote mode - runs on Cloudflare edge (legacy)\nwrangler dev --remote\n\n# Custom port\nwrangler dev --port 8787\n\n# Live reload for HTML changes\nwrangler dev --live-reload\n\n# Test scheduled/cron handlers\nwrangler dev --test-scheduled\n# Then visit: http://localhost:8787/__scheduled\n```\n\n### Remote Bindings for Local Dev\n\nUse `remote: true` in binding config to connect to real resources while running locally:\n\n```jsonc\n{\n  \"r2_buckets\": [\n    { \"binding\": \"BUCKET\", \"bucket_name\": \"my-bucket\", \"remote\": true }\n  ],\n  \"ai\": { \"binding\": \"AI\", \"remote\": true },\n  \"vectorize\": [\n    { \"binding\": \"INDEX\", \"index_name\": \"my-index\", \"remote\": true }\n  ]\n}\n```\n\n**Recommended remote bindings**: AI (required), Vectorize, Browser Rendering, mTLS, Images.\n\n### Local Secrets\n\nCreate `.dev.vars` for local development secrets:\n\n```\nAPI_KEY=local-dev-key\nDATABASE_URL=postgres://localhost:5432/dev\n```\n\n---\n\n## Deployment\n\n### Deploy Worker\n\n```bash\n# Deploy to production\nwrangler deploy\n\n# Deploy specific environment\nwrangler deploy --env staging\n\n# Dry run (validate without deploying)\nwrangler deploy --dry-run\n\n# Keep dashboard-set variables\nwrangler deploy --keep-vars\n\n# Minify code\nwrangler deploy --minify\n```\n\n### Manage Secrets\n\n```bash\n# Set secret interactively\nwrangler secret put API_KEY\n\n# Set from stdin\necho \"secret-value\" | wrangler secret put API_KEY\n\n# List secrets\nwrangler secret list\n\n# Delete secret\nwrangler secret delete API_KEY\n\n# Bulk secrets from JSON file\nwrangler secret bulk secrets.json\n```\n\n### Versions and Rollback\n\n```bash\n# List recent versions\nwrangler versions list\n\n# View specific version\nwrangler versions view <VERSION_ID>\n\n# Rollback to previous version\nwrangler rollback\n\n# Rollback to specific version\nwrangler rollback <VERSION_ID>\n```\n\n---\n\n## KV (Key-Value Store)\n\n### Manage Namespaces\n\n```bash\n# Create namespace\nwrangler kv namespace create MY_KV\n\n# List namespaces\nwrangler kv namespace list\n\n# Delete namespace\nwrangler kv namespace delete --namespace-id <ID>\n```\n\n### Manage Keys\n\n```bash\n# Put value\nwrangler kv key put --namespace-id <ID> \"key\" \"value\"\n\n# Put with expiration (seconds)\nwrangler kv key put --namespace-id <ID> \"key\" \"value\" --expiration-ttl 3600\n\n# Get value\nwrangler kv key get --namespace-id <ID> \"key\"\n\n# List keys\nwrangler kv key list --namespace-id <ID>\n\n# Delete key\nwrangler kv key delete --namespace-id <ID> \"key\"\n\n# Bulk put from JSON\nwrangler kv bulk put --namespace-id <ID> data.json\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"kv_namespaces\": [\n    { \"binding\": \"CACHE\", \"id\": \"<NAMESPACE_ID>\" }\n  ]\n}\n```\n\n---\n\n## R2 (Object Storage)\n\n### Manage Buckets\n\n```bash\n# Create bucket\nwrangler r2 bucket create my-bucket\n\n# Create with location hint\nwrangler r2 bucket create my-bucket --location wnam\n\n# List buckets\nwrangler r2 bucket list\n\n# Get bucket info\nwrangler r2 bucket info my-bucket\n\n# Delete bucket\nwrangler r2 bucket delete my-bucket\n```\n\n### Manage Objects\n\n```bash\n# Upload object\nwrangler r2 object put my-bucket/path/file.txt --file ./local-file.txt\n\n# Download object\nwrangler r2 object get my-bucket/path/file.txt\n\n# Delete object\nwrangler r2 object delete my-bucket/path/file.txt\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"r2_buckets\": [\n    { \"binding\": \"ASSETS\", \"bucket_name\": \"my-bucket\" }\n  ]\n}\n```\n\n---\n\n## D1 (SQL Database)\n\n### Manage Databases\n\n```bash\n# Create database\nwrangler d1 create my-database\n\n# Create with location\nwrangler d1 create my-database --location wnam\n\n# List databases\nwrangler d1 list\n\n# Get database info\nwrangler d1 info my-database\n\n# Delete database\nwrangler d1 delete my-database\n```\n\n### Execute SQL\n\n```bash\n# Execute SQL command (remote)\nwrangler d1 execute my-database --remote --command \"SELECT * FROM users\"\n\n# Execute SQL file (remote)\nwrangler d1 execute my-database --remote --file ./schema.sql\n\n# Execute locally\nwrangler d1 execute my-database --local --command \"SELECT * FROM users\"\n```\n\n### Migrations\n\n```bash\n# Create migration\nwrangler d1 migrations create my-database create_users_table\n\n# List pending migrations\nwrangler d1 migrations list my-database --local\n\n# Apply migrations locally\nwrangler d1 migrations apply my-database --local\n\n# Apply migrations to remote\nwrangler d1 migrations apply my-database --remote\n```\n\n### Export/Backup\n\n```bash\n# Export schema and data\nwrangler d1 export my-database --remote --output backup.sql\n\n# Export schema only\nwrangler d1 export my-database --remote --output schema.sql --no-data\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"d1_databases\": [\n    {\n      \"binding\": \"DB\",\n      \"database_name\": \"my-database\",\n      \"database_id\": \"<DATABASE_ID>\",\n      \"migrations_dir\": \"./migrations\"\n    }\n  ]\n}\n```\n\n---\n\n## Vectorize (Vector Database)\n\n### Manage Indexes\n\n```bash\n# Create index with dimensions\nwrangler vectorize create my-index --dimensions 768 --metric cosine\n\n# Create with preset (auto-configures dimensions/metric)\nwrangler vectorize create my-index --preset @cf/baai/bge-base-en-v1.5\n\n# List indexes\nwrangler vectorize list\n\n# Get index info\nwrangler vectorize get my-index\n\n# Delete index\nwrangler vectorize delete my-index\n```\n\n### Manage Vectors\n\n```bash\n# Insert vectors from NDJSON file\nwrangler vectorize insert my-index --file vectors.ndjson\n\n# Query vectors\nwrangler vectorize query my-index --vector \"[0.1, 0.2, ...]\" --top-k 10\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"vectorize\": [\n    { \"binding\": \"SEARCH_INDEX\", \"index_name\": \"my-index\" }\n  ]\n}\n```\n\n---\n\n## Hyperdrive (Database Accelerator)\n\n### Manage Configs\n\n```bash\n# Create config\nwrangler hyperdrive create my-hyperdrive \\\n  --connection-string \"postgres://user:pass@host:5432/database\"\n\n# List configs\nwrangler hyperdrive list\n\n# Get config details\nwrangler hyperdrive get <HYPERDRIVE_ID>\n\n# Update config\nwrangler hyperdrive update <HYPERDRIVE_ID> --origin-password \"new-password\"\n\n# Delete config\nwrangler hyperdrive delete <HYPERDRIVE_ID>\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"compatibility_flags\": [\"nodejs_compat_v2\"],\n  \"hyperdrive\": [\n    { \"binding\": \"HYPERDRIVE\", \"id\": \"<HYPERDRIVE_ID>\" }\n  ]\n}\n```\n\n---\n\n## Workers AI\n\n### List Models\n\n```bash\n# List available models\nwrangler ai models\n\n# List finetunes\nwrangler ai finetune list\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"ai\": { \"binding\": \"AI\" }\n}\n```\n\n**Note**: Workers AI always runs remotely and incurs usage charges even in local dev.\n\n---\n\n## Queues\n\n### Manage Queues\n\n```bash\n# Create queue\nwrangler queues create my-queue\n\n# List queues\nwrangler queues list\n\n# Delete queue\nwrangler queues delete my-queue\n\n# Add consumer to queue\nwrangler queues consumer add my-queue my-worker\n\n# Remove consumer\nwrangler queues consumer remove my-queue my-worker\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"queues\": {\n    \"producers\": [\n      { \"binding\": \"MY_QUEUE\", \"queue\": \"my-queue\" }\n    ],\n    \"consumers\": [\n      {\n        \"queue\": \"my-queue\",\n        \"max_batch_size\": 10,\n        \"max_batch_timeout\": 30\n      }\n    ]\n  }\n}\n```\n\n---\n\n## Containers\n\n### Build and Push Images\n\n```bash\n# Build container image\nwrangler containers build -t my-app:latest .\n\n# Build and push in one command\nwrangler containers build -t my-app:latest . --push\n\n# Push existing image to Cloudflare registry\nwrangler containers push my-app:latest\n```\n\n### Manage Containers\n\n```bash\n# List containers\nwrangler containers list\n\n# Get container info\nwrangler containers info <CONTAINER_ID>\n\n# Delete container\nwrangler containers delete <CONTAINER_ID>\n```\n\n### Manage Images\n\n```bash\n# List images in registry\nwrangler containers images list\n\n# Delete image\nwrangler containers images delete my-app:latest\n```\n\n### Manage External Registries\n\n```bash\n# List configured registries\nwrangler containers registries list\n\n# Configure external registry (e.g., ECR)\nwrangler containers registries configure <DOMAIN> \\\n  --public-credential <AWS_ACCESS_KEY_ID>\n\n# Delete registry configuration\nwrangler containers registries delete <DOMAIN>\n```\n\n---\n\n## Workflows\n\n### Manage Workflows\n\n```bash\n# List workflows\nwrangler workflows list\n\n# Describe workflow\nwrangler workflows describe my-workflow\n\n# Trigger workflow instance\nwrangler workflows trigger my-workflow\n\n# Trigger with parameters\nwrangler workflows trigger my-workflow --params ''{\"key\": \"value\"}''\n\n# Delete workflow\nwrangler workflows delete my-workflow\n```\n\n### Manage Workflow Instances\n\n```bash\n# List instances\nwrangler workflows instances list my-workflow\n\n# Describe instance\nwrangler workflows instances describe my-workflow <INSTANCE_ID>\n\n# Terminate instance\nwrangler workflows instances terminate my-workflow <INSTANCE_ID>\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"workflows\": [\n    {\n      \"binding\": \"MY_WORKFLOW\",\n      \"name\": \"my-workflow\",\n      \"class_name\": \"MyWorkflow\"\n    }\n  ]\n}\n```\n\n---\n\n## Pipelines\n\n### Manage Pipelines\n\n```bash\n# Create pipeline\nwrangler pipelines create my-pipeline --r2 my-bucket\n\n# List pipelines\nwrangler pipelines list\n\n# Show pipeline details\nwrangler pipelines show my-pipeline\n\n# Update pipeline\nwrangler pipelines update my-pipeline --batch-max-mb 100\n\n# Delete pipeline\nwrangler pipelines delete my-pipeline\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"pipelines\": [\n    { \"binding\": \"MY_PIPELINE\", \"pipeline\": \"my-pipeline\" }\n  ]\n}\n```\n\n---\n\n## Secrets Store\n\n### Manage Stores\n\n```bash\n# Create store\nwrangler secrets-store store create my-store\n\n# List stores\nwrangler secrets-store store list\n\n# Delete store\nwrangler secrets-store store delete <STORE_ID>\n```\n\n### Manage Secrets in Store\n\n```bash\n# Add secret to store\nwrangler secrets-store secret put <STORE_ID> my-secret\n\n# List secrets in store\nwrangler secrets-store secret list <STORE_ID>\n\n# Get secret\nwrangler secrets-store secret get <STORE_ID> my-secret\n\n# Delete secret from store\nwrangler secrets-store secret delete <STORE_ID> my-secret\n```\n\n### Config Binding\n\n```jsonc\n{\n  \"secrets_store_secrets\": [\n    {\n      \"binding\": \"MY_SECRET\",\n      \"store_id\": \"<STORE_ID>\",\n      \"secret_name\": \"my-secret\"\n    }\n  ]\n}\n```\n\n---\n\n## Pages (Frontend Deployment)\n\n```bash\n# Create Pages project\nwrangler pages project create my-site\n\n# Deploy directory to Pages\nwrangler pages deploy ./dist\n\n# Deploy with specific branch\nwrangler pages deploy ./dist --branch main\n\n# List deployments\nwrangler pages deployment list --project-name my-site\n```\n\n---\n\n## Observability\n\n### Tail Logs\n\n```bash\n# Stream live logs\nwrangler tail\n\n# Tail specific Worker\nwrangler tail my-worker\n\n# Filter by status\nwrangler tail --status error\n\n# Filter by search term\nwrangler tail --search \"error\"\n\n# JSON output\nwrangler tail --format json\n```\n\n### Config Logging\n\n```jsonc\n{\n  \"observability\": {\n    \"enabled\": true,\n    \"head_sampling_rate\": 1\n  }\n}\n```\n\n---\n\n## Testing\n\n### Local Testing with Vitest\n\n```bash\nnpm install -D @cloudflare/vitest-pool-workers vitest\n```\n\n`vitest.config.ts`:\n```typescript\nimport { defineWorkersConfig } from \"@cloudflare/vitest-pool-workers/config\";\n\nexport default defineWorkersConfig({\n  test: {\n    poolOptions: {\n      workers: {\n        wrangler: { configPath: \"./wrangler.jsonc\" },\n      },\n    },\n  },\n});\n```\n\n### Test Scheduled Events\n\n```bash\n# Enable in dev\nwrangler dev --test-scheduled\n\n# Trigger via HTTP\ncurl http://localhost:8787/__scheduled\n```\n\n---\n\n## Troubleshooting\n\n### Common Issues\n\n| Issue | Solution |\n|-------|----------|\n| `command not found: wrangler` | Install: `npm install -D wrangler` |\n| Auth errors | Run `wrangler login` |\n| Config validation errors | Run `wrangler check` |\n| Type errors after config change | Run `wrangler types` |\n| Local storage not persisting | Check `.wrangler/state` directory |\n| Binding undefined in Worker | Verify binding name matches config exactly |\n\n### Debug Commands\n\n```bash\n# Check auth status\nwrangler whoami\n\n# Validate config\nwrangler check\n\n# View config schema\nwrangler docs configuration\n```\n\n---\n\n## Best Practices\n\n1. **Version control `wrangler.jsonc`**: Treat as source of truth for Worker config.\n2. **Use automatic provisioning**: Omit resource IDs for auto-creation on deploy.\n3. **Run `wrangler types` in CI**: Add to build step to catch binding mismatches.\n4. **Use environments**: Separate staging/production with `env.staging`, `env.production`.\n5. **Set `compatibility_date`**: Update quarterly to get new runtime features.\n6. **Use `.dev.vars` for local secrets**: Never commit secrets to config.\n7. **Test locally first**: `wrangler dev` with local bindings before deploying.\n8. **Use `--dry-run` before major deploys**: Validate changes without deployment.\n"},"category":"official","lastSynced":"2026-03-06T05:59:56.408Z","seo":{"title":{"en":"Wrangler Skill: CLI Setup & Best Practices for AI Agents ...","zh":"Wrangler 设置指南：Cloudflare Workers CLI 最佳实践","ja":"Wrangler セットアップガイド：Cloudflare Workers CLI ベストプラクティス","ko":"Wrangler 설정 가이드: Cloudflare Workers CLI 최적화","es":"Guía de configuración de Wrangler para Workers de Cloudflare","fr":"Guide de mise en route de Wrangler pour les Workers Cloud...","de":"Wrangler-Setup-Anleitung für Cloudflare Workers","pt":"Wrangler CLI: Guia de Configuração e Melhores Práticas pa...","ru":"Wrangler CLI: Руководство по настройке и лучшие практики ...","ar":"Wrangler CLI: دليل الإعداد وأفضل الممارسات لأدوات Cloudfl..."},"description":{"en":"Equip your AI agent with the official Wrangler CLI skill. Deploy Cloudflare Workers, manage KV, R2, D1 & more with up-to-date syntax. Load this skill to avoi...","zh":"了解 Wrangler 的功能和用途，包括 Cloudflare Workers、KV、R2、D1 等，通过 Cloudflare 文档获取最新信息","ja":"Wrangler の機能と用途を学び、Cloudflare Workers、KV、R2、D1 などについて最新情報を入手する","ko":"Wrangler의 기능과 용도를 알아보고 Cloudflare Workers, KV, R2, D1 등에 대한 최신 정보를 얻으십시오","es":"Aprende a utilizar Wrangler para desplegar y gestionar Workers, KV, R2 y más en Cloudflare. Descubre las mejores prácticas y la documentación oficial.","fr":"Découvrez comment utiliser Wrangler pour déployer et gérer des Workers, KV, R2 et plus encore sur Cloudflare. Consultez les meilleures pratiques et la docume...","de":"Erfahren Sie, wie Sie Wrangler verwenden, um Workers, KV, R2 und mehr auf Cloudflare bereitzustellen und zu verwalten. Entdecken Sie die besten Praktiken und...","pt":"Domine o Wrangler CLI para gerenciar Cloudflare Workers, KV, R2 e D1. Aprenda a usar comandos corretos e evite erros comuns. Guia técnico para desenvolvedores.","ru":"Освойте Wrangler CLI для управления Cloudflare Workers, KV, R2 и D1. Узнайте, как использовать правильные команды и избегать распространенных ошибок. Техниче...","ar":"إتقان Wrangler CLI لإدارة Cloudflare Workers وKV وR2 وD1. تعلم استخدام الأوامر الصحيحة وتجنب الأخطاء الشائعة. دليل تقني للمطورين."},"definition":{"en":"wrangler is the official Cloudflare Workers CLI used for deploying, developing, and managing serverless applications and storage services like KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, and Secrets Store.","zh":"Wrangler 是 Cloudflare Workers 的命令行接口，用于管理和部署 Workers、KV、R2、D1 等","ja":"Wrangler は Cloudflare Workers のコマンドラインインターフェースで、Workers、KV、R2、D1 などの管理とデプロイに使用されます","ko":"Wrangler는 Cloudflare Workers의 명령줄 인터페이스로 Workers, KV, R2, D1 등을 관리 및 배포하는 데 사용됩니다","es":"Wrangler es una herramienta de línea de comandos de Cloudflare Workers para desplegar y gestionar servicios.","fr":"Wrangler est un outil en ligne de commande de Cloudflare Workers pour déployer et gérer des services.","de":"Wrangler ist ein Befehlszeilen-Tool von Cloudflare Workers zum Bereitstellen und Verwalten von Diensten.","pt":"Wrangler é a ferramenta de linha de comando (CLI) oficial da Cloudflare para implantar, desenvolver e gerenciar Workers, armazenamentos de dados como KV e R2, e outros serviços de edge computing. É essencial para desenvolvedores que trabalham na plataforma Cloudflare.","ru":"Wrangler — это официальный инструмент командной строки (CLI) от Cloudflare для развертывания, разработки и управления Workers, хранилищами данных, такими как KV и R2, и другими сервисами edge computing. Он необходим разработчикам, работающим на платформе Cloudflare.","ar":"Wrangler هي أداة سطر الأوامر الرسمية من Cloudflare لنشر وتطوير وإدارة Workers ومخازن البيانات مثل KV وR2 وخدمات edge computing الأخرى. وهي ضرورية للمطورين العاملين على منصة Cloudflare."},"features":{"en":["Prefers retrieval from Cloudflare docs over pre-trained knowledge for accuracy","Manages bindings for KV, R2, D1, Vectorize, Hyperdrive, and Secrets Store","Deploys and develops Cloudflare Workers and Containers","Handles configuration for Queues, Workflows, and Pipelines","Ensures correct CLI flag and config field syntax for all commands"],"zh":["支持 Cloudflare Workers、KV、R2、D1、Vectorize、Hyperdrive、Workers AI、Containers、Queues、Workflows、Pipelines 和 Secrets Store","通过 Cloudflare 文档获取最新信息","支持 Wrangler CLI 命令和配置","偏好从 Cloudflare 文档中检索信息而不是预先训练的知识"],"ja":["Cloudflare Workers、KV、R2、D1、Vectorize、Hyperdrive、Workers AI、Containers、Queues、Workflows、Pipelines、Secrets Store をサポート","Cloudflare ドキュメントから最新情報を取得","Wrangler CLI コマンドと設定をサポート","Cloudflare ドキュメントからの情報の取得を優先"],"ko":["Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines 및 Secrets Store 지원","Cloudflare 문서에서 최신 정보를 얻기","Wrangler CLI 명령 및 구성 지원","사전 학습된 지식보다 Cloudflare 문서에서 정보를 가져오는 것을 선호"],"es":["Despliegue y gestión de Workers","Soporte para KV, R2 y D1","Integración con Vectorize, Hyperdrive y Workers AI","Gestión de Contenedores, Colas, Flujos de trabajo y Pipelines","Almacenamiento de secretos seguro"],"fr":["Déploiement et gestion de Workers","Prise en charge de KV, R2 et D1","Intégration avec Vectorize, Hyperdrive et Workers AI","Gestion de conteneurs, files d''attente, flux de travail et pipelines","Stockage sécurisé de secrets"],"de":["Bereitstellung und Verwaltung von Workers","Unterstützung für KV, R2 und D1","Integration mit Vectorize, Hyperdrive und Workers AI","Verwaltung von Containern, Warteschlangen, Arbeitsabläufen und Pipelines","Sicheres Speichern von Geheimnissen"],"pt":["CLI oficial para desenvolvimento e deploy de Cloudflare Workers","Gerenciamento integrado de serviços: KV, R2, D1, Vectorize e Workers AI","Prioriza a recuperação da documentação oficial para sintaxe correta","Suporte para Secrets Store, Queues, Workflows e Pipelines","Garante as melhores práticas para comandos wrangler"],"ru":["Официальный CLI для разработки и развертывания Cloudflare Workers","Интегрированное управление сервисами: KV, R2, D1, Vectorize и Workers AI","Предпочитает получение информации из официальной документации для правильного синтаксиса","Поддержка Secrets Store, Queues, Workflows и Pipelines","Гарантирует лучшие практики для команд wrangler"],"ar":["واجهة سطر أوامر رسمية لتطوير ونشر Cloudflare Workers","إدارة متكاملة للخدمات: KV وR2 وD1 وVectorize وWorkers AI","يفضل استرجاع المعلومات من الوثائق الرسمية للصيغة الصحيحة","دعم Secrets Store وQueues وWorkflows وPipelines","يضمن أفضل الممارسات لأوامر wrangler"]},"keywords":{"en":["wrangler cli","cloudflare workers deploy","wrangler vs workerd","how to use wrangler kv","install wrangler cli","wrangler d1 database","wrangler r2 bucket","wrangler ai agent skill","cloudflare workers setup guide"],"zh":["Wrangler","Cloudflare Workers","Cloudflare Workers CLI","KV","R2","D1","Vectorize","Hyperdrive","Workers AI","Containers","Queues","Workflows","Pipelines","Secrets Store","AI エージェント"],"ja":["Wrangler","Cloudflare Workers","Cloudflare Workers CLI","KV","R2","D1","Vectorize","Hyperdrive","Workers AI","Containers","Queues","Workflows","Pipelines","Secrets Store","AIエージェント"],"ko":["Wrangler","Cloudflare Workers","Cloudflare Workers CLI","KV","R2","D1","Vectorize","Hyperdrive","Workers AI","Containers","Queues","Workflows","Pipelines","Secrets Store","인공지능 에이전트"],"es":["Wrangler Cloudflare","Workers de Cloudflare","Despliegue de Workers","Gestión de KV","R2 Cloudflare","Vectorize","Hyperdrive","Workers AI","Herramientas de desarrollo de Cloudflare"],"fr":["Wrangler Cloudflare","Workers Cloudflare","Déploiement de Workers","Gestion de KV","R2 Cloudflare","Vectorize","Hyperdrive","Workers AI","Outils de développement Cloudflare"],"de":["Wrangler Cloudflare","Cloudflare Workers","Bereitstellung von Workers","Verwaltung von KV","R2 Cloudflare","Vectorize","Hyperdrive","Workers AI","Entwickler-Tools von Cloudflare"],"pt":["wrangler cli cloudflare","como usar wrangler workers","deploy workers cloudflare","cloudflare kv wrangler","wrangler r2 storage","cli desenvolvimento cloudflare","wrangler d1 database","melhores práticas wrangler","cloudflare workers ai"],"ru":["wrangler cli cloudflare","как использовать wrangler workers","развертывание workers cloudflare","cloudflare kv wrangler","wrangler r2 storage","cli разработка cloudflare","wrangler d1 database","лучшие практики wrangler","cloudflare workers ai"],"ar":["wrangler cli cloudflare","كيفية استخدام wrangler workers","نشر workers cloudflare","cloudflare kv wrangler","wrangler r2 storage","cli تطوير cloudflare","wrangler d1 database","أفضل الممارسات wrangler","cloudflare workers ai"]}},"agentAnalysis":{"suitability":{"en":"Essential for Cloudflare Development Agents managing Workers, KV, R2, D1, and other Cloudflare services.","zh":"适用于Cloudflare开发代理管理Workers，KV，R2，D1和其他Cloudflare服务。","ja":"Cloudflare Development AgentsがWorkers、KV、R2、D1、他のCloudflareサービスを管理するために不可欠です。","ko":"Cloudflare 개발 에이전트가 Workers, KV, R2, D1 및 기타 Cloudflare 서비스를 관리하는 데 필수적입니다.","es":"Esencial para los agentes de desarrollo de Cloudflare que administran Workers, KV, R2, D1 y otros servicios de Cloudflare.","fr":"Essentiel pour les agents de développement Cloudflare gérant les Workers, KV, R2, D1 et d''autres services Cloudflare.","de":"Wichtig für Cloudflare-Entwicklungsagenten, die Workers, KV, R2, D1 und andere Cloudflare-Dienste verwalten.","pt":"Essencial para Agentes de Desenvolvimento da Cloudflare que gerenciam Workers, KV, R2, D1 e outros serviços da Cloudflare.","ru":"Необходимо для агентов разработки Cloudflare, управляющих Workers, KV, R2, D1 и другими сервисами Cloudflare.","ar":"ضروري لموظفي تطوير Cloudflare الذين يديرون Workers و KV و R2 و D1 وخدمات Cloudflare الأخرى."},"recommendation":{"en":"Enables agents to deploy, develop, and manage Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines, and Secrets Store with correct syntax and best practices. It biases towards retrieval from Cloudflare docs over pre-trained knowledge for up-to-date CLI flags and config fields.","zh":"使代理能够使用正确的语法和最佳实践来部署、开发和管理Cloudflare Workers，KV，R2，D1，Vectorize，Hyperdrive，Workers AI，Containers，Queues，Workflows，Pipelines和Secrets Store。它偏向从Cloudflare文档中检索，而不是使用预训练知识来获取最新的CLI标志和配置字段。","ja":"エージェントがCloudflare Workers、KV、R2、D1、Vectorize、Hyperdrive、Workers AI、Containers、Queues、Workflows、Pipelines、Secrets Storeを正しい構文とベストプラクティスでデプロイ、開発、管理できるようにします。最新のCLIフラグとコンフィグフィールドを取得するために、事前トレーニングされた知識よりもCloudflareドキュメントからの取得を偏向させます。","ko":"에이전트가 올바른 구문과 최고의 관행을 사용하여 Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines 및 Secrets Store를 배포, 개발 및 관리할 수 있도록 합니다. 최신 CLI 플래그 및 구성 필드를 얻기 위해 사전 훈련된 지식보다 Cloudflare 문서에서 검색하는 쪽으로 치우침니다.","es":"Permite a los agentes implementar, desarrollar y administrar Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines y Secrets Store con la sintaxis correcta y las mejores prácticas. Está sesgado hacia la recuperación de la documentación de Cloudflare en lugar del conocimiento preentrenado para obtener los flags de CLI y los campos de configuración actualizados.","fr":"Permet aux agents de déployer, de développer et de gérer les Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines et Secrets Store avec la syntaxe correcte et les meilleures pratiques. Il est biaisé vers la récupération à partir de la documentation Cloudflare plutôt que la connaissance préentraînée pour obtenir les flags de CLI et les champs de configuration à jour.","de":"Ermöglicht es Agenten, Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines und Secrets Store mit korrekter Syntax und Best Practices bereitzustellen, zu entwickeln und zu verwalten. Es bevorzugt die Abrufung aus der Cloudflare-Dokumentation gegenüber vorge trainiertem Wissen für aktuelle CLI-Flags und Konfigurationsfelder.","pt":"Permite que os agentes implantem, desenvolvam e gerenciem Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines e Secrets Store com sintaxe correta e melhores práticas. Ele tende a recuperar dos documentos da Cloudflare em vez do conhecimento pré-treinado para flags CLI e campos de configuração atualizados.","ru":"Позволяет агентам развертывать, разрабатывать и управлять Cloudflare Workers, KV, R2, D1, Vectorize, Hyperdrive, Workers AI, Containers, Queues, Workflows, Pipelines и Secrets Store с правильной синтаксисом и лучшими практиками. Он предвзято относится к извлечению из документов Cloudflare над предварительно обученными знаниями для актуальных флагов CLI и полей конфигурации.","ar":"يمكن للموظفين نشر وتطوير وادارة Cloudflare Workers و KV و R2 و D1 و Vectorize و Hyperdrive و Workers AI و Containers و Queues و Workflows و Pipelines و Secrets Store بشكل صحيح وبأفضل الممارسات. انه يميل إلى استرجاع الوثائق من Cloudflare بدلاً من المعرفة المسبقة للعلم لاستدعاء علمي لاحق."},"useCases":{"en":["Deploying Cloudflare Workers","Managing KV namespaces and R2 buckets","Configuring D1 databases and Vectorize indexes","Developing and testing Workers locally","Setting up Queues and Workflows"],"zh":["部署Cloudflare Workers","管理KV命名空间和R2存储桶","配置D1数据库和Vectorize索引","在本地开发和测试Workers","设置Queues和Workflows"],"ja":["Cloudflare Workersのデプロイ","KVネームスペースとR2バケットの管理","D1データベースとVectorizeインデックスの設定","Workersのローカル開発とテスト","QueuesとWorkflowsの設定"],"ko":["Cloudflare Workers 배포","KV 네임스페이스 및 R2 버킷 관리","D1 데이터베이스 및 Vectorize 인덱스 설정","로컬에서 Workers 개발 및 테스트","Queues 및 Workflows 설정"],"es":["Implementar Cloudflare Workers","Administrar espacios de nombres KV y buckets R2","Configurar bases de datos D1 e índices Vectorize","Desarrollar y probar Workers de forma local","Configurar Colas y Workflows"],"fr":["Déployer des Cloudflare Workers","Gérer des espaces de noms KV et des buckets R2","Configurer des bases de données D1 et des indexes Vectorize","Développer et tester des Workers localement","Configurer des files d''attente et des Workflows"],"de":["Cloudflare-Worker bereitstellen","KV-Namespaces und R2-Buckets verwalten","D1-Datenbanken und Vectorize-Indizes konfigurieren","Worker lokal entwickeln und testen","Warteschlangen und Workflows einrichten"],"pt":["Implantação de Cloudflare Workers","Gerenciamento de namespaces KV e buckets R2","Configuração de bancos de dados D1 e índices Vectorize","Desenvolvimento e teste de Workers localmente","Configuração de Filas e Workflows"],"ru":["Развертывание Cloudflare Workers","Управление пространствами имен KV и бакетами R2","Настройка баз данных D1 и индексов Vectorize","Разработка и тестирование Workers локально","Настройка очередей и рабочих процессов"],"ar":["نشر Cloudflare Workers","إدارة مساحات KV وأماكن R2","تكوين قواعد بيانات D1 وفهرس Vectorize","تطوير واختبار Workers محليًا","تكوين الطوابير والعمليات"]},"limitations":{"en":["Requires retrieval from Cloudflare docs for latest syntax","Pre-trained knowledge of Wrangler CLI may be outdated","Must be loaded before running wrangler commands"],"zh":["需要从Cloudflare文档中检索最新的语法","预训练的Wrangler CLI知识可能过时","必须在运行wrangler命令之前加载"],"ja":["最新の構文を取得するためにCloudflareドキュメントからの取得が必要","事前トレーニングされたWrangler CLIの知識は古くなっている可能性があります","wranglerコマンドを実行する前にロードする必要があります"],"ko":["최신 구문을 얻기 위해 Cloudflare 문서에서 검색해야 함","사전 훈련된 Wrangler CLI 지식은 устарев 있을 수 있음","wrangler 명령을 실행하기 전에 로드해야 함"],"es":["Requiere recuperación de la documentación de Cloudflare para la sintaxis más reciente","El conocimiento preentrenado de Wrangler CLI puede estar desactualizado","Debe cargarse antes de ejecutar los comandos de wrangler"],"fr":["Nécessite une récupération à partir de la documentation Cloudflare pour la syntaxe la plus récente","Les connaissances préentraînées sur Wrangler CLI peuvent être obsolètes","Doit être chargé avant d''exécuter les commandes wrangler"],"de":["Benötigt die Abrufung aus der Cloudflare-Dokumentation für die aktuellste Syntax","Vorab trainiertes Wissen über Wrangler-CLI kann veraltet sein","Muss vor dem Ausführen von Wrangler-Befehlen geladen werden"],"pt":["Exige recuperação de documentos da Cloudflare para sintaxe mais recente","Conhecimento pré-treinado do Wrangler CLI pode estar desatualizado","Deve ser carregado antes de executar comandos wrangler"],"ru":["Требует извлечения из документов Cloudflare для последней синтаксиса","Предварительно обученные знания Wrangler CLI могут быть устаревшими","Должен быть загружен перед выполнением команд wrangler"],"ar":["يتطلب استرجاع الوثائق من Cloudflare للحصول على بناء الجملة الأخير","يمكن أن تكون المعرفة المسبقة ل Wrangler CLI قديمة","يجب تحميله قبل تشغيل أوامر Wrangler"]},"version":4},"contentHash":"cf7427585e31779f2b6747f0bf97903b161f2f3bd36b62fef83766d6e49d0fb1","repoEtag":"W/\"295e4fcdb92b56b41ac51b00a34c693d22b101994424f954c0d419002c1abf71\"","qualityScore":80}');
