INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('neondatabase/mcp-server-neon/README.md', 'README.md', 'neondatabase', 'mcp-server-neon', 'official', 'README.md neondatabase mcp-server-neon official The README.md skill generates a customizable README file with dynamic logos and installation links for AI agents. It benefits developers by providing a streamlined setup process. README.md 文件提供了 Neon MCP Server 的安装和配置指南，包括图像和链接 README.md ファイルには、Neon MCP Server のインストールと設定方法が記載されています。画像やリンクも含まれています README.md 파일에는 Neon MCP Server 설치 및 구성 방법이 기술되어 있습니다. 이미지와 링크도 포함되어 있습니다 README.md es un archivo de configuración para el servidor MCP que utiliza imágenes con esquema de color oscuro y claro README.md est un fichier de configuration pour le serveur MCP qui utilise des images avec un schéma de couleur sombre et clair README.md ist eine Konfigurationsdatei für den MCP-Server, die Bilder mit dunklem und hellem Farbschema verwendet O README.md é um arquivo de documentação essencial para projetos de desenvolvimento de software, fornecendo informações sobre como configurar e executar o projeto Файл README.md является важнейшим документом для проектов разработки программного обеспечения, предоставляющим информацию о том, как настроить и запустить проект для ИИ Агентов ملف README.md هو وثيقة أساسية لمشاريع تطوير البرمجيات، يوفر معلومات حول كيفية تشغيل وتشغيل المشروع لأدوات الذكاء الاصطناعي how to use README.md README.md setup guide README.md alternative README.md vs GitHub README install README.md configure README.md for AI agents what is README.md README.md for developers README.md best practices README.md Neon MCP Server 安装指南 配置文件 Cursor AIエージェント 技术详细信息 多语言支持 Generates dynamic logos using HTML picture tags and SVG files Supports dark and light color schemes using prefers-color-scheme media queries Creates installation links for Cursor using deeplink URLs Uses JSON config files for customization Displays fallback logos for unsupported browsers Provides a markdown-based README file for AI agents README.md is a skill that generates a markdown file with a dynamic logo and installation link for AI agents, using HTML and SVG technologies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('langgenius/dify/frontend-testing', 'official', 'langgenius', 'dify', 'langgenius/dify', 'frontend-testing', 131375, 20455, 80, '2026-03-06T06:00:48Z', '2026-03-06T06:07:00.629Z', 'be27373a5d11b4eca1ecc21148e97fbf9c893a4f3807787e5ce448e85cb5de13', '{"id":"langgenius/dify/frontend-testing","name":"frontend-testing","description":{"en":"The frontend-testing skill generates high-quality tests for Dify frontend components, hooks, and utilities using Vitest and React Testing Library, benefiting developers and QA engineers.","zh":"该技能支持使用 Vitest 和 React Testing Library 为 Dify 前端组件、hooks 和实用程序生成高质量测试。","ja":"このスキルは、Vitest と React Testing Library を使用して Dify フロントエンドコンポーネント、hooks、ユーティリティのための高品質テストを生成することを支援します。","ko":"이 스킬은 Vitest 및 React Testing Library를 사용하여 Dify 프론트엔드 컴포넌트, hooks 및 유틸리티에 대한 고품질 테스트를 생성하는 것을 지원합니다.","es":"Genera pruebas de alta calidad para componentes, hooks y utilidades frontend con Vitest y React Testing Library","fr":"Générez des tests de haute qualité pour les composants, les hooks et les utilités frontend avec Vitest et React Testing Library","de":"Erzeugen Sie hochwertige Tests für Frontend-Komponenten, -Hooks und -Utilities mit Vitest und React Testing Library","pt":"O skill de teste frontend gera testes de alta qualidade para componentes, hooks e utilitários Dify usando Vitest e React Testing Library","ru":"Навык фронтенд-тестирования генерирует высококачественные тесты для компонентов, хуков и утилит Dify с помощью Vitest и React Testing Library","ar":"مهارة الاختبار الأمامي تنتج اختبارات عالية الجودة لمكونات و Hooks و أدوات Dify باستخدام Vitest و React Testing Library"},"owner":"langgenius","repo":"dify","repoPath":"langgenius/dify","stars":131375,"forks":20455,"updatedAt":"2026-03-06T06:00:48Z","topics":["agent","agentic-ai","agentic-framework","agentic-workflow","ai","automation","gemini","genai","gpt","gpt-4","llm","low-code","mcp","nextjs","no-code","openai","orchestration","python","rag","workflow"],"skillMd":{"name":"frontend-testing","description":"Generate Vitest + React Testing Library tests for Dify frontend components, hooks, and utilities. Triggers on testing, spec files, coverage, Vitest, RTL, unit tests, integration tests, or write/review test requests.","bodyPreview":"# Dify Frontend Testing Skill\n\nThis skill enables Claude to generate high-quality, comprehensive frontend tests for the Dify project following established conventions and best practices.\n\n> **⚠️ Authoritative Source**: This skill is derived from `web/docs/test.md`. Use Vitest mock/timer APIs (`vi.*`).\n\n## When to Apply This Skill\n\nApply this skill when the user:\n\n- Asks to **write tests** for a component, hook, or utility\n- Asks to **review existing tests** for completeness\n- Mentions **Vitest**","body":"# Dify Frontend Testing Skill\n\nThis skill enables Claude to generate high-quality, comprehensive frontend tests for the Dify project following established conventions and best practices.\n\n> **⚠️ Authoritative Source**: This skill is derived from `web/docs/test.md`. Use Vitest mock/timer APIs (`vi.*`).\n\n## When to Apply This Skill\n\nApply this skill when the user:\n\n- Asks to **write tests** for a component, hook, or utility\n- Asks to **review existing tests** for completeness\n- Mentions **Vitest**, **React Testing Library**, **RTL**, or **spec files**\n- Requests **test coverage** improvement\n- Uses `pnpm analyze-component` output as context\n- Mentions **testing**, **unit tests**, or **integration tests** for frontend code\n- Wants to understand **testing patterns** in the Dify codebase\n\n**Do NOT apply** when:\n\n- User is asking about backend/API tests (Python/pytest)\n- User is asking about E2E tests (Playwright/Cypress)\n- User is only asking conceptual questions without code context\n\n## Quick Reference\n\n### Tech Stack\n\n| Tool | Version | Purpose |\n|------|---------|---------|\n| Vitest | 4.0.16 | Test runner |\n| React Testing Library | 16.0 | Component testing |\n| jsdom | - | Test environment |\n| nock | 14.0 | HTTP mocking |\n| TypeScript | 5.x | Type safety |\n\n### Key Commands\n\n```bash\n# Run all tests\npnpm test\n\n# Watch mode\npnpm test:watch\n\n# Run specific file\npnpm test path/to/file.spec.tsx\n\n# Generate coverage report\npnpm test:coverage\n\n# Analyze component complexity\npnpm analyze-component <path>\n\n# Review existing test\npnpm analyze-component <path> --review\n```\n\n### File Naming\n\n- Test files: `ComponentName.spec.tsx` (same directory as component)\n- Integration tests: `web/__tests__/` directory\n\n## Test Structure Template\n\n```typescript\nimport { render, screen, fireEvent, waitFor } from ''@testing-library/react''\nimport Component from ''./index''\n\n// ✅ Import real project components (DO NOT mock these)\n// import Loading from ''@/app/components/base/loading''\n// import { ChildComponent } from ''./child-component''\n\n// ✅ Mock external dependencies only\nvi.mock(''@/service/api'')\nvi.mock(''next/navigation'', () => ({\n  useRouter: () => ({ push: vi.fn() }),\n  usePathname: () => ''/test'',\n}))\n\n// ✅ Zustand stores: Use real stores (auto-mocked globally)\n// Set test state with: useAppStore.setState({ ... })\n\n// Shared state for mocks (if needed)\nlet mockSharedState = false\n\ndescribe(''ComponentName'', () => {\n  beforeEach(() => {\n    vi.clearAllMocks()  // ✅ Reset mocks BEFORE each test\n    mockSharedState = false  // ✅ Reset shared state\n  })\n\n  // Rendering tests (REQUIRED)\n  describe(''Rendering'', () => {\n    it(''should render without crashing'', () => {\n      // Arrange\n      const props = { title: ''Test'' }\n      \n      // Act\n      render(<Component {...props} />)\n      \n      // Assert\n      expect(screen.getByText(''Test'')).toBeInTheDocument()\n    })\n  })\n\n  // Props tests (REQUIRED)\n  describe(''Props'', () => {\n    it(''should apply custom className'', () => {\n      render(<Component className=\"custom\" />)\n      expect(screen.getByRole(''button'')).toHaveClass(''custom'')\n    })\n  })\n\n  // User Interactions\n  describe(''User Interactions'', () => {\n    it(''should handle click events'', () => {\n      const handleClick = vi.fn()\n      render(<Component onClick={handleClick} />)\n      \n      fireEvent.click(screen.getByRole(''button''))\n      \n      expect(handleClick).toHaveBeenCalledTimes(1)\n    })\n  })\n\n  // Edge Cases (REQUIRED)\n  describe(''Edge Cases'', () => {\n    it(''should handle null data'', () => {\n      render(<Component data={null} />)\n      expect(screen.getByText(/no data/i)).toBeInTheDocument()\n    })\n\n    it(''should handle empty array'', () => {\n      render(<Component items={[]} />)\n      expect(screen.getByText(/empty/i)).toBeInTheDocument()\n    })\n  })\n})\n```\n\n## Testing Workflow (CRITICAL)\n\n### ⚠️ Incremental Approach Required\n\n**NEVER generate all test files at once.** For complex components or multi-file directories:\n\n1. **Analyze & Plan**: List all files, order by complexity (simple → complex)\n1. **Process ONE at a time**: Write test → Run test → Fix if needed → Next\n1. **Verify before proceeding**: Do NOT continue to next file until current passes\n\n```\nFor each file:\n  ┌────────────────────────────────────────┐\n  │ 1. Write test                          │\n  │ 2. Run: pnpm test <file>.spec.tsx      │\n  │ 3. PASS? → Mark complete, next file    │\n  │    FAIL? → Fix first, then continue    │\n  └────────────────────────────────────────┘\n```\n\n### Complexity-Based Order\n\nProcess in this order for multi-file testing:\n\n1. 🟢 Utility functions (simplest)\n1. 🟢 Custom hooks\n1. 🟡 Simple components (presentational)\n1. 🟡 Medium components (state, effects)\n1. 🔴 Complex components (API, routing)\n1. 🔴 Integration tests (index files - last)\n\n### When to Refactor First\n\n- **Complexity > 50**: Break into smaller pieces before testing\n- **500+ lines**: Consider splitting before testing\n- **Many dependencies**: Extract logic into hooks first\n\n> 📖 See `references/workflow.md` for complete workflow details and todo list format.\n\n## Testing Strategy\n\n### Path-Level Testing (Directory Testing)\n\nWhen assigned to test a directory/path, test **ALL content** within that path:\n\n- Test all components, hooks, utilities in the directory (not just `index` file)\n- Use incremental approach: one file at a time, verify each before proceeding\n- Goal: 100% coverage of ALL files in the directory\n\n### Integration Testing First\n\n**Prefer integration testing** when writing tests for a directory:\n\n- ✅ **Import real project components** directly (including base components and siblings)\n- ✅ **Only mock**: API services (`@/service/*`), `next/navigation`, complex context providers\n- ❌ **DO NOT mock** base components (`@/app/components/base/*`)\n- ❌ **DO NOT mock** sibling/child components in the same directory\n\n> See [Test Structure Template](#test-structure-template) for correct import/mock patterns.\n\n### `nuqs` Query State Testing (Required for URL State Hooks)\n\nWhen a component or hook uses `useQueryState` / `useQueryStates`:\n\n- ✅ Use `NuqsTestingAdapter` (prefer shared helpers in `web/test/nuqs-testing.tsx`)\n- ✅ Assert URL synchronization via `onUrlUpdate` (`searchParams`, `options.history`)\n- ✅ For custom parsers (`createParser`), keep `parse` and `serialize` bijective and add round-trip edge cases (`%2F`, `%25`, spaces, legacy encoded values)\n- ✅ Verify default-clearing behavior (default values should be removed from URL when applicable)\n- ⚠️ Only mock `nuqs` directly when URL behavior is explicitly out of scope for the test\n\n## Core Principles\n\n### 1. AAA Pattern (Arrange-Act-Assert)\n\nEvery test should clearly separate:\n\n- **Arrange**: Setup test data and render component\n- **Act**: Perform user actions\n- **Assert**: Verify expected outcomes\n\n### 2. Black-Box Testing\n\n- Test observable behavior, not implementation details\n- Use semantic queries (getByRole, getByLabelText)\n- Avoid testing internal state directly\n- **Prefer pattern matching over hardcoded strings** in assertions:\n\n```typescript\n// ❌ Avoid: hardcoded text assertions\nexpect(screen.getByText(''Loading...'')).toBeInTheDocument()\n\n// ✅ Better: role-based queries\nexpect(screen.getByRole(''status'')).toBeInTheDocument()\n\n// ✅ Better: pattern matching\nexpect(screen.getByText(/loading/i)).toBeInTheDocument()\n```\n\n### 3. Single Behavior Per Test\n\nEach test verifies ONE user-observable behavior:\n\n```typescript\n// ✅ Good: One behavior\nit(''should disable button when loading'', () => {\n  render(<Button loading />)\n  expect(screen.getByRole(''button'')).toBeDisabled()\n})\n\n// ❌ Bad: Multiple behaviors\nit(''should handle loading state'', () => {\n  render(<Button loading />)\n  expect(screen.getByRole(''button'')).toBeDisabled()\n  expect(screen.getByText(''Loading...'')).toBeInTheDocument()\n  expect(screen.getByRole(''button'')).toHaveClass(''loading'')\n})\n```\n\n### 4. Semantic Naming\n\nUse `should <behavior> when <condition>`:\n\n```typescript\nit(''should show error message when validation fails'')\nit(''should call onSubmit when form is valid'')\nit(''should disable input when isReadOnly is true'')\n```\n\n## Required Test Scenarios\n\n### Always Required (All Components)\n\n1. **Rendering**: Component renders without crashing\n1. **Props**: Required props, optional props, default values\n1. **Edge Cases**: null, undefined, empty values, boundary conditions\n\n### Conditional (When Present)\n\n| Feature | Test Focus |\n|---------|-----------|\n| `useState` | Initial state, transitions, cleanup |\n| `useEffect` | Execution, dependencies, cleanup |\n| Event handlers | All onClick, onChange, onSubmit, keyboard |\n| API calls | Loading, success, error states |\n| Routing | Navigation, params, query strings |\n| `useCallback`/`useMemo` | Referential equality |\n| Context | Provider values, consumer behavior |\n| Forms | Validation, submission, error display |\n\n## Coverage Goals (Per File)\n\nFor each test file generated, aim for:\n\n- ✅ **100%** function coverage\n- ✅ **100%** statement coverage\n- ✅ **>95%** branch coverage\n- ✅ **>95%** line coverage\n\n> **Note**: For multi-file directories, process one file at a time with full coverage each. See `references/workflow.md`.\n\n## Detailed Guides\n\nFor more detailed information, refer to:\n\n- `references/workflow.md` - **Incremental testing workflow** (MUST READ for multi-file testing)\n- `references/mocking.md` - Mock patterns, Zustand store testing, and best practices\n- `references/async-testing.md` - Async operations and API calls\n- `references/domain-components.md` - Workflow, Dataset, Configuration testing\n- `references/common-patterns.md` - Frequently used testing patterns\n- `references/checklist.md` - Test generation checklist and validation steps\n\n## Authoritative References\n\n### Primary Specification (MUST follow)\n\n- **`web/docs/test.md`** - The canonical testing specification. This skill is derived from this document.\n\n### Reference Examples in Codebase\n\n- `web/utils/classnames.spec.ts` - Utility function tests\n- `web/app/components/base/button/index.spec.tsx` - Component tests\n- `web/__mocks__/provider-context.ts` - Mock factory example\n\n### Project Configuration\n\n- `web/vitest.config.ts` - Vitest configuration\n- `web/vitest.setup.ts` - Test environment setup\n- `web/scripts/analyze-component.js` - Component analysis tool\n- Modules are not mocked automatically. Global mocks live in `web/vitest.setup.ts` (for example `react-i18next`, `next/image`); mock other modules like `ky` or `mime` locally in test files.\n"},"category":"official","lastSynced":"2026-03-06T06:07:00.629Z","seo":{"title":{"en":"Frontend-Testing: Vitest + React Testing Library Setup Gu...","zh":"前端测试设置指南 - Vitest 和 React Testing Library","ja":"フロントエンドテストのベストプラクティス - Vitest と React Testing Library","ko":"프론트엔드 테스트 설정 가이드 - Vitest 및 React Testing Library","es":"Guía de configuración de pruebas frontend con Vitest y Re...","fr":"Guide de configuration des tests frontend avec Vitest et ...","de":"Einrichtungsleitfaden für Frontend-Tests mit Vitest und R...","pt":"Guia de Configuração de Testes Frontend com Vitest e React","ru":"Настройка Фронтенд Тестирования с Vitest и React - ИИ Агенты","ar":"دليل إعداد الاختبارات الأمامية مع Vitest و React - أدوات ..."},"description":{"en":"Unlock efficient frontend testing with Vitest and React Testing Library. Discover how to generate comprehensive tests and improve code quality - get started ...","zh":"使用 Vitest 和 React Testing Library 为 Dify 前端组件、hooks 和实用程序生成高质量测试。AIエージェント","ja":"Dify フロントエンドコンポーネント、hooks、ユーティリティのための高品質テストを Vitest と React Testing Library で生成します。AIエージェント","ko":"Vitest 및 React Testing Library를 사용하여 Dify 프론트엔드 컴포넌트, hooks 및 유틸리티에 대한 고품질 테스트를 생성합니다. AI 도구","es":"Automatice las pruebas de su aplicación frontend con nuestra habilidad de pruebas frontend, compatible con Vitest y React Testing Library","fr":"Automatisez les tests de votre application frontend avec notre compétence de test frontend, compatible avec Vitest et React Testing Library","de":"Automatisieren Sie die Tests Ihrer Frontend-Anwendung mit unserer Fähigkeit zum Frontend-Testen, kompatibel mit Vitest und React Testing Library","pt":"Aprenda a configurar testes frontend de alta qualidade com Vitest e React Testing Library para componentes, hooks e utilitários Dify","ru":"Узнайте, как настроить высококачественные фронтенд-тесты с Vitest и React Testing Library для компонентов, хуков и утилит Dify - ИИ Агенты","ar":"تعلم كيفية إعداد اختبارات أمامية عالية الجودة مع Vitest و React Testing Library لمكونات و Hooks و أدوات Dify - أدوات الذكاء الاصطناعي"},"definition":{"en":"Frontend-testing is a skill that enables AI agents to generate comprehensive tests for frontend component