ng Library","محدود للتطبيقات الأمامية المستندة إلى React","يعتمد على web/docs/test.md للاتفاقيات الاختبارية"]},"version":4},"contentHash":"be27373a5d11b4eca1ecc21148e97fbf9c893a4f3807787e5ce448e85cb5de13","repoEtag":"W/\"8b79270de464b84537dd173d2e750efb4b05e743496516f4c20a14f45fafde09\"","qualityScore":80}');
