INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benchflow-ai/skillsbench/gh-cli', 'gh-cli', 'benchflow-ai', 'skillsbench', 'community', 'gh-cli benchflow-ai skillsbench community GitHub CLI（gh）是一种命令行工具，允许开发者从命令行管理 GitHub 仓库、问题和拉取请求 GitHub CLI（gh）は、コマンドラインから GitHub リポジトリ、問題、プルリクエストを管理できるコマンドラインツール GitHub CLI(gh)는 명령줄에서 GitHub 저장소, 문제, 풀 요청을 관리할 수 있는 명령줄 도구 GitHub CLI es una herramienta de línea de comandos que permite a los desarrolladores trabajar con GitHub de manera eficiente. Ofrece comandos para gestionar issues, solicitudes de extracción y repositorios GitHub CLI est un outil en ligne de commande qui permet aux développeurs de travailler avec GitHub de manière efficace. Il propose des commandes pour gérer les problèmes, les demandes d''extraction et les référentiels GitHub CLI ist ein Kommandozeilen-Tool, das es Entwicklern ermöglicht, mit GitHub effizient zu arbeiten. Es bietet Befehle zum Verwalten von Issues, Pull-Requests und Repositorys O GitHub CLI é uma ferramenta de linha de comando que permite trabalhar com repositórios GitHub de forma eficiente. Ele oferece comandos para gerenciar problemas, pull requests e repositórios GitHub CLI — это инструмент командной строки, который позволяет работать с репозиториями GitHub эффективно. Он предлагает команды для управления проблемами, запросами на включение и репозиториями جيت هاب سي ال آي هو أداة سطر الأوامر التي تمكنك من العمل مع مستودعات جيت هاب بفعالية. يقدم أدوات لإدارة المشاكل وطلبات الدمج والمستودعات SkillsBench evaluates how well skills work and how effective agents are at using them GitHub CLI 命令行工具 仓库管理 问题管理 拉取请求管理 API 请求 工作流运行 SkillsBench evaluates how well skills work and how effective agents are at using them');
