INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/code-porter', 'code-porter', 'majiayu000', 'claude-skill-registry', 'community', 'code-porter majiayu000 claude-skill-registry community 代码搬运师是一种开发技能，优先使用开源方案和库，减少重复劳动，提高开发效率 コードポーターは、オープンソースの方案とライブラリを優先して使用し、重複作業を減らし、開発の効率を向上させる開発スキルです 코드 포터는 오픈소스 方案과 라이브러리를 우선하여 사용하여重複 작업을 줄이고 개발 효율성을 높이는 개발 스킬입니다 Code Porter es una habilidad que promueve la reutilización de código abierto y la eficiencia en el desarrollo de software Code Porter est une compétence qui promeut la réutilisation de code ouvert et l''efficacité dans le développement de logiciels Code Porter ist eine Fähigkeit, die die Wiederverwendung von Open-Source-Code und die Effizienz in der Softwareentwicklung fördert O Code Porter é uma ferramenta que facilita a reutilização de código de projetos open source, ajudando a melhorar a eficiência e reduzir o tempo de desenvolvimento. Code Porter - это инструмент, который облегчает повторное использование кода из открытых проектов, помогая улучшить эффективность и сократить время разработки. كود بورتر هو أداة تسهل إعادة استخدام الشفرة من المشاريع مفتوحة المصدر، مما يساعد على تحسين الكفاءة وتقليل وقت التطوير. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 代码搬运师 开源方案 开发技能 优先使用开源库 减少重复劳动 提高开发效率 新功能实现 技术方案选择 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cristianoliveira/dotfiles/git-explorer', 'community', 'cristianoliveira', 'dotfiles', 'cristianoliveira/dotfiles', 'git-explorer', 0, 0, 80, '2026-02-20T04:13:19.570Z', '2026-02-20T04:20:16.491Z', 'fa055620e231dd380b652de229dcd2da8e05935c6a38f852fe5998b97dd74d28', '{"id":"cristianoliveira/dotfiles/git-explorer","name":"git-explorer","description":{"zh":"Git Explorer 技能提供 GitHub 高级搜索功能，支持仓库、代码、问题、拉取请求或提交的搜索","ja":"Git Explorer スキルは、GitHub の高度な検索機能を提供し、リポジトリ、コード、問題、プルリクエスト、またはコミットの検索をサポートします","ko":"Git Explorer 스킬은 GitHub 고급 검색 기능을 제공하며 저장소, 코드, 문제, 풀 요청 또는 커밋의 검색을 지원합니다","es":"El skill git-explorer permite buscar y explorar contenido de GitHub, incluyendo repositorios y código","fr":"Le skill git-explorer permet de rechercher et d''explorer le contenu GitHub, y compris les référentiels et le code","de":"Der git-explorer-Skill ermöglicht die Suche und Erkundung von GitHub-Inhalten, einschließlich Repositories und Code","pt":"O Explorador Git é uma ferramenta para buscar e explorar conteúdo do GitHub, incluindo repositórios, código, issues e pull requests.","ru":"Git-Эксплорер - это инструмент для поиска и изучения контента GitHub, включая репозитории, код, проблемы и запросы на слияние.","ar":"مستكشف جيت هو أداة للبحث واستكشاف محتوى جيت هاب، بما في ذلك المستودعات والاكواد والقضايا والطلبات السحابية.","en":"My dotfiles for macOS and NixOS. :sunglasses: :package:"},"seo":{"title":{"zh":"Git Explorer 技能 - GitHub 高级搜索","ja":"Git Explorer スキル - GitHub 高度な検索","ko":"Git Explorer 스킬 - GitHub 고급 검색","es":"Explorador de Git: Busca y explora contenido de GitHub","fr":"Explorateur Git: Recherchez et explorez le contenu GitHub","de":"Git-Explorer: Durchsuchen und erkunden Sie GitHub-Inhalte","pt":"Explorador Git: Busca Repositórios e Código no GitHub","ru":"Git-Эксплорер: Поиск Репозиториев и Кодов на GitHub","ar":"مستكشف جيت: بحث مستودعات واكواد على جيت هاب","en":"git-explorer"},"description":{"zh":"Git Explorer 技能提供 GitHub 高级搜索功能，支持仓库、代码、问题、拉取请求或提交的搜索","ja":"Git Explorer スキルは、GitHub の高度な検索機能を提供し、リポジトリ、コード、問題、プルリクエスト、またはコミットの検索をサポートします","ko":"Git Explorer 스킬은 GitHub 고급 검색 기능을 제공하며 저장소, 코드, 문제, 풀 요청 또는 커밋의 검색을 지원합니다","es":"El skill git-explorer permite buscar y explorar contenido de GitHub, incluyendo repositorios y código","fr":"Le skill git-explorer permet de rechercher et d''explorer le contenu GitHub, y compris les référentiels et le code","de":"Der git-explorer-Skill ermöglicht die Suche und Erkundung von GitHub-Inhalten, einschließlich Repositories und Code","pt":"O Explorador Git é uma ferramenta para buscar e explorar conteúdo do GitHub, incluindo repositórios, código, issues e pull requests.","ru":"Git-Эксплорер - это инструмент для поиска и изучения контента GitHub, включая репозитории, код, проблемы и запросы на слияние.","ar":"مستكشف جيت هو أداة للبحث واستكشاف محتوى جيت هاب، بما في ذلك المستودعات والاكواد والقضايا والطلبات السحابية.","en":"My dotfiles for macOS and NixOS. :sunglasses: :package:"},"definition":{"en":"My dotfiles for macOS and NixOS. :sunglasses: :package:"},"features":{"zh":["GitHub 高级搜索","仓库搜索","代码搜索","问题搜索","拉取请求搜索","提交搜索"],"ja":["GitHub の高度な検索","リポジトリ検索","コード検索","問題検索","プルリクエスト検索","コミット検索"],"ko":["GitHub 고급 검색","저장소 검색","코드 검색","문제 검색","풀 요청 검색","커밋 검색"],"es":["Búsqueda avanzada de GitHub","Exploración de repositorios y código","Soporte para solicitudes de extracción y problemas","Uso de la CLI de GitHub (gh) para consultas sofisticadas","Búsqueda de repositorios según criterios específicos"],"fr":["Recherche avancée sur GitHub","Exploration de référentiels et de code","Prise en charge des demandes d''extraction et des problèmes","Utilisation de la CLI GitHub (gh) pour des requêtes sophistiquées","Recherche de référentiels selon des critères spécifiques"],"de":["Erweiterte GitHub-Suche","Durchsuchen von Repositories und Code","Unterstützung für Pull-Requests und Probleme","Verwendung der GitHub-CLI (gh) für komplexe Abfragen","Suche nach Repositories nach spezifischen Kriterien"],"pt":["Busca avançada por repositórios e código","Filtragem por critérios específicos","Suporte à busca por issues e pull requests","Integração com a CLI do GitHub","Suporte à construção de consultas sofisticadas"],"ru":["Продвинутый поиск репозиториев и кода","Фильтрация по конкретным критериям","Поддержка поиска проблем и запросов на слияние","Интеграция с CLI GitHub","Поддержка построения сложных запросов"],"ar":["بحث متقدم للمستودعات والاكواد","التصفية حسب معايير محددة","دعم البحث عن القضايا والطلبات السحابية","التكامل مع واجهة سطر الأوامر جيت هاب","دعم بناء استفسارات متقدمة"]},"keywords":{"zh":["Git Explorer","GitHub 搜索","仓库搜索","代码搜索","问题搜索","拉取请求搜索","提交搜索","GitHub 高级搜索"],"ja":["Git Explorer","GitHub 検索","リポジトリ検索","コード検索","問題検索","プルリクエスト検索","コミット検索","GitHub 高度な検索"],"ko":["Git Explorer","GitHub 검색","저장소 검색","코드 검색","문제 검색","풀 요청 검색","커밋 검색","GitHub 고급 검색"],"es":["git-explorer","búsqueda de GitHub","exploración de repositorios","repositorios de código abierto","GitHub CLI","búsqueda avanzada","desarrollo de software","herramientas de desarrollo"],"fr":["git-explorer","recherche GitHub","exploration de référentiels","référentiels de code open source","CLI GitHub","recherche avancée","développement de logiciels","outils de développement"],"de":["git-explorer","GitHub-Suche","Repository-Durchsuchung","Open-Source-Code-Repositorys","GitHub-CLI","erweiterte Suche","Software-Entwicklung","Entwicklertools"],"pt":["explorador git","busca github","repositórios github","código github","issues github","pull requests github","github cli","busca avançada github"],"ru":["git-эксплорер","поиск github","репозитории github","код github","проблемы github","запросы на слияние github","github cli","продвинутый поиск github"],"ar":["مستكشف جيت","بحث جيت هاب","مستودعات جيت هاب","اكواد جيت هاب","قضايا جيت هاب","طلبات سحابية جيت هاب","واجهة سطر الأوامر جيت هاب","بحث متقدم جيت هاب"]}},"owner":"cristianoliveira","repo":"dotfiles","repoPath":"cristianoliveira/dotfiles","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.570Z","topics":[],"category":"community","skillMd":{"name":"git-explorer","description":"Use when the user mentions searching Git/GitHub to explore GitHub repositories, code, issues, and commits using advanced search capabilities.","bodyPreview":"# Git Explorer Skill\n\nUse this skill when the user needs to search or explore GitHub content, including repositories, code, issues, pull requests, or commits. This skill leverages the `github-explorer` agent for advanced GitHub search using the GitHub CLI (`gh`) with sophisticated query construction.\n\n## When to Use This Skill\n\n- User explicitly mentions \"search GitHub\", \"GitHub search\", or similar phrases\n- Need to find github repositories matching specific criteria (language, stars, topics, et","body":"# Git Explorer Skill\n\nUse this skill when the user needs to search or explore GitHub content, including repositories, code, issues, pull requests, or commits. This skill leverages the `github-explorer` agent for advanced GitHub search using the GitHub CLI (`gh`) with sophisticated query construction.\n\n## When to Use This Skill\n\n- User explicitly mentions \"search GitHub\", \"GitHub search\", or similar phrases\n- Need to find github repositories matching specific criteria (language, stars, topics, etc.)\n- Need to search for code snippets across GitHub\n- Need to explore issues, pull requests, or commits\n- Need to perform advanced searches using GitHub''s query language\n\n## Key Capabilities\n\n1. **Repository Search**: Find repositories by name, description, topics, language, stars, forks\n2. **Code Search**: Search for code snippets across all public repositories\n3. **Issue/PR Search**: Find issues and pull requests by state, labels, assignees, authors\n4. **Commit Search**: Search commits by author, date, message content\n5. **Advanced Filtering**: Use qualifiers, boolean operators, comparison operators, and ranges\n\n## Recommended Approach\n\n### 1. Invoke the GitHub Explorer Agent\nFor complex GitHub searches, delegate to the specialized `github-explorer` agent:\n\n```bash\n# Use the Task tool to launch the github-explorer agent\nTask(description=\"Search GitHub\", prompt=\"Search GitHub for repositories about machine learning with Python and >1000 stars\", subagent_type=\"github-explorer\")\n```\n\nThe github-explorer agent has expertise in:\n- GitHub CLI (`gh search`) with all subcommands\n- Advanced query construction with qualifiers and operators\n- Rate limit management and authentication\n- JSON output processing and analysis\n\n### 2. Direct GitHub CLI Commands\nFor simple searches, you can use `gh` commands directly:\n\n```bash\n# Search repositories\ngh search repos \"machine learning\" --language=python --stars=\">1000\" --limit=10 --json\n\n# Search code\ngh search code \"def train_model\" --language=python --repo=org/repo --json\n\n# Search issues\ngh search issues \"bug\" --state=open --label=bug --json\n\n# Search commits\ngh search commits \"fix memory leak\" --author=username --json\n```\n\n### 3. Query Construction Examples\n\n**Basic repository search:**\n```bash\ngh search repos \"neural network\" --language=python --stars=\">500\" --json | jq -r ''.[] | \"\\(.nameWithOwner): \\(.description)\"''\n```\n\n**Advanced search with multiple qualifiers:**\n```bash\ngh search repos \"topic:deep-learning language:python stars:>1000 forks:>100\" --json\n```\n\n**Code search with path filtering:**\n```bash\ngh search code \"import torch\" --language=python --path=\"src/\" --json\n```\n\n## Qualifiers Reference\n\nCommon GitHub search qualifiers:\n- `repo:owner/name` - Specific repository\n- `language:python` - Programming language\n- `stars:>1000` - Star count\n- `forks:>100` - Fork count\n- `topic:machine-learning` - Repository topics\n- `path:src/` - File path\n- `filename:*.py` - File name pattern\n- `is:public` / `is:private` - Repository visibility\n- `created:>2023-01-01` - Creation date\n- `pushed:>2024-01-01` - Last push date\n\n## Best Practices\n\n1. **Use JSON output**: Always add `--json` flag for machine-readable results\n2. **Limit results**: Use `--limit` to control output size (default 30, max 100)\n3. **Authenticate for higher limits**: Run `gh auth login` for higher rate limits (30 vs 10 requests/minute)\n4. **Combine flag-based and raw qualifiers**: Some qualifiers work better as flags, others in raw query\n5. **Test with small limits first**: Use `--limit=2` to verify query syntax before full execution\n6. **Process results with jq**: Filter and format JSON output for readability\n\n## Common Use Cases\n\n### Finding Popular Repositories\n```bash\ngh search repos \"machine learning\" --language=python --stars=\">10000\" --json | jq -r ''.[] | \"\\(.nameWithOwner) (\\(.stargazerCount) stars): \\(.description)\"''\n```\n\n### Searching for Code Patterns\n```bash\ngh search code \"from transformers import\" --language=python --json | jq -r ''.[] | \"\\(.repository.nameWithOwner): \\(.path)\"''\n```\n\n### Exploring Issues by Label\n```bash\ngh search issues \"good first issue\" --state=open --label=\"good first issue\" --json | jq -r ''.[] | \"\\(.repository.nameWithOwner)#\\(.number): \\(.title)\"''\n```\n\n## References\n\n- GitHub Explorer agent: `/Users/cristianoliveira/.dotfiles/ai/shared/agents/github-explorer.md`\n- GitHub advanced search research: `.tmp/docs/github-advanced-search.md`\n- GitHub CLI documentation: `gh help search`\n- GitHub search syntax: https://docs.github.com/en/search-github\n\n## Notes\n\n- For complex boolean logic (parentheses), use the github-explorer agent which has workarounds using the API endpoint\n- The github-explorer agent is specifically designed to handle GitHub''s advanced search capabilities and query limitations\n- Always consider rate limits when performing multiple searches\n"},"lastSynced":"2026-02-20T04:20:16.491Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub Integration Agents needing advanced repository search and exploration capabilities using the GitHub CLI (gh).","zh":"适合需要使用 GitHub CLI（gh）进行高级仓库搜索和探索的 GitHub 集成代理。","ja":"GitHub CLI（gh）を使用した高度なリポジトリ検索および探索機能が必要なGitHub統合エージェントに適しています。","ko":"GitHub CLI(gh)를 사용하여 고급 저장소 검색 및 탐색 기능이 필요한 GitHub 통합 에이전트에 적합합니다.","es":"Perfecto para Agentes de Integración de GitHub que necesitan capacidades de búsqueda y exploración de repositorios avanzadas utilizando la CLI de GitHub (gh).","fr":"Parfait pour les Agents d''Intégration GitHub nécessitant des capacités de recherche et d''exploration de référentiels avancées en utilisant la CLI GitHub (gh).","de":"Perfekt für GitHub-Integration-Agents, die erweiterte Repository-Such- und Explorationsfunktionen unter Verwendung der GitHub-CLI (gh) benötigen.","pt":"Perfeito para Agentes de Integração do GitHub que necessitam de capacidades avançadas de busca e exploração de repositórios usando a CLI do GitHub (gh).","ru":"Идеально подходит для агентов интеграции GitHub, которым необходимы расширенные возможности поиска и изучения репозиториев с использованием CLI GitHub (gh).","ar":"مثالي لعميل تكامل GitHub الذي يحتاج إلىقدرات متقدمة للبحث واستكشاف المستودعات باستخدام واجهة سطر الأوامر GitHub (gh)."},"recommendation":{"en":"Empowers agents to perform sophisticated GitHub searches using advanced query construction, enabling them to find specific repositories, code, issues, pull requests, or commits based on criteria like language, stars, and topics, all leveraging the github-explorer agent.","zh":"赋予代理执行复杂的GitHub搜索的能力，使用高级查询构造，能够根据语言、星级和主题等标准找到特定的仓库、代码、问题、拉取请求或提交，所有这些都利用了github-explorer代理。","ja":"エージェントが高度なGitHub検索を実行できるようにし、高度なクエリ構築を使用して、言語、スター数、トピックなどに基づいて、特定のリポジトリ、コード、問題、プルリクエスト、またはコミットを検索できるようにする。すべてこれらは、github-explorerエージェントを活用しています。","ko":"에이전트가 고급 GitHub 검색을 수행할 수 있도록 하여 언어, 별, 주제 등에 따라 특정 저장소, 코드, 문제, 풀 요청 또는 커밋을 찾을 수 있도록 고급 쿼리 구성을 사용하며, 모두 github-explorer 에이전트를 활용합니다.","es":"Habilita a los agentes a realizar búsquedas sofisticadas de GitHub utilizando una construcción de consultas avanzadas, lo que les permite encontrar repositorios, código, problemas, solicitudes de extracción o confirmaciones específicas en función de criterios como lenguaje, estrellas y temas, todo aprovechando el agente github-explorer.","fr":"Permet aux agents d''effectuer des recherches GitHub sophistiquées en utilisant une construction de requêtes avancée, leur permettant de trouver des référentiels, du code, des problèmes, des demandes d''extraction ou des validations spécifiques en fonction de critères tels que la langue, les étoiles et les sujets, le tout en exploitant l''agent github-explorer.","de":"Ermöglicht es Agenten, komplexe GitHub-Suchen durchzuführen, indem sie eine erweiterte Abfragekonstruktion verwenden, sodass sie spezifische Repositorys, Code, Probleme, Pull-Requests oder Commits basierend auf Kriterien wie Sprache, Sterne und Themen finden können, und dabei den github-explorer-Agent nutzen.","pt":"Habilita os agentes a realizar buscas sofisticadas no GitHub usando a construção de consultas avançadas, permitindo que eles encontrem repositórios, código, problemas, solicitações de pull ou commits específicos com base em critérios como linguagem, estrelas e tópicos, todos aproveitando o agente github-explorer.","ru":"Наделяет агентов возможностью выполнять сложные поиски в GitHub с использованием продвинутой конструкции запросов, что позволяет им находить конкретные репозитории, код, проблемы, запросы на включение или коммиты на основе критериев, таких как язык, звезды и темы, все это благодаря агенту github-explorer.","ar":"يمنح العميل القدرة على إجراء عمليات بحث متقدمة على GitHub باستخدام بناء استفسار متقدم، مما يسمح لهم بالعثور على مستودعات أو رمز أو مشاكل أو طلبات سحب أو عمليات إيداع محددة بناءً على معايير مثل اللغة والنجوم والمواضيع، وكل ذلك من خلال عميل مستكشف GitHub."},"useCases":{"en":["Searching GitHub repositories by specific languages or topics","Exploring GitHub issues and pull requests for trending projects","Finding commits related to specific features or bug fixes"],"zh":["根据特定语言或主题搜索GitHub仓库","探索热门项目的GitHub问题和拉取请求","找到与特定功能或错误修复相关的提交"],"ja":["特定言語やトピックによるGitHubリポジトリの検索","トレンドプロジェクトのGitHubの問題やプルリクエストの探索","特定機能またはバグ修正に関連するコミットの検索"],"ko":["특정 언어 또는 주제에 따라 GitHub 저장소를 검색","人気 프로젝트의 GitHub 문제 및 풀 요청을 탐색","특정 기능 또는 버그 수정과 관련된 커밋을 찾는 것"],"es":["Buscar repositorios de GitHub por lenguajes o temas específicos","Explorar problemas y solicitudes de extracción de GitHub para proyectos de tendencia","Encontrar confirmaciones relacionadas con características o correcciones de errores específicas"],"fr":["Rechercher des référentiels GitHub par langages ou sujets spécifiques","Explorer les problèmes et les demandes d''extraction de GitHub pour les projets tendance","Trouver des validations liées à des fonctionnalités ou des corrections de bogues spécifiques"],"de":["GitHub-Repositorys nach bestimmten Sprachen oder Themen suchen","GitHub-Probleme und Pull-Requests für Trendsprojekte erkunden","Commits in Bezug auf bestimmte Funktionen oder Fehlerbehebungen finden"],"pt":["Pesquisar repositórios do GitHub por linguagens ou tópicos específicos","Explorar problemas e solicitações de pull do GitHub para projetos em tendência","Encontrar commits relacionados a recursos ou correções de bugs específicos"],"ru":["Поиск репозиториев GitHub по конкретным языкам или темам","Изучение проблем и запросов на включение GitHub для проектов, находящихся в тренде","Поиск коммитов, связанных с конкретными функциями или исправлениями ошибок"],"ar":["بحث المستودعات على GitHub حسب اللغات أو المواضيع المحددة","استكشاف المشاكل وطلبات السحب على GitHub للمشاريع الشائعة","العثور على عمليات الإيداع المرتبطة بالسمات أو إصلاحات الأعطال المحددة"]},"limitations":{"en":["Requires GitHub CLI (gh) installation and configuration","Dependent on the github-explorer agent for advanced search functionality"],"zh":["需要安装和配置GitHub CLI（gh）","依赖github-explorer代理进行高级搜索功能"],"ja":["GitHub CLI（gh）のインストールと構成が必要","高度な検索機能にはgithub-explorerエージェントに依存"],"ko":["GitHub CLI(gh) 설치 및 구성 필요","고급 검색 기능은 github-explorer 에이전트에 의존"],"es":["Requiere la instalación y configuración de la CLI de GitHub (gh)","Depende del agente github-explorer para la funcionalidad de búsqueda avanzada"],"fr":["Nécessite l''installation et la configuration de la CLI GitHub (gh)","Dépend de l''agent github-explorer pour la fonctionnalité de recherche avancée"],"de":["Benötigt die Installation und Konfiguration der GitHub-CLI (gh)","Ist von dem github-explorer-Agent für die erweiterte Suchfunktion abhängig"],"pt":["Requer instalação e configuração da CLI do GitHub (gh)","Depende do agente github-explorer para funcionalidade de busca avançada"],"ru":["Требует установки и конфигурации CLI GitHub (gh)","Зависит от агента github-explorer для расширенной функциональности поиска"],"ar":["يتطلب تثبيت وتهيئة واجهة سطر الأوامر GitHub (gh)","يعتمد على عميل مستكشف GitHub لتحقيق وظيفة البحث المتقدم"]},"version":3},"contentHash":"fa055620e231dd380b652de229dcd2da8e05935c6a38f852fe5998b97dd74d28","qualityScore":80}');
