INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cristianoliveira/dotfiles/git-explorer', 'git-explorer', 'cristianoliveira', 'dotfiles', 'community', 'git-explorer cristianoliveira dotfiles community Git Explorer 技能提供 GitHub 高级搜索功能，支持仓库、代码、问题、拉取请求或提交的搜索 Git Explorer スキルは、GitHub の高度な検索機能を提供し、リポジトリ、コード、問題、プルリクエスト、またはコミットの検索をサポートします Git Explorer 스킬은 GitHub 고급 검색 기능을 제공하며 저장소, 코드, 문제, 풀 요청 또는 커밋의 검색을 지원합니다 El skill git-explorer permite buscar y explorar contenido de GitHub, incluyendo repositorios y código Le skill git-explorer permet de rechercher et d''explorer le contenu GitHub, y compris les référentiels et le code Der git-explorer-Skill ermöglicht die Suche und Erkundung von GitHub-Inhalten, einschließlich Repositories und Code O Explorador Git é uma ferramenta para buscar e explorar conteúdo do GitHub, incluindo repositórios, código, issues e pull requests. Git-Эксплорер - это инструмент для поиска и изучения контента GitHub, включая репозитории, код, проблемы и запросы на слияние. مستكشف جيت هو أداة للبحث واستكشاف محتوى جيت هاب، بما في ذلك المستودعات والاكواد والقضايا والطلبات السحابية. My dotfiles for macOS and NixOS. :sunglasses: :package: Git Explorer GitHub 搜索 仓库搜索 代码搜索 问题搜索 拉取请求搜索 提交搜索 GitHub 高级搜索 My dotfiles for macOS and NixOS. :sunglasses: :package:');
