INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/gh-cli', 'gh-cli', 'majiayu000', 'claude-skill-registry', 'community', 'gh-cli majiayu000 claude-skill-registry community GitHub CLI (gh) 是一个命令行工具，用于与 GitHub 进行交互。它提供了便捷的方式来管理仓库、问题和Pull Request GitHub CLI (gh) は、GitHub と対話するためのコマンドラインツールです。リポジトリ、issue、Pull Request を管理するための便利な方法を提供します GitHub CLI (gh) 는 GitHub 와 상호 작용하기 위한 명령줄 도구입니다. 저장소, 이슈, 풀 リクエスト를 관리하기 위한 편리한 방법을 제공합니다 La CLI de GitHub es una herramienta para trabajar con GitHub desde la línea de comandos. Ofrece una forma eficiente de interactuar con GitHub La CLI GitHub est un outil pour travailler avec GitHub depuis la ligne de commande. Elle offre une façon efficace d''interagir avec GitHub Die GitHub-CLI ist ein Tool, um mit GitHub von der Kommandozeile aus zu arbeiten. Sie bietet eine effiziente Möglichkeit, mit GitHub zu interagieren O GitHub CLI é uma ferramenta poderosa para desenvolvedores que desejam trabalhar com o GitHub de forma eficiente GitHub CLI — это мощный инструмент для разработчиков, которые хотят работать с GitHub эффективно واجهة سطر الأوامر لجيت هاب هي أداة قوية للمطورين الذين يرغبون في العمل مع جيت هاب بفعالية The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app GitHub CLI gh 命令行工具 仓库管理 问题管理 Pull Request GitHub 交互 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
