INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mfts/papermark/gh-cli', 'gh-cli', 'mfts', 'papermark', 'community', 'gh-cli mfts papermark community GitHub CLI（gh）是GitHub的命令行接口，允许开发人员从终端直接与GitHub交互。版本2.85.0 GitHub CLI（gh）は、開発者がターミナルから直接GitHubとやり取りできるGitHubのコマンドラインインターフェイスです。バージョン2.85.0 GitHub CLI(gh)는 개발자가 터미널에서 직접 GitHub와 상호 작용할 수 있는 GitHub의 명령줄 인터페이스입니다. 버전 2.85.0 GitHub CLI es una herramienta de línea de comandos para trabajar con GitHub. Ofrece una forma sencilla de interactuar con la plataforma desde tu terminal GitHub CLI est un outil de ligne de commande pour travailler avec GitHub. Il offre une façon simple d''interagir avec la plateforme depuis votre terminal GitHub CLI ist ein Kommandozeilen-Tool, um mit GitHub zu arbeiten. Es bietet eine einfache Möglichkeit, mit der Plattform über Ihr Terminal zu interagieren O gh-cli é uma ferramenta de linha de comando para trabalhar com o GitHub. Veja como instalar e usar. gh-cli - это инструмент командной строки для работы с GitHub. Посмотрите, как установить и использовать. gh-cli هي أداة سطر الأوامر للعمل مع جيت هاب. انظر كيفية التثبيت والاستخدام. Papermark is the open-source DocSend alternative with built-in analytics and custom domains. GitHub CLI gh 命令行工具 GitHub API 开发者工具 版本控制 代码管理 协作工具 Papermark is the open-source DocSend alternative with built-in analytics and custom domains.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jonathan-vella/azure-agentic-infraops-accelerator/gh-cli', 'community', 'jonathan-vella', 'azure-agentic-infraops-accelerator', 'jonathan-vella/azure-agentic-infraops-accelerator', 'gh-cli', 0, 0, 80, '2026-02-20T04:13:19.571Z', '2026-02-20T04:21:54.483Z', '22d027a3219c487eefd4c7dae6e1a44b0ee8886aa5bdb9020c8886a2337c2fb4', '{"id":"jonathan-vella/azure-agentic-infraops-accelerator/gh-cli","name":"gh-cli","description":{"zh":"GitHub CLI (gh) 是一个强大的命令行工具，用于自动化 GitHub 工作流和开发过程","ja":"GitHub CLI (gh) は、GitHub のワークフローと開発プロセスを自動化する強力なコマンドラインツール","ko":"GitHub CLI (gh) 는 GitHub 의 워크플로우와 개발 프로세스를 자동화하는 강력한 명령줄 툴","es":"El agente gh-cli es una plantilla de inicio para el desarrollo de infraestructura de Azure que contiene agentes personalizados de Copilot y servidor de precios de Azure.","fr":"L''agent gh-cli est un modèle de démarrage pour le développement d''infrastructure Azure qui contient des agents Copilot personnalisés et un serveur de tarification Azure.","de":"Der gh-cli-Agent ist eine Startvorlage für die Entwicklung von Azure-Infrastruktur, die benutzerdefinierte Copilot-Agents und einen Azure-Preisserver enthält.","pt":"O gh-cli é uma ferramenta de linha de comando para desenvolvedores que permite trabalhar com o GitHub de forma eficiente. Ele inclui recursos como auto-sincronização e workflow de 7 etapas.","ru":"gh-cli - это командная строка для разработчиков, которая позволяет работать с GitHub эффективно. Она включает в себя функции, такие как автоматическая синхронизация и 7-шаговый рабочий процесс.","ar":"gh-cli هي أداة سطر أوامر للمطورين التي تمكنهم من العمل مع GitHub بفعالية. تشمل ميزات مثل التزامن التلقائي و워크 فلوي 7 خطوات.","en":"Starter template for agentic Azure infrastructure development. Contains custom Copilot agents (architect, bicep-plan, bicep-implement), Azure Pricing MCP server, and the 7-step workflow. Auto-syncs from the main repository."},"seo":{"title":{"zh":"GitHub CLI (gh) 技术指南","ja":"GitHub CLI (gh) 技術ガイド","ko":"GitHub CLI (gh) 개발자 안내서","es":"gh-cli: Desarrollo de infraestructura de Azure","fr":"gh-cli : Développement d''infrastructure Azure","de":"gh-cli: Azure-Infrastruktur-Entwicklung","pt":"gh-cli: Ferramenta de Linha de Comando para Desenvolvedores","ru":"gh-cli: Командная строка для разработчиков","ar":"gh-cli: أداة سطر الأوامر للمطورين","en":"gh-cli"},"description":{"zh":"GitHub CLI (gh) 是一个强大的命令行工具，用于自动化 GitHub 工作流和开发过程","ja":"GitHub CLI (gh) は、GitHub のワークフローと開発プロセスを自動化する強力なコマンドラインツール","ko":"GitHub CLI (gh) 는 GitHub 의 워크플로우와 개발 프로세스를 자동화하는 강력한 명령줄 툴","es":"El agente gh-cli es una plantilla de inicio para el desarrollo de infraestructura de Azure que contiene agentes personalizados de Copilot y servidor de preci...","fr":"L''agent gh-cli est un modèle de démarrage pour le développement d''infrastructure Azure qui contient des agents Copilot personnalisés et un serveur de tarific...","de":"Der gh-cli-Agent ist eine Startvorlage für die Entwicklung von Azure-Infrastruktur, die benutzerdefinierte Copilot-Agents und einen Azure-Preisserver enthält.","pt":"O gh-cli é uma ferramenta de linha de comando para desenvolvedores que permite trabalhar com o GitHub de forma eficiente. Ele inclui recursos como auto-sincr...","ru":"gh-cli - это командная строка для разработчиков, которая позволяет работать с GitHub эффективно. Она включает в себя функции, такие как автоматическая синхро...","ar":"gh-cli هي أداة سطر أوامر للمطورين التي تمكنهم من العمل مع GitHub بفعالية. تشمل ميزات مثل التزامن التلقائي و워크 فلوي 7 خطوات.","en":"Starter template for agentic Azure infrastructure development. Contains custom Copilot agents (architect, bicep-plan, bicep-implement), Azure Pricing MCP ser..."},"definition":{"en":"Starter template for agentic Azure infrastructure development. Contains custom Copilot agents (architect, bicep-plan, bicep-implement), Azure Pricing MCP server, and the 7-step workflow. Auto-syncs from the main repository."},"features":{"zh":["自动化 GitHub 工作流","支持多种开发语言","提供强大的命令行工具","实现自动化部署","支持 GitHub Actions"],"ja":["GitHub ワークフローの自動化","複数の開発言語をサポート","強力なコマンドラインツールを提供","自動化デプロイを実現","GitHub Actions をサポート"],"ko":["GitHub 워크플로우의 자동화","다수의 개발 언어를 지원","강력한 명령줄 툴을 제공","자동화 배포를 구현","GitHub Actions 를 지원"],"es":["Plantilla de inicio para el desarrollo de infraestructura de Azure","Agentes personalizados de Copilot","Servidor de precios de Azure","Flujo de trabajo de 7 pasos","Sincronización automática desde el repositorio principal"],"fr":["Modèle de démarrage pour le développement d''infrastructure Azure","Agents Copilot personnalisés","Serveur de tarification Azure","Flux de travail de 7 étapes","Synchronisation automatique depuis le référentiel principal"],"de":["Startvorlage für die Entwicklung von Azure-Infrastruktur","Benutzerdefinierte Copilot-Agents","Azure-Preisserver","7-Schritte-Arbeitsablauf","Automatische Synchronisation vom Hauptrepository"],"pt":["Auto-sincronização com o repositório principal","Workflow de 7 etapas para desenvolvimento de infraestrutura Azure","Acesso a recursos do GitHub via linha de comando","Integração com o Azure Pricing MCP server","Suporte a custom Copilot agents"],"ru":["Автоматическая синхронизация с основным репозиторием","7-шаговый рабочий процесс для разработки инфраструктуры Azure","Доступ к ресурсам GitHub через командную строку","Интеграция с сервером Azure Pricing MCP","Поддержка пользовательских агентов Copilot"],"ar":["التزامن التلقائي مع المستودع الرئيسي","워크 فلوي 7 خطوات لتطوير البنية التحتية ل Azure","الوصول إلى موارد GitHub عبر سطر الأوامر","التكامل مع خادم Azure Pricing MCP","دعم وكلاء Copilot المخصصين"]},"keywords":{"zh":["GitHub CLI","gh","命令行工具","自动化工作流","开发效率","GitHub Actions"],"ja":["GitHub CLI","gh","コマンドラインツール","ワークフローの自動化","開発効率","GitHub Actions"],"ko":["GitHub CLI","gh","명령줄 툴","워크플로우의 자동화","개발 효율","GitHub Actions"],"es":["desarrollo de infraestructura de Azure","gh-cli","agentes de Copilot","servidor de precios de Azure","flujo de trabajo de 7 pasos","sincronización automática","desarrollo de software","herramientas de desarrollo"],"fr":["développement d''infrastructure Azure","gh-cli","agents Copilot","serveur de tarification Azure","flux de travail de 7 étapes","synchronisation automatique","développement de logiciels","outils de développement"],"de":["Entwicklung von Azure-Infrastruktur","gh-cli","Copilot-Agents","Azure-Preisserver","7-Schritte-Arbeitsablauf","automatische Synchronisation","Software-Entwicklung","Entwicklungstools"],"pt":["gh-cli","GitHub CLI","desenvolvimento de infraestrutura Azure","linha de comando","auto-sincronização","workflow de 7 etapas","Azure Pricing MCP server","custom Copilot agents"],"ru":["gh-cli","GitHub CLI","разработка инфраструктуры Azure","командная строка","автоматическая синхронизация","7-шаговый рабочий процесс","сервер Azure Pricing MCP","пользовательские агенты Copilot"],"ar":["gh-cli","GitHub CLI","تطوير البنية التحتية ل Azure","سطر الأوامر","التزامن التلقائي","워크 فلوي 7 خطوات","خادم Azure Pricing MCP","وكلاء Copilot المخصصين"]}},"owner":"jonathan-vella","repo":"azure-agentic-infraops-accelerator","repoPath":"jonathan-vella/azure-agentic-infraops-accelerator","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.571Z","topics":[],"category":"community","skillMd":{"name":"gh-cli","description":">","bodyPreview":"# GitHub CLI (gh)\n\nComprehensive reference for GitHub CLI (gh) - work seamlessly with GitHub from the command line.\n\n**Version:** 2.85.0 (current as of January 2026)\n\n## Prerequisites\n\n### Installation\n\n```bash\n# macOS\nbrew install gh\n\n# Linux\ncurl -fsSL https://cli.github.com/packages/githubcli-archive-keyring.gpg | sudo dd of=/usr/share/keyrings/githubcli-archive-keyring.gpg\necho \"deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/githubcli-archive-keyring.gpg] https://cli.gi","body":"# GitHub CLI (gh)\n\nComprehensive reference for GitHub CLI (gh) - work seamlessly with GitHub from the command line.\n\n**Version:** 2.85.0 (current as of January 2026)\n\n## Prerequisites\n\n### Installation\n\n```bash\n# macOS\nbrew install gh\n\n# Linux\ncurl -fsSL https://cli.github.com/packages/githubcli-archive-keyring.gpg | sudo dd of=/usr/share/keyrings/githubcli-archive-keyring.gpg\necho \"deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/githubcli-archive-keyring.gpg] https://cli.github.com/packages stable main\" | sudo tee /etc/apt/sources.list.d/github-cli.list > /dev/null\nsudo apt update\nsudo apt install gh\n\n# Windows\nwinget install --id GitHub.cli\n\n# Verify installation\ngh --version\n```\n\n### Authentication\n\n```bash\n# Interactive login (default: github.com)\ngh auth login\n\n# Login with specific hostname\ngh auth login --hostname enterprise.internal\n\n# Login with token\ngh auth login --with-token < mytoken.txt\n\n# Check authentication status\ngh auth status\n\n# Switch accounts\ngh auth switch --hostname github.com --user username\n\n# Logout\ngh auth logout --hostname github.com --user username\n```\n\n### Setup Git Integration\n\n```bash\n# Configure git to use gh as credential helper\ngh auth setup-git\n\n# View active token\ngh auth token\n\n# Refresh authentication scopes\ngh auth refresh --scopes write:org,read:public_key\n```\n\n## CLI Structure\n\n```\ngh                          # Root command\n├── auth                    # Authentication\n│   ├── login\n│   ├── logout\n│   ├── refresh\n│   ├── setup-git\n│   ├── status\n│   ├── switch\n│   └── token\n├── browse                  # Open in browser\n├── codespace               # GitHub Codespaces\n│   ├── code\n│   ├── cp\n│   ├── create\n│   ├── delete\n│   ├── edit\n│   ├── jupyter\n│   ├── list\n│   ├── logs\n│   ├── ports\n│   ├── rebuild\n│   ├── ssh\n│   ├── stop\n│   └── view\n├── gist                    # Gists\n│   ├── clone\n│   ├── create\n│   ├── delete\n│   ├── edit\n│   ├── list\n│   ├── rename\n│   └── view\n├── issue                   # Issues\n│   ├── create\n│   ├── list\n│   ├── status\n│   ├── close\n│   ├── comment\n│   ├── delete\n│   ├── develop\n│   ├── edit\n│   ├── lock\n│   ├── pin\n│   ├── reopen\n│   ├── transfer\n│   ├── unlock\n│   └── view\n├── org                     # Organizations\n│   └── list\n├── pr                      # Pull Requests\n│   ├── create\n│   ├── list\n│   ├── status\n│   ├── checkout\n│   ├── checks\n│   ├── close\n│   ├── comment\n│   ├── diff\n│   ├── edit\n│   ├── lock\n│   ├── merge\n│   ├── ready\n│   ├── reopen\n│   ├── revert\n│   ├── review\n│   ├── unlock\n│   ├── update-branch\n│   └── view\n├── project                 # Projects\n│   ├── close\n│   ├── copy\n│   ├── create\n│   ├── delete\n│   ├── edit\n│   ├── field-create\n│   ├── field-delete\n│   ├── field-list\n│   ├── item-add\n│   ├── item-archive\n│   ├── item-create\n│   ├── item-delete\n│   ├── item-edit\n│   ├── item-list\n│   ├── link\n│   ├── list\n│   ├── mark-template\n│   ├── unlink\n│   └── view\n├── release                 # Releases\n│   ├── create\n│   ├── list\n│   ├── delete\n│   ├── delete-asset\n│   ├── download\n│   ├── edit\n│   ├── upload\n│   ├── verify\n│   ├── verify-asset\n│   └── view\n├── repo                    # Repositories\n│   ├── create\n│   ├── list\n│   ├── archive\n│   ├── autolink\n│   ├── clone\n│   ├── delete\n│   ├── deploy-key\n│   ├── edit\n│   ├── fork\n│   ├── gitignore\n│   ├── license\n│   ├── rename\n│   ├── set-default\n│   ├── sync\n│   ├── unarchive\n│   └── view\n├── cache                   # Actions caches\n│   ├── delete\n│   └── list\n├── run                     # Workflow runs\n│   ├── cancel\n│   ├── delete\n│   ├── download\n│   ├── list\n│   ├── rerun\n│   ├── view\n│   └── watch\n├── workflow                # Workflows\n│   ├── disable\n│   ├── enable\n│   ├── list\n│   ├── run\n│   └── view\n├── agent-task              # Agent tasks\n├── alias                   # Command aliases\n│   ├── delete\n│   ├── import\n│   ├── list\n│   └── set\n├── api                     # API requests\n├── attestation             # Artifact attestations\n│   ├── download\n│   ├── trusted-root\n│   └── verify\n├── completion              # Shell completion\n├── config                  # Configuration\n│   ├── clear-cache\n│   ├── get\n│   ├── list\n│   └── set\n├── extension               # Extensions\n│   ├── browse\n│   ├── create\n│   ├── exec\n│   ├── install\n│   ├── list\n│   ├── remove\n│   ├── search\n│   └── upgrade\n├── gpg-key                 # GPG keys\n│   ├── add\n│   ├── delete\n│   └── list\n├── label                   # Labels\n│   ├── clone\n│   ├── create\n│   ├── delete\n│   ├── edit\n│   └── list\n├── preview                 # Preview features\n├── ruleset                 # Rulesets\n│   ├── check\n│   ├── list\n│   └── view\n├── search                  # Search\n│   ├── code\n│   ├── commits\n│   ├── issues\n│   ├── prs\n│   └── repos\n├── secret                  # Secrets\n│   ├── delete\n│   ├── list\n│   └── set\n├── ssh-key                 # SSH keys\n│   ├── add\n│   ├── delete\n│   └── list\n├── status                  # Status overview\n└── variable                # Variables\n    ├── delete\n    ├── get\n    ├── list\n    └── set\n```\n\n## Configuration\n\n### Global Configuration\n\n```bash\n# List all configuration\ngh config list\n\n# Get specific configuration value\ngh config list git_protocol\ngh config get editor\n\n# Set configuration value\ngh config set editor vim\ngh config set git_protocol ssh\ngh config set prompt disabled\ngh config set pager \"less -R\"\n\n# Clear configuration cache\ngh config clear-cache\n```\n\n### Environment Variables\n\n```bash\n# GitHub token (for automation)\nexport GH_TOKEN=ghp_xxxxxxxxxxxx\n\n# GitHub hostname\nexport GH_HOST=github.com\n\n# Disable prompts\nexport GH_PROMPT_DISABLED=true\n\n# Custom editor\nexport GH_EDITOR=vim\n\n# Custom pager\nexport GH_PAGER=less\n\n# HTTP timeout\nexport GH_TIMEOUT=30\n\n# Custom repository (override default)\nexport GH_REPO=owner/repo\n\n# Custom git protocol\nexport GH_ENTERPRISE_HOSTNAME=hostname\n```\n\n## Authentication (gh auth)\n\n### Login\n\n```bash\n# Interactive login\ngh auth login\n\n# Web-based authentication\ngh auth login --web\n\n# With clipboard for OAuth code\ngh auth login --web --clipboard\n\n# With specific git protocol\ngh auth login --git-protocol ssh\n\n# With custom hostname (GitHub Enterprise)\ngh auth login --hostname enterprise.internal\n\n# Login with token from stdin\ngh auth login --with-token < token.txt\n\n# Insecure storage (plain text)\ngh auth login --insecure-storage\n```\n\n### Status\n\n```bash\n# Show all authentication status\ngh auth status\n\n# Show active account only\ngh auth status --active\n\n# Show specific hostname\ngh auth status --hostname github.com\n\n# Show token in output\ngh auth status --show-token\n\n# JSON output\ngh auth status --json hosts\n\n# Filter with jq\ngh auth status --json hosts --jq ''.hosts | add''\n```\n\n### Switch Accounts\n\n```bash\n# Interactive switch\ngh auth switch\n\n# Switch to specific user/host\ngh auth switch --hostname github.com --user monalisa\n```\n\n### Token\n\n```bash\n# Print authentication token\ngh auth token\n\n# Token for specific host/user\ngh auth token --hostname github.com --user monalisa\n```\n\n### Refresh\n\n```bash\n# Refresh credentials\ngh auth refresh\n\n# Add scopes\ngh auth refresh --scopes write:org,read:public_key\n\n# Remove scopes\ngh auth refresh --remove-scopes delete_repo\n\n# Reset to default scopes\ngh auth refresh --reset-scopes\n\n# With clipboard\ngh auth refresh --clipboard\n```\n\n### Setup Git\n\n```bash\n# Setup git credential helper\ngh auth setup-git\n\n# Setup for specific host\ngh auth setup-git --hostname enterprise.internal\n\n# Force setup even if host not known\ngh auth setup-git --hostname enterprise.internal --force\n```\n\n## Browse (gh browse)\n\n```bash\n# Open repository in browser\ngh browse\n\n# Open specific path\ngh browse script/\ngh browse main.go:312\n\n# Open issue or PR\ngh browse 123\n\n# Open commit\ngh browse 77507cd94ccafcf568f8560cfecde965fcfa63\n\n# Open with specific branch\ngh browse main.go --branch bug-fix\n\n# Open different repository\ngh browse --repo owner/repo\n\n# Open specific pages\ngh browse --actions       # Actions tab\ngh browse --projects      # Projects tab\ngh browse --releases      # Releases tab\ngh browse --settings      # Settings page\ngh browse --wiki          # Wiki page\n\n# Print URL instead of opening\ngh browse --no-browser\n```\n\n## Repositories (gh repo)\n\n### Create Repository\n\n```bash\n# Create new repository\ngh repo create my-repo\n\n# Create with description\ngh repo create my-repo --description \"My awesome project\"\n\n# Create public repository\ngh repo create my-repo --public\n\n# Create private repository\ngh repo create my-repo --private\n\n# Create with homepage\ngh repo create my-repo --homepage https://example.com\n\n# Create with license\ngh repo create my-repo --license mit\n\n# Create with gitignore\ngh repo create my-repo --gitignore python\n\n# Initialize as template repository\ngh repo create my-repo --template\n\n# Create repository in organization\ngh repo create org/my-repo\n\n# Create without cloning locally\ngh repo create my-repo --source=.\n\n# Disable issues\ngh repo create my-repo --disable-issues\n\n# Disable wiki\ngh repo create my-repo --disable-wiki\n```\n\n### Clone Repository\n\n```bash\n# Clone repository\ngh repo clone owner/repo\n\n# Clone to specific directory\ngh repo clone owner/repo my-directory\n\n# Clone with different branch\ngh repo clone owner/repo --branch develop\n```\n\n### List Repositories\n\n```bash\n# List all repositories\ngh repo list\n\n# List repositories for owner\ngh repo list owner\n\n# Limit results\ngh repo list --limit 50\n\n# Public repositories only\ngh repo list --public\n\n# Source repositories only (not forks)\ngh repo list --source\n\n# JSON output\ngh repo list --json name,visibility,owner\n\n# Table output\ngh repo list --limit 100 | tail -n +2\n\n# Filter with jq\ngh repo list --json name --jq ''.[].name''\n```\n\n### View Repository\n\n```bash\n# View repository details\ngh repo view\n\n# View specific repository\ngh repo view owner/repo\n\n# JSON output\ngh repo view --json name,description,defaultBranchRef\n\n# View in browser\ngh repo view --web\n```\n\n### Edit Repository\n\n```bash\n# Edit description\ngh repo edit --description \"New description\"\n\n# Set homepage\ngh repo edit --homepage https://example.com\n\n# Change visibility\ngh repo edit --visibility private\ngh repo edit --visibility public\n\n# Enable/disable features\ngh repo edit --enable-issues\ngh repo edit --disable-issues\ngh repo edit --enable-wiki\ngh repo edit --disable-wiki\ngh repo edit --enable-projects\ngh repo edit --disable-projects\n\n# Set default branch\ngh repo edit --default-branch main\n\n# Rename repository\ngh repo rename new-name\n\n# Archive repository\ngh repo archive\ngh repo unarchive\n```\n\n### Delete Repository\n\n```bash\n# Delete repository\ngh repo delete owner/repo\n\n# Confirm without prompt\ngh repo delete owner/repo --yes\n```\n\n### Fork Repository\n\n```bash\n# Fork repository\ngh repo fork owner/repo\n\n# Fork to organization\ngh repo fork owner/repo --org org-name\n\n# Clone after forking\ngh repo fork owner/repo --clone\n\n# Remote name for fork\ngh repo fork owner/repo --remote-name upstream\n```\n\n### Sync Fork\n\n```bash\n# Sync fork with upstream\ngh repo sync\n\n# Sync specific branch\ngh repo sync --branch feature\n\n# Force sync\ngh repo sync --force\n```\n\n### Set Default Repository\n\n```bash\n# Set default repository for current directory\ngh repo set-default\n\n# Set default explicitly\ngh repo set-default owner/repo\n\n# Unset default\ngh repo set-default --unset\n```\n\n### Repository Autolinks\n\n```bash\n# List autolinks\ngh repo autolink list\n\n# Add autolink\ngh repo autolink add \\\n  --key-prefix JIRA- \\\n  --url-template https://jira.example.com/browse/<num>\n\n# Delete autolink\ngh repo autolink delete 12345\n```\n\n### Repository Deploy Keys\n\n```bash\n# List deploy keys\ngh repo deploy-key list\n\n# Add deploy key\ngh repo deploy-key add ~/.ssh/id_rsa.pub \\\n  --title \"Production server\" \\\n  --read-only\n\n# Delete deploy key\ngh repo deploy-key delete 12345\n```\n\n### Gitignore and License\n\n```bash\n# View gitignore template\ngh repo gitignore\n\n# View license template\ngh repo license mit\n\n# License with full name\ngh repo license mit --fullname \"John Doe\"\n```\n\n## Issues (gh issue)\n\n### Create Issue\n\n```bash\n# Create issue interactively\ngh issue create\n\n# Create with title\ngh issue create --title \"Bug: Login not working\"\n\n# Create with title and body\ngh issue create \\\n  --title \"Bug: Login not working\" \\\n  --body \"Steps to reproduce...\"\n\n# Create with body from file\ngh issue create --body-file issue.md\n\n# Create with labels\ngh issue create --title \"Fix bug\" --labels bug,high-priority\n\n# Create with assignees\ngh issue create --title \"Fix bug\" --assignee user1,user2\n\n# Create in specific repository\ngh issue create --repo owner/repo --title \"Issue title\"\n\n# Create issue from web\ngh issue create --web\n```\n\n### List Issues\n\n```bash\n# List all open issues\ngh issue list\n\n# List all issues (including closed)\ngh issue list --state all\n\n# List closed issues\ngh issue list --state closed\n\n# Limit results\ngh issue list --limit 50\n\n# Filter by assignee\ngh issue list --assignee username\ngh issue list --assignee @me\n\n# Filter by labels\ngh issue list --labels bug,enhancement\n\n# Filter by milestone\ngh issue list --milestone \"v1.0\"\n\n# Search/filter\ngh issue list --search \"is:open is:issue label:bug\"\n\n# JSON output\ngh issue list --json number,title,state,author\n\n# Table view\ngh issue list --json number,title,labels --jq ''.[] | [.number, .title, .labels[].name] | @tsv''\n\n# Show comments count\ngh issue list --json number,title,comments --jq ''.[] | [.number, .title, .comments]''\n\n# Sort by\ngh issue list --sort created --order desc\n```\n\n### View Issue\n\n```bash\n# View issue\ngh issue view 123\n\n# View with comments\ngh issue view 123 --comments\n\n# View in browser\ngh issue view 123 --web\n\n# JSON output\ngh issue view 123 --json title,body,state,labels,comments\n\n# View specific fields\ngh issue view 123 --json title --jq ''.title''\n```\n\n### Edit Issue\n\n```bash\n# Edit interactively\ngh issue edit 123\n\n# Edit title\ngh issue edit 123 --title \"New title\"\n\n# Edit body\ngh issue edit 123 --body \"New description\"\n\n# Add labels\ngh issue edit 123 --add-label bug,high-priority\n\n# Remove labels\ngh issue edit 123 --remove-label stale\n\n# Add assignees\ngh issue edit 123 --add-assignee user1,user2\n\n# Remove assignees\ngh issue edit 123 --remove-assignee user1\n\n# Set milestone\ngh issue edit 123 --milestone \"v1.0\"\n```\n\n### Close/Reopen Issue\n\n```bash\n# Close issue\ngh issue close 123\n\n# Close with comment\ngh issue close 123 --comment \"Fixed in PR #456\"\n\n# Reopen issue\ngh issue reopen 123\n```\n\n### Comment on Issue\n\n```bash\n# Add comment\ngh issue comment 123 --body \"This looks good!\"\n\n# Edit comment\ngh issue comment 123 --edit 456789 --body \"Updated comment\"\n\n# Delete comment\ngh issue comment 123 --delete 456789\n```\n\n### Issue Status\n\n```bash\n# Show issue status summary\ngh issue status\n\n# Status for specific repository\ngh issue status --repo owner/repo\n```\n\n### Pin/Unpin Issues\n\n```bash\n# Pin issue (pinned to repo dashboard)\ngh issue pin 123\n\n# Unpin issue\ngh issue unpin 123\n```\n\n### Lock/Unlock Issue\n\n```bash\n# Lock conversation\ngh issue lock 123\n\n# Lock with reason\ngh issue lock 123 --reason off-topic\n\n# Unlock\ngh issue unlock 123\n```\n\n### Transfer Issue\n\n```bash\n# Transfer to another repository\ngh issue transfer 123 --repo owner/new-repo\n```\n\n### Delete Issue\n\n```bash\n# Delete issue\ngh issue delete 123\n\n# Confirm without prompt\ngh issue delete 123 --yes\n```\n\n### Develop Issue (Draft PR)\n\n```bash\n# Create draft PR from issue\ngh issue develop 123\n\n# Create in specific branch\ngh issue develop 123 --branch fix/issue-123\n\n# Create with base branch\ngh issue develop 123 --base main\n```\n\n## Pull Requests (gh pr)\n\n### Create Pull Request\n\n```bash\n# Create PR interactively\ngh pr create\n\n# Create with title\ngh pr create --title \"Feature: Add new functionality\"\n\n# Create with title and body\ngh pr create \\\n  --title \"Feature: Add new functionality\" \\\n  --body \"This PR adds...\"\n\n# Fill body from template\ngh pr create --body-file .github/PULL_REQUEST_TEMPLATE.md\n\n# Set base branch\ngh pr create --base main\n\n# Set head branch (default: current branch)\ngh pr create --head feature-branch\n\n# Create draft PR\ngh pr create --draft\n\n# Add assignees\ngh pr create --assignee user1,user2\n\n# Add reviewers\ngh pr create --reviewer user1,user2\n\n# Add labels\ngh pr create --labels enhancement,feature\n\n# Link to issue\ngh pr create --issue 123\n\n# Create in specific repository\ngh pr create --repo owner/repo\n\n# Open in browser after creation\ngh pr create --web\n```\n\n### List Pull Requests\n\n```bash\n# List open PRs\ngh pr list\n\n# List all PRs\ngh pr list --state all\n\n# List merged PRs\ngh pr list --state merged\n\n# List closed (not merged) PRs\ngh pr list --state closed\n\n# Filter by head branch\ngh pr list --head feature-branch\n\n# Filter by base branch\ngh pr list --base main\n\n# Filter by author\ngh pr list --author username\ngh pr list --author @me\n\n# Filter by assignee\ngh pr list --assignee username\n\n# Filter by labels\ngh pr list --labels bug,enhancement\n\n# Limit results\ngh pr list --limit 50\n\n# Search\ngh pr list --search \"is:open is:pr label:review-required\"\n\n# JSON output\ngh pr list --json number,title,state,author,headRefName\n\n# Show check status\ngh pr list --json number,title,statusCheckRollup --jq ''.[] | [.number, .title, .statusCheckRollup[]?.status]''\n\n# Sort by\ngh pr list --sort created --order desc\n```\n\n### View Pull Request\n\n```bash\n# View PR\ngh pr view 123\n\n# View with comments\ngh pr view 123 --comments\n\n# View in browser\ngh pr view 123 --web\n\n# JSON output\ngh pr view 123 --json title,body,state,author,commits,files\n\n# View diff\ngh pr view 123 --json files --jq ''.files[].path''\n\n# View with jq query\ngh pr view 123 --json title,state --jq ''\"\\(.title): \\(.state)\"''\n```\n\n### Checkout Pull Request\n\n```bash\n# Checkout PR branch\ngh pr checkout 123\n\n# Checkout with specific branch name\ngh pr checkout 123 --branch name-123\n\n# Force checkout\ngh pr checkout 123 --force\n```\n\n### Diff Pull Request\n\n```bash\n# View PR diff\ngh pr diff 123\n\n# View diff with color\ngh pr diff 123 --color always\n\n# Output to file\ngh pr diff 123 > pr-123.patch\n\n# View diff of specific files\ngh pr diff 123 --name-only\n```\n\n### Merge Pull Request\n\n```bash\n# Merge PR\ngh pr merge 123\n\n# Merge with specific method\ngh pr merge 123 --merge\ngh pr merge 123 --squash\ngh pr merge 123 --rebase\n\n# Delete branch after merge\ngh pr merge 123 --delete-branch\n\n# Merge with comment\ngh pr merge 123 --subject \"Merge PR #123\" --body \"Merging feature\"\n\n# Merge draft PR\ngh pr merge 123 --admin\n\n# Force merge (skip checks)\ngh pr merge 123 --admin\n```\n\n### Close Pull Request\n\n```bash\n# Close PR (as draft, not merge)\ngh pr close 123\n\n# Close with comment\ngh pr close 123 --comment \"Closing due to...\"\n```\n\n### Reopen Pull Request\n\n```bash\n# Reopen closed PR\ngh pr reopen 123\n```\n\n### Edit Pull Request\n\n```bash\n# Edit interactively\ngh pr edit 123\n\n# Edit title\ngh pr edit 123 --title \"New title\"\n\n# Edit body\ngh pr edit 123 --body \"New description\"\n\n# Add labels\ngh pr edit 123 --add-label bug,enhancement\n\n# Remove labels\ngh pr edit 123 --remove-label stale\n\n# Add assignees\ngh pr edit 123 --add-assignee user1,user2\n\n# Remove assignees\ngh pr edit 123 --remove-assignee user1\n\n# Add reviewers\ngh pr edit 123 --add-reviewer user1,user2\n\n# Remove reviewers\ngh pr edit 123 --remove-reviewer user1\n\n# Mark as ready for review\ngh pr edit 123 --ready\n```\n\n### Ready for Review\n\n```bash\n# Mark draft PR as ready\ngh pr ready 123\n```\n\n### Pull Request Checks\n\n```bash\n# View PR checks\ngh pr checks 123\n\n# Watch checks in real-time\ngh pr checks 123 --watch\n\n# Watch interval (seconds)\ngh pr checks 123 --watch --interval 5\n```\n\n### Comment on Pull Request\n\n```bash\n# Add comment\ngh pr comment 123 --body \"Looks good!\"\n\n# Comment on specific line\ngh pr comment 123 --body \"Fix this\" \\\n  --repo owner/repo \\\n  --head-owner owner --head-branch feature\n\n# Edit comment\ngh pr comment 123 --edit 456789 --body \"Updated\"\n\n# Delete comment\ngh pr comment 123 --delete 456789\n```\n\n### Review Pull Request\n\n```bash\n# Review PR (opens editor)\ngh pr review 123\n\n# Approve PR\ngh pr review 123 --approve\n\n--approve-body \"LGTM!\"\n\n# Request changes\ngh pr review 123 --request-changes \\\n  --body \"Please fix these issues\"\n\n# Comment on PR\ngh pr review 123 --comment --body \"Some thoughts...\"\n\n# Dismiss review\ngh pr review 123 --dismiss\n```\n\n### Update Branch\n\n```bash\n# Update PR branch with latest base branch\ngh pr update-branch 123\n\n# Force update\ngh pr update-branch 123 --force\n\n# Use merge strategy\ngh pr update-branch 123 --merge\n```\n\n### Lock/Unlock Pull Request\n\n```bash\n# Lock PR conversation\ngh pr lock 123\n\n# Lock with reason\ngh pr lock 123 --reason off-topic\n\n# Unlock\ngh pr unlock 123\n```\n\n### Revert Pull Request\n\n```bash\n# Revert merged PR\ngh pr revert 123\n\n# Revert with specific branch name\ngh pr revert 123 --branch revert-pr-123\n```\n\n### Pull Request Status\n\n```bash\n# Show PR status summary\ngh pr status\n\n# Status for specific repository\ngh pr status --repo owner/repo\n```\n\n## GitHub Actions\n\n### Workflow Runs (gh run)\n\n```bash\n# List workflow runs\ngh run list\n\n# List for specific workflow\ngh run list --workflow \"ci.yml\"\n\n# List for specific branch\ngh run list --branch main\n\n# Limit results\ngh run list --limit 20\n\n# JSON output\ngh run list --json databaseId,status,conclusion,headBranch\n\n# View run details\ngh run view 123456789\n\n# View run with verbose logs\ngh run view 123456789 --log\n\n# View specific job\ngh run view 123456789 --job 987654321\n\n# View in browser\ngh run view 123456789 --web\n\n# Watch run in real-time\ngh run watch 123456789\n\n# Watch with interval\ngh run watch 123456789 --interval 5\n\n# Rerun failed run\ngh run rerun 123456789\n\n# Rerun specific job\ngh run rerun 123456789 --job 987654321\n\n# Cancel run\ngh run cancel 123456789\n\n# Delete run\ngh run delete 123456789\n\n# Download run artifacts\ngh run download 123456789\n\n# Download specific artifact\ngh run download 123456789 --name build\n\n# Download to directory\ngh run download 123456789 --dir ./artifacts\n```\n\n### Workflows (gh workflow)\n\n```bash\n# List workflows\ngh workflow list\n\n# View workflow details\ngh workflow view ci.yml\n\n# View workflow YAML\ngh workflow view ci.yml --yaml\n\n# View in browser\ngh workflow view ci.yml --web\n\n# Enable workflow\ngh workflow enable ci.yml\n\n# Disable workflow\ngh workflow disable ci.yml\n\n# Run workflow manually\ngh workflow run ci.yml\n\n# Run with inputs\ngh workflow run ci.yml \\\n  --raw-field \\\n  version=\"1.0.0\" \\\n  environment=\"production\"\n\n# Run from specific branch\ngh workflow run ci.yml --ref develop\n```\n\n### Action Caches (gh cache)\n\n```bash\n# List caches\ngh cache list\n\n# List for specific branch\ngh cache list --branch main\n\n# List with limit\ngh cache list --limit 50\n\n# Delete cache\ngh cache delete 123456789\n\n# Delete all caches\ngh cache delete --all\n```\n\n### Action Secrets (gh secret)\n\n```bash\n# List secrets\ngh secret list\n\n# Set secret (prompts for value)\ngh secret set MY_SECRET\n\n# Set secret from environment\necho \"$MY_SECRET\" | gh secret set MY_SECRET\n\n# Set secret for specific environment\ngh secret set MY_SECRET --env production\n\n# Set secret for organization\ngh secret set MY_SECRET --org orgname\n\n# Delete secret\ngh secret delete MY_SECRET\n\n# Delete from environment\ngh secret delete MY_SECRET --env production\n```\n\n### Action Variables (gh variable)\n\n```bash\n# List variables\ngh variable list\n\n# Set variable\ngh variable set MY_VAR \"some-value\"\n\n# Set variable for environment\ngh variable set MY_VAR \"value\" --env production\n\n# Set variable for organization\ngh variable set MY_VAR \"value\" --org orgname\n\n# Get variable value\ngh variable get MY_VAR\n\n# Delete variable\ngh variable delete MY_VAR\n\n# Delete from environment\ngh variable delete MY_VAR --env production\n```\n\n## Projects (gh project)\n\n```bash\n# List projects\ngh project list\n\n# List for owner\ngh project list --owner owner\n\n# Open projects\ngh project list --open\n\n# View project\ngh project view 123\n\n# View project items\ngh project view 123 --format json\n\n# Create project\ngh project create --title \"My Project\"\n\n# Create in organization\ngh project create --title \"Project\" --org orgname\n\n# Create with readme\ngh project create --title \"Project\" --readme \"Description here\"\n\n# Edit project\ngh project edit 123 --title \"New Title\"\n\n# Delete project\ngh project delete 123\n\n# Close project\ngh project close 123\n\n# Copy project\ngh project copy 123 --owner target-owner --title \"Copy\"\n\n# Mark template\ngh project mark-template 123\n\n# List fields\ngh project field-list 123\n\n# Create field\ngh project field-create 123 --title \"Status\" --datatype single_select\n\n# Delete field\ngh project field-delete 123 --id 456\n\n# List items\ngh project item-list 123\n\n# Create item\ngh project item-create 123 --title \"New item\"\n\n# Add item to project\ngh project item-add 123 --owner-owner --repo repo --issue 456\n\n# Edit item\ngh project item-edit 123 --id 456 --title \"Updated title\"\n\n# Delete item\ngh project item-delete 123 --id 456\n\n# Archive item\ngh project item-archive 123 --id 456\n\n# Link items\ngh project link 123 --id 456 --link-id 789\n\n# Unlink items\ngh project unlink 123 --id 456 --link-id 789\n\n# View project in browser\ngh project view 123 --web\n```\n\n## Releases (gh release)\n\n```bash\n# List releases\ngh release list\n\n# View latest release\ngh release view\n\n# View specific release\ngh release view v1.0.0\n\n# View in browser\ngh release view v1.0.0 --web\n\n# Create release\ngh release create v1.0.0 \\\n  --notes \"Release notes here\"\n\n# Create release with notes from file\ngh release create v1.0.0 --notes-file notes.md\n\n# Create release with target\ngh release create v1.0.0 --target main\n\n# Create release as draft\ngh release create v1.0.0 --draft\n\n# Create pre-release\ngh release create v1.0.0 --prerelease\n\n# Create release with title\ngh release create v1.0.0 --title \"Version 1.0.0\"\n\n# Upload asset to release\ngh release upload v1.0.0 ./file.tar.gz\n\n# Upload multiple assets\ngh release upload v1.0.0 ./file1.tar.gz ./file2.tar.gz\n\n# Upload with label (casing sensitive)\ngh release upload v1.0.0 ./file.tar.gz --casing\n\n# Delete release\ngh release delete v1.0.0\n\n# Delete with cleanup tag\ngh release delete v1.0.0 --yes\n\n# Delete specific asset\ngh release delete-asset v1.0.0 file.tar.gz\n\n# Download release assets\ngh release download v1.0.0\n\n# Download specific asset\ngh release download v1.0.0 --pattern \"*.tar.gz\"\n\n# Download to directory\ngh release download v1.0.0 --dir ./downloads\n\n# Download archive (zip/tar)\ngh release download v1.0.0 --archive zip\n\n# Edit release\ngh release edit v1.0.0 --notes \"Updated notes\"\n\n# Verify release signature\ngh release verify v1.0.0\n\n# Verify specific asset\ngh release verify-asset v1.0.0 file.tar.gz\n```\n\n## Gists (gh gist)\n\n```bash\n# List gists\ngh gist list\n\n# List all gists (including private)\ngh gist list --public\n\n# Limit results\ngh gist list --limit 20\n\n# View gist\ngh gist view abc123\n\n# View gist files\ngh gist view abc123 --files\n\n# Create gist\ngh gist create script.py\n\n# Create gist with description\ngh gist create script.py --desc \"My script\"\n\n# Create public gist\ngh gist create script.py --public\n\n# Create multi-file gist\ngh gist create file1.py file2.py\n\n# Create from stdin\necho \"print(''hello'')\" | gh gist create\n\n# Edit gist\ngh gist edit abc123\n\n# Delete gist\ngh gist delete abc123\n\n# Rename gist file\ngh gist rename abc123 --filename old.py new.py\n\n# Clone gist\ngh gist clone abc123\n\n# Clone to directory\ngh gist clone abc123 my-directory\n```\n\n## Codespaces (gh codespace)\n\n```bash\n# List codespaces\ngh codespace list\n\n# Create codespace\ngh codespace create\n\n# Create with specific repository\ngh codespace create --repo owner/repo\n\n# Create with branch\ngh codespace create --branch develop\n\n# Create with specific machine\ngh codespace create --machine premiumLinux\n\n# View codespace details\ngh codespace view\n\n# SSH into codespace\ngh codespace ssh\n\n# SSH with specific command\ngh codespace ssh --command \"cd /workspaces && ls\"\n\n# Open codespace in browser\ngh codespace code\n\n# Open in VS Code\ngh codespace code --codec\n\n# Open with specific path\ngh codespace code --path /workspaces/repo\n\n# Stop codespace\ngh codespace stop\n\n# Delete codespace\ngh codespace delete\n\n# View logs\ngh codespace logs\n\n--tail 100\n\n# View ports\ngh codespace ports\n\n# Forward port\ngh codespace cp 8080:8080\n\n# Rebuild codespace\ngh codespace rebuild\n\n# Edit codespace\ngh codespace edit --machine standardLinux\n\n# Jupyter support\ngh codespace jupyter\n\n# Copy files to/from codespace\ngh codespace cp file.txt :/workspaces/file.txt\ngh codespace cp :/workspaces/file.txt ./file.txt\n```\n\n## Organizations (gh org)\n\n```bash\n# List organizations\ngh org list\n\n# List for user\ngh org list --user username\n\n# JSON output\ngh org list --json login,name,description\n\n# View organization\ngh org view orgname\n\n# View organization members\ngh org view orgname --json members --jq ''.members[] | .login''\n```\n\n## Search (gh search)\n\n```bash\n# Search code\ngh search code \"TODO\"\n\n# Search in specific repository\ngh search code \"TODO\" --repo owner/repo\n\n# Search commits\ngh search commits \"fix bug\"\n\n# Search issues\ngh search issues \"label:bug state:open\"\n\n# Search PRs\ngh search prs \"is:open is:pr review:required\"\n\n# Search repositories\ngh search repos \"stars:>1000 language:python\"\n\n# Limit results\ngh search repos \"topic:api\" --limit 50\n\n# JSON output\ngh search repos \"stars:>100\" --json name,description,stargazers\n\n# Order results\ngh search repos \"language:rust\" --order desc --sort stars\n\n# Search with extensions\ngh search code \"import\" --extension py\n\n# Web search (open in browser)\ngh search prs \"is:open\" --web\n```\n\n## Labels (gh label)\n\n```bash\n# List labels\ngh label list\n\n# Create label\ngh label create bug --color \"d73a4a\" --description \"Something isn''t working\"\n\n# Create with hex color\ngh label create enhancement --color \"#a2eeef\"\n\n# Edit label\ngh label edit bug --name \"bug-report\" --color \"ff0000\"\n\n# Delete label\ngh label delete bug\n\n# Clone labels from repository\ngh label clone owner/repo\n\n# Clone to specific repository\ngh label clone owner/repo --repo target/repo\n```\n\n## SSH Keys (gh ssh-key)\n\n```bash\n# List SSH keys\ngh ssh-key list\n\n# Add SSH key\ngh ssh-key add ~/.ssh/id_rsa.pub --title \"My laptop\"\n\n# Add key with type\ngh ssh-key add ~/.ssh/id_ed25519.pub --type \"authentication\"\n\n# Delete SSH key\ngh ssh-key delete 12345\n\n# Delete by title\ngh ssh-key delete --title \"My laptop\"\n```\n\n## GPG Keys (gh gpg-key)\n\n```bash\n# List GPG keys\ngh gpg-key list\n\n# Add GPG key\ngh gpg-key add ~/.ssh/id_rsa.pub\n\n# Delete GPG key\ngh gpg-key delete 12345\n\n# Delete by key ID\ngh gpg-key delete ABCD1234\n```\n\n## Status (gh status)\n\n```bash\n# Show status overview\ngh status\n\n# Status for specific repositories\ngh status --repo owner/repo\n\n# JSON output\ngh status --json\n```\n\n## Configuration (gh config)\n\n```bash\n# List all config\ngh config list\n\n# Get specific value\ngh config get editor\n\n# Set value\ngh config set editor vim\n\n# Set git protocol\ngh config set git_protocol ssh\n\n# Clear cache\ngh config clear-cache\n\n# Set prompt behavior\ngh config set prompt disabled\ngh config set prompt enabled\n```\n\n## Extensions (gh extension)\n\n```bash\n# List installed extensions\ngh extension list\n\n# Search extensions\ngh extension search github\n\n# Install extension\ngh extension install owner/extension-repo\n\n# Install from branch\ngh extension install owner/extension-repo --branch develop\n\n# Upgrade extension\ngh extension upgrade extension-name\n\n# Remove extension\ngh extension remove extension-name\n\n# Create new extension\ngh extension create my-extension\n\n# Browse extensions\ngh extension browse\n\n# Execute extension command\ngh extension exec my-extension --arg value\n```\n\n## Aliases (gh alias)\n\n```bash\n# List aliases\ngh alias list\n\n# Set alias\ngh alias set prview ''pr view --web''\n\n# Set shell alias\ngh alias set co ''pr checkout'' --shell\n\n# Delete alias\ngh alias delete prview\n\n# Import aliases\ngh alias import ./aliases.sh\n```\n\n## API Requests (gh api)\n\n```bash\n# Make API request\ngh api /user\n\n# Request with method\ngh api --method POST /repos/owner/repo/issues \\\n  --field title=\"Issue title\" \\\n  --field body=\"Issue body\"\n\n# Request with headers\ngh api /user \\\n  --header \"Accept: application/vnd.github.v3+json\"\n\n# Request with pagination\ngh api /user/repos --paginate\n\n# Raw output (no formatting)\ngh api /user --raw\n\n# Include headers in output\ngh api /user --include\n\n# Silent mode (no progress output)\ngh api /user --silent\n\n# Input from file\ngh api --input request.json\n\n# jq query on response\ngh api /user --jq ''.login''\n\n# Field from response\ngh api /repos/owner/repo --jq ''.stargazers_count''\n\n# GitHub Enterprise\ngh api /user --hostname enterprise.internal\n\n# GraphQL query\ngh api graphql \\\n  -f query=''\n  {\n    viewer {\n      login\n      repositories(first: 5) {\n        nodes {\n          name\n        }\n      }\n    }\n  }''\n```\n\n## Rulesets (gh ruleset)\n\n```bash\n# List rulesets\ngh ruleset list\n\n# View ruleset\ngh ruleset view 123\n\n# Check ruleset\ngh ruleset check --branch feature\n\n# Check specific repository\ngh ruleset check --repo owner/repo --branch main\n```\n\n## Attestations (gh attestation)\n\n```bash\n# Download attestation\ngh attestation download owner/repo \\\n  --artifact-id 123456\n\n# Verify attestation\ngh attestation verify owner/repo\n\n# Get trusted root\ngh attestation trusted-root\n```\n\n## Completion (gh completion)\n\n```bash\n# Generate shell completion\ngh completion -s bash > ~/.gh-complete.bash\ngh completion -s zsh > ~/.gh-complete.zsh\ngh completion -s fish > ~/.gh-complete.fish\ngh completion -s powershell > ~/.gh-complete.ps1\n\n# Shell-specific instructions\ngh completion --shell=bash\ngh completion --shell=zsh\n```\n\n## Preview (gh preview)\n\n```bash\n# List preview features\ngh preview\n\n# Run preview script\ngh preview prompter\n```\n\n## Agent Tasks (gh agent-task)\n\n```bash\n# List agent tasks\ngh agent-task list\n\n# View agent task\ngh agent-task view 123\n\n# Create agent task\ngh agent-task create --description \"My task\"\n```\n\n## Global Flags\n\n| Flag                       | Description                            |\n| -------------------------- | -------------------------------------- |\n| `--help` / `-h`            | Show help for command                  |\n| `--version`                | Show gh version                        |\n| `--repo [HOST/]OWNER/REPO` | Select another repository              |\n| `--hostname HOST`          | GitHub hostname                        |\n| `--jq EXPRESSION`          | Filter JSON output                     |\n| `--json FIELDS`            | Output JSON with specified fields      |\n| `--template STRING`        | Format JSON using Go template          |\n| `--web`                    | Open in browser                        |\n| `--paginate`               | Make additional API calls              |\n| `--verbose`                | Show verbose output                    |\n| `--debug`                  | Show debug output                      |\n| `--timeout SECONDS`        | Maximum API request duration           |\n| `--cache CACHE`            | Cache control (default, force, bypass) |\n\n## Output Formatting\n\n### JSON Output\n\n```bash\n# Basic JSON\ngh repo view --json name,description\n\n# Nested fields\ngh repo view --json owner,name --jq ''.owner.login + \"/\" + .name''\n\n# Array operations\ngh pr list --json number,title --jq ''.[] | select(.number > 100)''\n\n# Complex queries\ngh issue list --json number,title,labels \\\n  --jq ''.[] | {number, title: .title, tags: [.labels[].name]}''\n```\n\n### Template Output\n\n```bash\n# Custom template\ngh repo view \\\n  --template ''{{.name}}: {{.description}}''\n\n# Multiline template\ngh pr view 123 \\\n  --template ''Title: {{.title}}\nAuthor: {{.author.login}}\nState: {{.state}}\n''\n```\n\n## Common Workflows\n\n### Create PR from Issue\n\n```bash\n# Create branch from issue\ngh issue develop 123 --branch feature/issue-123\n\n# Make changes, commit, push\ngit add .\ngit commit -m \"Fix issue #123\"\ngit push\n\n# Create PR linking to issue\ngh pr create --title \"Fix #123\" --body \"Closes #123\"\n```\n\n### Bulk Operations\n\n```bash\n# Close multiple issues\ngh issue list --search \"label:stale\" \\\n  --json number \\\n  --jq ''.[].number'' | \\\n  xargs -I {} gh issue close {} --comment \"Closing as stale\"\n\n# Add label to multiple PRs\ngh pr list --search \"review:required\" \\\n  --json number \\\n  --jq ''.[].number'' | \\\n  xargs -I {} gh pr edit {} --add-label needs-review\n```\n\n### Repository Setup Workflow\n\n```bash\n# Create repository with initial setup\ngh repo create my-project --public \\\n  --description \"My awesome project\" \\\n  --clone \\\n  --gitignore python \\\n  --license mit\n\ncd my-project\n\n# Set up branches\ngit checkout -b develop\ngit push -u origin develop\n\n# Create labels\ngh label create bug --color \"d73a4a\" --description \"Bug report\"\ngh label create enhancement --color \"a2eeef\" --description \"Feature request\"\ngh label create documentation --color \"0075ca\" --description \"Documentation\"\n```\n\n### CI/CD Workflow\n\n```bash\n# Run workflow and wait\nRUN_ID=$(gh workflow run ci.yml --ref main --jq ''.databaseId'')\n\n# Watch the run\ngh run watch \"$RUN_ID\"\n\n# Download artifacts on completion\ngh run download \"$RUN_ID\" --dir ./artifacts\n```\n\n### Fork Sync Workflow\n\n```bash\n# Fork repository\ngh repo fork original/repo --clone\n\ncd repo\n\n# Add upstream remote\ngit remote add upstream https://github.com/original/repo.git\n\n# Sync fork\ngh repo sync\n\n# Or manual sync\ngit fetch upstream\ngit checkout main\ngit merge upstream/main\ngit push origin main\n```\n\n## Environment Setup\n\n### Shell Integration\n\n```bash\n# Add to ~/.bashrc or ~/.zshrc\neval \"$(gh completion -s bash)\"  # or zsh/fish\n\n# Create useful aliases\nalias gs=''gh status''\nalias gpr=''gh pr view --web''\nalias gir=''gh issue view --web''\nalias gco=''gh pr checkout''\n```\n\n### Git Configuration\n\n```bash\n# Use gh as credential helper\ngh auth setup-git\n\n# Set gh as default for repo operations\ngit config --global credential.helper ''gh !gh auth setup-git''\n\n# Or manually\ngit config --global credential.helper github\n```\n\n## Best Practices\n\n1. **Authentication**: Use environment variables for automation\n\n   ```bash\n   export GH_TOKEN=$(gh auth token)\n   ```\n\n2. **Default Repository**: Set default to avoid repetition\n\n   ```bash\n   gh repo set-default owner/repo\n   ```\n\n3. **JSON Parsing**: Use jq for complex data extraction\n\n   ```bash\n   gh pr list --json number,title --jq ''.[] | select(.title | contains(\"fix\"))''\n   ```\n\n4. **Pagination**: Use --paginate for large result sets\n\n   ```bash\n   gh issue list --state all --paginate\n   ```\n\n5. **Caching**: Use cache control for frequently accessed data\n   ```bash\n   gh api /user --cache force\n   ```\n\n## Getting Help\n\n```bash\n# General help\ngh --help\n\n# Command help\ngh pr --help\ngh issue create --help\n\n# Help topics\ngh help formatting\ngh help environment\ngh help exit-codes\ngh help accessibility\n```\n\n## References\n\n- Official Manual: https://cli.github.com/manual/\n- GitHub Docs: https://docs.github.com/en/github-cli\n- REST API: https://docs.github.com/en/rest\n- GraphQL API: https://docs.github.com/en/graphql\n"},"lastSynced":"2026-02-20T04:21:54.483Z","agentAnalysis":{"suitability":{"en":"Perfect for Azure Infrastructure Agents needing streamlined GitHub CLI workflow automation.","zh":"非常适合需要简化 GitHub CLI 工作流自动化的 Azure 基础设施代理。","ja":"Azure インフラストラクチャ エージェントが GitHub CLI ワークフロー自動化を簡素化する必要がある場合に最適です。","ko":"GitHub CLI 워크플ロー 자동화를 단순화해야 하는 Azure 인프라 에이전트에 적합합니다.","es":"Perfecto para Agentes de Infraestructura de Azure que necesitan una automatización de flujo de trabajo de GitHub CLI optimizada.","fr":"Parfait pour les Agents d''Infrastructure Azure ayant besoin d''une automation de flux de travail GitHub CLI simplifiée.","de":"Perfekt für Azure-Infrastrukturagenten, die eine optimierte Automatisierung des GitHub-CLI-Workflows benötigen.","pt":"Perfeito para Agentes de Infraestrutura do Azure que precisam de automação de fluxo de trabalho de CLI do GitHub simplificado.","ru":"Идеально подходит для агентов инфраструктуры Azure, которым требуется упрощенная автоматизация рабочего процесса GitHub CLI.","ar":"مثالي لعميل Azure البنية تحتاج إلى تسهيل تدفق عمل GitHub CLI"},"recommendation":{"en":"Empowers agents to seamlessly interact with GitHub from the command line, utilizing version 2.85.0 of the GitHub CLI, and leveraging custom Copilot agents like architect, bicep-plan, and bicep-implement, while auto-syncing from the main repository.","zh":"赋予代理从命令行无缝地与 GitHub 交互的能力，利用 2.85.0 版本的 GitHub CLI，并利用自定义的 Copilot 代理，如架构师、bicep-plan 和 bicep-implement，同时从主存储库自动同步。","ja":"エージェントがコマンドラインから GitHub とシームレスにやり取りできるようにし、GitHub CLI のバージョン 2.85.0 を利用し、カスタムの Copilot エージェント (アーキテクト、bicep-plan、bicep-implement など) を利用し、メイン リポジトリから自動同期します。","ko":"에이전트가 명령줄에서 GitHub와 무중단으로 상호 작용할 수 있도록 하며 GitHub CLI 버전 2.85.0을 사용하고 아키텍트, bicep-plan 및 bicep-implement와 같은 사용자 지정 Copilot 에이전트를 활용하며 메인 리포지토리에서 자동으로 동기화합니다.","es":"Habilita a los agentes a interactuar de forma transparente con GitHub desde la línea de comandos, utilizando la versión 2.85.0 de la GitHub CLI, y aprovechando agentes personalizados de Copilot como architect, bicep-plan y bicep-implement, mientras se sincroniza automáticamente desde el repositorio principal.","fr":"Permet aux agents d''interagir en toute transparence avec GitHub depuis la ligne de commande, en utilisant la version 2.85.0 de la GitHub CLI, et en exploitant des agents Copilot personnalisés tels que architect, bicep-plan et bicep-implement, tout en synchronisant automatiquement depuis le référentiel principal.","de":"Ermöglicht es den Agenten, nahtlos mit GitHub über die Befehlszeile zu interagieren, indem sie die Version 2.85.0 der GitHub-CLI verwenden und benutzerdefinierte Copilot-Agenten wie Architect, Bicep-Plan und Bicep-Implement nutzen, während sie automatisch aus dem Hauptrepository synchronisieren.","pt":"Habilita os agentes a interagir sem problemas com o GitHub a partir da linha de comando, utilizando a versão 2.85.0 da CLI do GitHub e aproveitando agentes Copilot personalizados como arquiteto, bicep-plan e bicep-implement, ao mesmo tempo em que sincroniza automaticamente do repositório principal.","ru":"Предоставляет агентам возможность бесшовного взаимодействия с GitHub из командной строки, используя версию 2.85.0 GitHub CLI и используя пользовательских агентов Copilot, таких как архитектор, bicep-plan и bicep-implement, при этом автоматически синхронизируясь с основным репозиторием.","ar":"يمكن للعميل التفاعل بسلاسة مع GitHub من سطر الأوامر، مع استخدام الإصدار 2.85.0 من GitHub CLI وتحقيق عميل Copilot المخصص مثل المعماري، bicep-plan و bicep-implement، مع 同步 تلقائي من المستودع الرئيسي"},"useCases":{"en":["Automating Azure infrastructure development with custom Copilot agents","Implementing the 7-step workflow for efficient infrastructure management","Utilizing the Azure Pricing MCP server for cost optimization"],"zh":["使用自定义 Copilot 代理自动化 Azure 基础设施开发","实施 7 步工作流以实现高效的基础设施管理","利用 Azure Pricing MCP 服务器进行成本优化"],"ja":["カスタム Copilot エージェントを使用して Azure インフラストラクチャ開発を自動化する","効率的なインフラストラクチャ管理のための 7 ステップ ワークフローを実施する","Azure Pricing MCP サーバーを使用してコスト最適化を行う"],"ko":["사용자 지정 Copilot 에이전트를 사용하여 Azure 인프라 개발을 자동화하는 것","효율적인 인프라 관리를 위한 7단계 워크플로우를 구현하는 것","Azure Pricing MCP 서버를 사용하여 비용 최적화를 수행하는 것"],"es":["Automatización del desarrollo de infraestructura de Azure con agentes personalizados de Copilot","Implementación del flujo de trabajo de 7 pasos para una gestión de infraestructura eficiente","Uso del servidor de precios de Azure MCP para la optimización de costos"],"fr":["Automatisation du développement d''infrastructure Azure avec des agents Copilot personnalisés","Mise en œuvre du flux de travail en 7 étapes pour une gestion d''infrastructure efficace","Utilisation du serveur de tarification Azure MCP pour l''optimisation des coûts"],"de":["Automatisierung der Azure-Infrastruktur-Entwicklung mit benutzerdefinierten Copilot-Agents","Implementierung des 7-Schritt-Workflows für eine effiziente Infrastrukturverwaltung","Verwendung des Azure-Preis-MCP-Servers für die Kostenerfassung"],"pt":["Automatizar o desenvolvimento de infraestrutura do Azure com agentes Copilot personalizados","Implementar o fluxo de trabalho de 7 etapas para gerenciamento de infraestrutura eficiente","Utilizar o servidor de preços do Azure MCP para otimização de custos"],"ru":["Автоматизировать разработку инфраструктуры Azure с помощью пользовательских агентов Copilot","Реализовать 7-шаговый рабочий процесс для эффективного управления инфраструктурой","Использовать сервер цен Azure MCP для оптимизации затрат"],"ar":["توفير تلقائي لتطوير البنية التحتية لآزور مع عميل Copilot المخصص","تنفيذ تدفق عمل 7 خطوات لإدارة البنية التحتية الفعّالة","استخدام خادم تسعير Azure MCP لتحسين التكلفة"]},"limitations":{"en":["Requires installation via brew on macOS or curl on Linux","Limited to GitHub CLI version 2.85.0 as of January 2026"],"zh":["需要在 macOS 上通过 brew 或在 Linux 上通过 curl 进行安装","仅限于 2026 年 1 月份的 GitHub CLI 版本 2.85.0"],"ja":["macOS では brew、Linux では curl を使用してインストールする必要がある","2026 年 1 月時点での GitHub CLI バージョン 2.85.0 までの対応"],"ko":["macOS에서는 brew를 통해, 리눅스에서는 curl을 통해 설치해야 함","2026년 1월 현재 GitHub CLI 버전 2.85.0까지 지원"],"es":["Requiere instalación a través de brew en macOS o curl en Linux","Limitado a la versión 2.85.0 de la GitHub CLI a partir de enero de 2026"],"fr":["Nécessite une installation via brew sur macOS ou curl sur Linux","Limité à la version 2.85.0 de la GitHub CLI à compter de janvier 2026"],"de":["Erfordert Installation über brew auf macOS oder curl auf Linux","Begrenzt auf Version 2.85.0 der GitHub-CLI ab Januar 2026"],"pt":["Requer instalação via brew no macOS ou curl no Linux","Limitado à versão 2.85.0 da CLI do GitHub a partir de janeiro de 2026"],"ru":["Требует установки через brew на macOS или curl на Linux","Ограничен версией 2.85.0 GitHub CLI на январь 2026 года"],"ar":["يتطلب تثبيت عبر brew على macOS أو curl على Linux","محدود بالإصدار 2.85.0 من GitHub CLI اعتبارًا من يناير 2026"]},"version":3},"contentHash":"22d027a3219c487eefd4c7dae6e1a44b0ee8886aa5bdb9020c8886a2337c2fb4","qualityScore":80}');
