INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NeverSight/skills_feed/gh-cli', 'gh-cli', 'NeverSight', 'skills_feed', 'community', 'gh-cli NeverSight skills_feed community GitHub CLI（gh）是一种命令行工具，允许开发人员从命令行与GitHub合作。gh-cli是GitHub CLI的自动化脚本 GitHub CLI（gh）は、開発者がコマンドラインからGitHubと協力できるコマンドラインツールです。gh-cliはGitHub CLIの自動化スクリプトです GitHub CLI(gh)는 개발자가 명령줄에서 GitHub와 협력할 수 있는 명령줄 도구입니다. gh-cli는 GitHub CLI의 자동화 스크립트입니다 gh-cli es una herramienta de línea de comandos para interactuar con GitHub. Permite a los desarrolladores trabajar de manera eficiente con el platform. gh-cli est un outil de ligne de commande pour interagir avec GitHub. Il permet aux développeurs de travailler de manière efficace avec la plateforme. gh-cli ist ein Befehlszeilentool zum Interagieren mit GitHub. Es ermöglicht es Entwicklern, effizient mit der Plattform zu arbeiten. O GH CLI é uma ferramenta de linha de comando para interagir com o GitHub. Aprenda a instalá-lo e usá-lo para melhorar sua produtividade. GH CLI — это инструмент командной строки для взаимодействия с GitHub. Узнайте, как его установить и использовать для повышения производительности. GH CLI هي أداة سطر الأوامر للتفاعل مع جيت هاب. تعلم كيفية تثبيتها واستخدامها لتحسين إنتاجيتك. A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions. GitHub CLI gh-cli 命令行工具 自动化脚本 网络数据获取 开发者工具 A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions.');
